styles.css:
/* Punch App result screen: showcase.
   The glass is the machine's own: 1080 x 3840, portrait, no scrolling. The page shows the glass alone; the phone flow lives in mobile.css.
   Themes are complete visual worlds. Each one sets tokens and restyles a small set of shared building blocks
   (.surface, .surface-hi, .display, .label, .text, .strike-fill, .photo, .photo-frame, .badge),
   so every section design follows the theme. Red is the strike: the charge, replay progress and the primary action. */

/* ---------------------------------------------------------------- faces */
@font-face { font-family: "Big Shoulders Display"; src: url("fonts/big-shoulders-display-latin-800-normal.woff2") format("woff2"); font-weight: 800; font-display: swap; }
@font-face { font-family: "Big Shoulders Display"; src: url("fonts/big-shoulders-display-latin-900-normal.woff2") format("woff2"); font-weight: 900; font-display: swap; }
@font-face { font-family: "Barlow"; src: url("fonts/barlow-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Barlow"; src: url("fonts/barlow-latin-500-normal.woff2") format("woff2"); font-weight: 500; font-display: swap; }
@font-face { font-family: "Barlow"; src: url("fonts/barlow-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Barlow"; src: url("fonts/barlow-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Barlow Condensed"; src: url("fonts/barlow-condensed-latin-500-normal.woff2") format("woff2"); font-weight: 500; font-display: swap; }
@font-face { font-family: "Barlow Condensed"; src: url("fonts/barlow-condensed-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Barlow Condensed"; src: url("fonts/barlow-condensed-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Unbounded"; src: url("fonts/unbounded-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Unbounded"; src: url("fonts/unbounded-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Unbounded"; src: url("fonts/unbounded-latin-800-normal.woff2") format("woff2"); font-weight: 800; font-display: swap; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-500-normal.woff2") format("woff2"); font-weight: 500; font-display: swap; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Inter"; src: url("fonts/inter-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Anton"; src: url("fonts/anton-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Orbitron"; src: url("fonts/orbitron-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Orbitron"; src: url("fonts/orbitron-latin-900-normal.woff2") format("woff2"); font-weight: 900; font-display: swap; }
@font-face { font-family: "Chakra Petch"; src: url("fonts/chakra-petch-latin-500-normal.woff2") format("woff2"); font-weight: 500; font-display: swap; }
@font-face { font-family: "Chakra Petch"; src: url("fonts/chakra-petch-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Chakra Petch"; src: url("fonts/chakra-petch-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Sora"; src: url("fonts/sora-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }
@font-face { font-family: "Sora"; src: url("fonts/sora-latin-600-normal.woff2") format("woff2"); font-weight: 600; font-display: swap; }
@font-face { font-family: "Sora"; src: url("fonts/sora-latin-700-normal.woff2") format("woff2"); font-weight: 700; font-display: swap; }
@font-face { font-family: "Sora"; src: url("fonts/sora-latin-800-normal.woff2") format("woff2"); font-weight: 800; font-display: swap; }
@font-face { font-family: "Archivo Black"; src: url("fonts/archivo-black-latin-400-normal.woff2") format("woff2"); font-weight: 400; font-display: swap; }

/* ---------------------------------------------------------------- tokens: Arena, the default */
:root {
  /* live controls, written by app.js */
  --zoom: .4;
  --space: 1;
  --r: 20px;
  --accent-amt: 100;
  --glow: .4;
  --photo-sat: .35;
  --fit: 1;
  --gap-live: calc(64px * var(--space));

  /* The spacing scale. Every margin, padding and gap in this showcase is one of these steps: 2 to 12 in twos,
     fours to 48, then eights. A value that is not on the scale is a bug, not a decision — the design
     system page draws the whole ladder, and tools/check-spacing.py is the check that keeps it honest. */
  --s-2: 2px;  --s-4: 4px;  --s-6: 6px;  --s-8: 8px;
  --s-10: 10px;  --s-12: 12px;  --s-16: 16px;  --s-20: 20px;
  --s-24: 24px;  --s-28: 28px;  --s-32: 32px;  --s-36: 36px;
  --s-40: 40px;  --s-48: 48px;  --s-56: 56px;  --s-64: 64px;
  --s-72: 72px;  --s-80: 80px;  --s-88: 88px;  --s-96: 96px;
  --s-104: 104px;  --s-112: 112px;  --s-120: 120px;  --s-128: 128px;
  --s-144: 144px;  --s-160: 160px;  --s-176: 176px;  --s-192: 192px;

  /* type. Big numbers: font-size: min(calc(CAP_PX / var(--cap)), calc(100cqi / (CHARS * var(--num-w)))) */
  --f-display: "Big Shoulders Display", "Arial Narrow", sans-serif;
  --w-display: 900;
  --display-case: uppercase;
  --display-track: .01em;
  --display-glow: none;
  --num-w: .424;
  --cap: .8;
  --f-text: "Barlow", system-ui, sans-serif;
  --w-text: 500;
  --w-strong: 700;
  --f-label: "Barlow Condensed", "Arial Narrow", sans-serif;
  --w-label: 600;
  --label-track: .16em;

  /* screen */
  --accent: #EB1110;
  --ground: #0B0B0C;
  --raised: #151517;
  --raised-hi: #1F1F22;
  --badge: #1F1F22;
  --badge-ink: #F5F3EF;
  --line: rgba(255, 255, 255, .1);
  --ink-1: #F5F3EF;
  --ink-2: rgba(245, 243, 239, .72);
  --ink-3: rgba(245, 243, 239, .56);
  --track: rgba(255, 255, 255, .12);
  --strike-off: #F5F3EF;
  --cta-ink: #FFFFFF;
  --strike-glow: 0 0 0 transparent;
  --surface-bg: linear-gradient(180deg, #19191B, #131315);
  --surface-hi-bg: linear-gradient(180deg, #262629, #1B1B1E);
  --surface-border: 2px solid rgba(255, 255, 255, .09);
  --surface-hi-border: 2px solid rgba(255, 255, 255, .24);
  --surface-shadow: inset 0 2px 0 rgba(255, 255, 255, .04), 0 24px 48px -32px rgba(0, 0, 0, .9);
  --surface-filter: none;
  --photo-filter: saturate(var(--photo-sat)) contrast(1.1) brightness(.95);
  --screen-bg:
    radial-gradient(90% 26% at 50% 0%, rgba(255, 236, 214, .14), transparent 70%),
    radial-gradient(70% 18% at 50% 100%, rgba(235, 17, 16, .12), transparent 70%),
    linear-gradient(#101012, #09090A);

  /* derived */
  --strike: color-mix(in oklab, var(--accent) calc(var(--accent-amt) * 1%), var(--strike-off));
  --pad: calc(80px * var(--space));
  --pad-top: calc(88px * var(--space));
  --pad-bottom: calc(72px * var(--space));
  --gap-sec: calc(64px * var(--space));
  --gap-title: calc(28px * var(--space));
  --gap-grid: calc(20px * var(--space));
  --card-pad: calc(40px * var(--space));

  /* stage */
  --stage-bg: radial-gradient(60% 55% at 50% 18%, #34302C, #151413 62%, #0C0C0B);
  --stage-base: #0C0C0B;
  --shell-ink: #F2EFEA;
  --shell-mute: rgba(242, 239, 234, .64);
  --shell-pill: rgba(20, 19, 18, .72);
  --shell-pill-line: rgba(255, 255, 255, .12);
  --shell-pill-ink: rgba(242, 239, 234, .7);
  --shell-pill-hover: rgba(255, 255, 255, .06);
  --shell-pill-on: #F2EFEA;
  --shell-pill-on-ink: #141312;
  --bezel: #050505;
  --play-bg: #F5F3EF;
  --play-ink: #0B0B0C;

  --ref-card: #16090B;
  --ref-well: #050304;
  --ref-sponsor: #140A0A;
  --ref-ink: #FFFFFF;

  /* shell */
  --dock-bg: #F4F1EC;
  --dock-ink: #141312;
  --dock-mute: rgba(20, 19, 18, .64);
  --dock-sel: rgba(20, 19, 18, .08);
  --dock-line: rgba(20, 19, 18, .12);
  --dock-filter: none;
  --panel-bg: #FBF9F6;
  --panel-ink: #1A1614;
  --panel-mute: #6B635C;
  --panel-line: #E4DED6;
  --focus: #F2EFEA;
}

/* ---------------------------------------------------------------- Light: the same system on a daylight ground.
   Arena Light keeps every role (ink, surface, strike) and only turns the ground; red keeps its single job. */
:root[data-appearance="light"] {
  --ground: #F3F0EB;
  --raised: #FFFFFF;
  --raised-hi: #FFFFFF;
  --badge: color-mix(in oklab, var(--ink-1) 9%, var(--raised));
  --badge-ink: #151413;
  --line: rgba(21, 20, 19, .12);
  --ink-1: #151413;
  --ink-2: rgba(21, 20, 19, .74);
  --ink-3: rgba(21, 20, 19, .6);
  --track: rgba(21, 20, 19, .12);
  --strike-off: #151413;
  --accent: #E3100F;
  --surface-bg: linear-gradient(180deg, #FFFFFF, #FBF9F6);
  --surface-hi-bg: linear-gradient(180deg, #F7F3EE, #EFEAE3);
  --surface-border: 2px solid rgba(21, 20, 19, .08);
  --surface-hi-border: 2px solid rgba(21, 20, 19, .24);
  --surface-shadow: inset 0 2px 0 rgba(255, 255, 255, .9), 0 24px 48px -32px rgba(70, 45, 30, .35);
  --photo-filter: saturate(var(--photo-sat)) contrast(1.04);
  --screen-bg:
    radial-gradient(90% 26% at 50% 0%, rgba(235, 17, 16, .08), transparent 70%),
    radial-gradient(70% 18% at 50% 100%, rgba(235, 17, 16, .06), transparent 70%),
    linear-gradient(#F8F5F1, #EEEAE4);
  --stage-bg: radial-gradient(60% 55% at 50% 18%, #FFFFFF, #EEEAE4 62%, #E4DFD8);
  --stage-base: #E4DFD8;
  --shell-ink: #1A1614;
  --shell-mute: rgba(26, 22, 20, .64);
  --shell-pill: rgba(255, 255, 255, .72);
  --shell-pill-line: rgba(26, 22, 20, .12);
  --shell-pill-ink: rgba(26, 22, 20, .66);
  --shell-pill-hover: rgba(26, 22, 20, .06);
  --shell-pill-on: #1A1614;
  --shell-pill-on-ink: #F7F4EF;
  --bezel: #1A1614;
  --focus: #1A1614;
}

/* ---------------------------------------------------------------- base */
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html { background: var(--stage-base); }
body {
  margin: 0;
  min-height: 100vh;
  background: var(--stage-bg);
  background-color: var(--stage-base);
  background-attachment: fixed;
  color: var(--shell-ink);
  font: 500 15px/1.5 "Barlow", ui-sans-serif, system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}
button, input { font: inherit; color: inherit; }
p, h1, h2, figure { margin: 0; }
img { display: block; max-width: 100%; }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }

/* ---------------------------------------------------------------- shared building blocks for every design */
.surface {
  background: var(--surface-bg); border: var(--surface-border); border-radius: var(--r);
  box-shadow: var(--surface-shadow);
  -webkit-backdrop-filter: var(--surface-filter); backdrop-filter: var(--surface-filter);
}
.surface-hi {
  background: var(--surface-hi-bg); border: var(--surface-hi-border); border-radius: var(--r);
  box-shadow: var(--surface-shadow);
  -webkit-backdrop-filter: var(--surface-filter); backdrop-filter: var(--surface-filter);
}
.display {
  font-family: var(--f-display); font-weight: var(--w-display);
  text-transform: var(--display-case); letter-spacing: var(--display-track);
  text-shadow: var(--display-glow); line-height: .9; white-space: nowrap;
}
.label {
  font-family: var(--f-label); font-weight: var(--w-label); font-size: 28px; line-height: 1;
  letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-2);
}
.text { font-family: var(--f-text); font-weight: var(--w-text); font-size: 30px; line-height: 1.3; }
/* the glass reads from 1 m and more: nothing on the Result under 32 px (the shared classes stay as they are elsewhere) */
:where(#screen) .label, :where(#screen) .text { font-size: 32px; }
.strike-fill { background: var(--strike); color: var(--cta-ink); box-shadow: var(--strike-glow); }
.glass {
  background: linear-gradient(140deg, rgba(255, 255, 255, .22), rgba(255, 255, 255, .06)), rgba(18, 12, 20, .22);
  border: 2px solid rgba(255, 255, 255, .34); border-radius: var(--r);
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, .45), 0 30px 60px -30px rgba(0, 0, 0, .7);
  -webkit-backdrop-filter: blur(28px) saturate(1.5); backdrop-filter: blur(28px) saturate(1.5);
  color: #FFFFFF;
}
.photo { filter: var(--photo-filter); }
.photo-frame { position: relative; overflow: hidden; isolation: isolate; }
.photo-frame > img { width: 100%; height: 100%; object-fit: cover; }
.photo-frame::after { content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 1; border-radius: inherit; }

.badge { display: inline-grid; place-items: center; border-radius: 50%; flex: none; background: var(--badge); color: var(--badge-ink); }
.badge svg { width: 100%; height: 100%; display: block; overflow: visible; }
.badge-logo { width: 96px; height: 96px; background: var(--strike); color: #FFFFFF; box-shadow: var(--strike-glow); }
/* a chosen alternative logo replaces the badge with the full-colour mark */
[data-glyph="logo"][data-mark] { background: none !important; box-shadow: none !important; border-radius: 0 !important; }
[data-glyph="logo"][data-mark] img { width: 100%; height: 100%; object-fit: contain; display: block; }
.badge-rank { width: 100px; height: 100px; }
.badge-stat { width: 72px; height: 72px; }
/* One line weight for every line icon on the glass, 3 glass px. The glyph box is 40 units wide, so a badge of
   size S draws stroke-width 3 x 40 / S; the section files restate it for their own badge sizes. */
.badge-rank svg g { stroke-width: 1.2; }
.badge-stat svg g { stroke-width: 1.67; }
.badge-play { width: 140px; height: 140px; background: var(--play-bg); color: var(--play-ink); }

/* ---------------------------------------------------------------- loader
   Round eleven: the first thing the showcase shows is the mark, a bar and one line of type. Nothing else. */
.loader {
  --ld-ink: var(--shell-ink);
  --ld-mute: var(--shell-mute);
  --ld-line: color-mix(in oklab, var(--shell-ink) 16%, transparent);
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-items: center; padding: 24px 16px;
  background: var(--stage-bg); background-color: var(--stage-base);
  transition: opacity .42s ease, visibility 0s linear .42s;
  animation: loader-failsafe 0s linear 9s forwards;
}
.loader.is-done { opacity: 0; visibility: hidden; }
@keyframes loader-failsafe { to { opacity: 0; visibility: hidden; } }
.ld { display: grid; justify-items: center; gap: 28px; width: min(320px, 78vw); }
.ld-lock { display: flex; align-items: center; gap: 16px; }
.ld-mark { width: 42px; height: 42px; object-fit: contain; }
.ld-word { width: 158px; height: auto; }
.ld-on-light { display: none; }
:root[data-appearance="light"] .ld-on-dark { display: none; }
:root[data-appearance="light"] .ld-on-light { display: block; }
.ld-bar { display: block; width: 100%; height: 4px; border-radius: 2px; background: var(--ld-line); overflow: hidden; }
.ld-bar i { display: block; height: 100%; border-radius: inherit; background: var(--strike); transform-origin: 0 50%; transform: scaleX(var(--lp, 0)); transition: transform .12s linear; }
.loader.is-still .ld-bar i { transform: scaleX(1); }
.loader-note {
  font: var(--w-label) 12px/1 var(--f-label); letter-spacing: max(var(--label-track), .08em); text-transform: uppercase;
  color: var(--ld-mute);
}

/* ---------------------------------------------------------------- top bar */
/* Three columns: the crumb, the mode switch centred on the page, the actions. The outer columns never shrink below
   their content, so when room runs short the switch moves aside instead of sliding over a neighbour. Narrower screens
   drop words in steps (the subtitle, the long labels, the title) and, under 800 px, move the switch onto its own row.
   Its height keeps to what the stages leave for it: 96 px, 140 px under 960 and 124 px under 720. */
.topbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 30;
  display: grid; grid-template-columns: minmax(max-content, 1fr) auto minmax(max-content, 1fr);
  align-items: center; column-gap: 16px; row-gap: 10px;
  padding: 20px 24px; pointer-events: none;
}
.topbar > * { pointer-events: auto; }
/* once the page scrolls, the bar takes the page's own ground, so nothing reads through it */
.topbar.is-scrolled { pointer-events: auto; background: var(--stage-bg); background-color: var(--stage-base); background-attachment: fixed; }
.topbar.is-scrolled::after {
  content: ""; position: absolute; left: 0; right: 0; top: 100%; height: 22px; pointer-events: none;
  background: var(--stage-bg); background-color: var(--stage-base); background-attachment: fixed;
  -webkit-mask-image: linear-gradient(#000, transparent); mask-image: linear-gradient(#000, transparent);
}
.topactions { justify-self: end; }
.crumb { display: flex; align-items: center; gap: 20px; min-width: 0; }
.crumb-logo { flex: none; width: 104px; height: auto; }
.crumb-logo.on-light { display: none; }
:root[data-appearance="light"] .crumb-logo.on-dark { display: none; }
:root[data-appearance="light"] .crumb-logo.on-light { display: block; }
.crumb-text { display: grid; gap: 4px; min-width: 0; }
.crumb b { font: 700 15px/1.1 "Barlow", sans-serif; color: var(--shell-ink); white-space: nowrap; }
.crumb-text > span { font: 500 12.5px/1.3 "Barlow", sans-serif; color: var(--shell-mute); max-width: 42ch; }

/* the brief, beside the title */
.crumb-title { display: flex; align-items: center; gap: 10px; }
.briefbtn {
  appearance: none; border: 0; cursor: pointer; flex: none; height: 26px; padding: 0 10px 0 8px; border-radius: 8px;
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--shell-pill); color: var(--shell-ink);
  box-shadow: inset 0 0 0 1px var(--shell-pill-line);
  font: 700 12.5px/1 "Barlow", sans-serif; white-space: nowrap;
  transition: background-color .2s ease;
}
.briefbtn:hover { background: var(--shell-pill-hover); }
.briefbtn[aria-expanded="true"] { background: var(--shell-pill-on); color: var(--shell-pill-on-ink); }

/* machine or phone */
.modes {
  display: flex; gap: 8px; padding: 4px; border-radius: 15px;
  background: var(--shell-pill); box-shadow: inset 0 0 0 1px var(--shell-pill-line), 0 14px 28px -18px rgba(0, 0, 0, .5);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
}
.mode {
  appearance: none; border: 0; cursor: pointer; height: 38px; padding: 0 16px 0 12px; border-radius: 11px;
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; color: var(--shell-pill-ink);
  font: 700 14px/1 "Barlow", sans-serif; white-space: nowrap;
  transition: background-color .2s ease, color .2s ease;
}
.mode:hover { color: var(--shell-ink); background: var(--shell-pill-hover); }
.mode[aria-pressed="true"] { background: var(--shell-pill-on); color: var(--shell-pill-on-ink); }
.mode:focus-visible { outline: 2px solid var(--shell-ink); outline-offset: 2px; }
.mode .short { display: none; }

.iconbtn {
  appearance: none; border: 0; cursor: pointer;
  height: 46px; min-width: 46px; padding: 0 16px 0 16px; border-radius: 14px;
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  background: var(--dock-bg); color: var(--dock-ink);
  -webkit-backdrop-filter: var(--dock-filter); backdrop-filter: var(--dock-filter);
  box-shadow: 0 10px 24px -14px rgba(0, 0, 0, .55), 0 0 0 1px var(--dock-line);
  font: 700 14px/1 "Barlow", sans-serif;
  transition: transform .2s ease;
}
.iconbtn:hover { transform: translateY(-1px); }
.iconbtn[aria-expanded="true"] { background: var(--dock-ink); color: var(--dock-bg); }

.iconbtn.small { height: 36px; min-width: 36px; padding: 0; border-radius: 10px; box-shadow: none; background: transparent; color: inherit; -webkit-backdrop-filter: none; backdrop-filter: none; }
.iconbtn.small:hover { background: color-mix(in oklab, currentColor 8%, transparent); transform: none; }

/* ---------------------------------------------------------------- stage and the machine */
.stage {
  position: relative;
  min-height: 100vh;
  display: flex; flex-direction: column; align-items: safe center;
  padding: 96px 16px 96px;
  transition: padding .45s cubic-bezier(.2, .7, .2, 1);
}
.machine { zoom: var(--zoom); flex: none; width: 1080px; }

/* the glass: exactly the machine's 1080 x 3840 */
.screen {
  position: relative; isolation: isolate; overflow: hidden;
  width: 1080px; height: 3840px; flex: none;
  background: var(--screen-bg);
  color: var(--ink-1);
  border-radius: 12px;
  box-shadow: 0 0 0 6px var(--bezel), 0 0 0 8px color-mix(in oklab, var(--shell-ink) 10%, transparent), 0 80px 160px -60px rgba(0, 0, 0, .7);
}

.screen-scene { position: absolute; inset: 0; z-index: 0; pointer-events: none; }

.screen-fx { position: absolute; inset: 0; z-index: 3; pointer-events: none; }

/* the content column is fitted to the glass by app.js: gaps grow to fill it, or the whole column scales down */
.screen-content {
  position: relative; z-index: 1;
  zoom: var(--fit);
  width: calc(1080px / var(--fit)); height: calc(3840px / var(--fit));
  display: flex; flex-direction: column; gap: var(--gap-live);
  padding: var(--pad-top) var(--pad) var(--pad-bottom);
  transition: gap .35s ease;
}
.screen-content.is-measuring { height: auto; transition: none; }
.screen-content:not(.is-measuring) > .sec.is-last { margin-top: auto; }
.screen .sec { position: relative; }
.screen [data-qr] { cursor: pointer; }

/* the glow behind the score, strength from the Light glow control */
.spot { position: absolute; left: 50%; pointer-events: none; z-index: 0; transform: translateX(-50%); border-radius: 50%; }
.spot-top {
  top: -260px; width: 1300px; height: 900px;
  background: radial-gradient(closest-side, var(--accent), transparent);
  opacity: calc(var(--glow) * .45 * var(--accent-amt) / 100);
  filter: blur(40px);
}
.spot-mid { display: none; }

:root[data-appearance="light"] .spot-top { opacity: calc(var(--glow) * .16 * var(--accent-amt) / 100); }
.s-header .v-a { display: flex; align-items: center; justify-content: center; gap: 28px; }
.wordmark { font: var(--w-display) 96px/.9 var(--f-display); letter-spacing: var(--display-track); text-transform: var(--display-case); text-shadow: var(--display-glow); white-space: nowrap; }
.wordmark span { color: var(--ink-3); }

.s-hero .v-a { container-type: inline-size; display: grid; justify-items: center; gap: calc(28px * var(--space)); padding-block: calc(16px * var(--space)); text-align: center; }
.hero-label { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-2); }
.hero-score {
  font: var(--w-display) 200px/.9 var(--f-display); letter-spacing: var(--display-track); text-transform: var(--display-case); text-shadow: var(--display-glow);
  font-size: min(calc(210px / var(--cap)), calc(100cqi / (var(--score-chars, 9.8) * var(--num-w))));
  white-space: nowrap; font-variant-numeric: tabular-nums;
}
.charge { position: relative; width: 100%; height: 16px; border-radius: 8px; background: var(--track); }
.charge-fill {
  position: absolute; left: 0; top: 0; bottom: 0; width: 100%;
  background: var(--strike); box-shadow: var(--strike-glow); border-radius: inherit;
  transform-origin: 0 50%; transform: scaleX(var(--charge, 1));
}
.hero-grade { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-2); }

.s-title { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-2); margin-bottom: var(--gap-title); }
.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid); }
.card {
  background: var(--surface-bg); border: var(--surface-border); border-radius: var(--r);
  box-shadow: var(--surface-shadow);
  -webkit-backdrop-filter: var(--surface-filter); backdrop-filter: var(--surface-filter);
  padding: var(--card-pad);
}
.k { font: var(--w-text) 32px/1.2 var(--f-text); color: var(--ink-2); white-space: nowrap; }
.rank { display: flex; align-items: center; gap: 28px; }
.rank > div { display: grid; gap: 10px; min-width: 0; flex: 1; container-type: inline-size; }
.rank .k { font-size: 32px; }
.rank .v {
  font: var(--w-display) 80px/.9 var(--f-display); letter-spacing: var(--display-track); text-shadow: var(--display-glow);
  font-size: min(calc(56px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(100cqi / (max(6.2, var(--rank-chars, 6.2)) * var(--num-w))));
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.rank.is-key { background: var(--surface-hi-bg); border: var(--surface-hi-border); }
.rank.is-key .k { color: var(--ink-1); }
.stat { display: grid; gap: 24px; container-type: inline-size; }
.stat-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.stat .v {
  font: var(--w-display) 96px/.9 var(--f-display); letter-spacing: var(--display-track); text-shadow: var(--display-glow);
  font-size: min(calc(70px / var(--cap)), calc(100cqi / (7.6 * var(--num-w))));
  display: flex; align-items: baseline; gap: 16px; white-space: nowrap;
}
.stat .v small { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: .08em; color: var(--ink-3); text-shadow: none; }

.player { position: relative; aspect-ratio: 920 / 560; border-radius: var(--r); overflow: hidden; background: #000; border: var(--surface-border); box-shadow: var(--surface-shadow); }
.poster { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .62; }
.player-center { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 24px; z-index: 2; }
.player-cap { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: #FFFFFF; text-shadow: 0 2px 16px rgba(0, 0, 0, .6); }
.timeline { position: absolute; left: 0; right: 0; bottom: 0; z-index: 2; padding: 28px var(--card-pad) 32px; display: grid; gap: 20px; background: linear-gradient(to top, rgba(0, 0, 0, .8), rgba(0, 0, 0, 0)); }
.time-row { display: flex; justify-content: space-between; font: 500 32px/1 var(--f-text); color: rgba(255, 255, 255, .86); font-variant-numeric: tabular-nums; }
.time-row b { font: var(--w-label) 32px/1 var(--f-label); color: #FFFFFF; letter-spacing: var(--label-track); text-transform: uppercase; }
.track { height: 10px; border-radius: 5px; background: rgba(255, 255, 255, .22); overflow: hidden; }
.progress { display: block; height: 100%; width: calc(100% / 3); background: var(--strike); box-shadow: var(--strike-glow); border-radius: inherit; }

.thumbs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--gap-grid); }
.thumb { display: grid; gap: 20px; }
.thumb img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: calc(var(--r) * .7); background: var(--raised); }
.thumb figcaption { font: var(--w-strong) 32px/1.2 var(--f-text); color: var(--ink-1); }

.boxer { border-radius: var(--r); aspect-ratio: 920 / 420; background: var(--raised); border: var(--surface-border); box-shadow: var(--surface-shadow); }

.s-cta .v-a { display: grid; }
.cta {
  display: grid; place-items: center; min-height: 168px; border-radius: var(--r);
  background: var(--strike); color: var(--cta-ink); box-shadow: var(--strike-glow);
  font: var(--w-display) 76px/1 var(--f-display); letter-spacing: .04em; text-transform: uppercase;
}

.s-sponsor .v-a {
  display: flex; align-items: center; justify-content: center; gap: 20px;
  padding-top: calc(36px * var(--space)); border-top: 2px solid var(--line);
}
.s-sponsor .v-a span { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-3); }
.s-sponsor .v-a b { font: var(--w-display) 44px/1 var(--f-display); letter-spacing: .03em; color: var(--ink-2); }

/* ---------------------------------------------------------------- section designs: switching */
.vars { position: relative; }
.vars.is-switching { overflow: clip; overflow-clip-margin: calc(40px * var(--space)); transition: height .42s cubic-bezier(.2, .7, .2, 1); }
.var { min-width: 0; }
.sec.is-target { outline: 6px dashed color-mix(in oklab, var(--ink-1) 45%, transparent); outline-offset: calc(22px * var(--space)); border-radius: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* ---------------------------------------------------------------- reveal */
.is-revealing .screen-content > .sec { animation: rise .8s cubic-bezier(.2, .7, .2, 1) both; animation-delay: calc(var(--i, 0) * 70ms); }
@keyframes rise { from { opacity: 0; transform: translateY(40px); } }

/* ---------------------------------------------------------------- top bar buttons */
.topactions { display: flex; align-items: center; gap: 10px; flex: none; }
.topbtn, .iconbtn, .briefbtn, .mode { flex: none; white-space: nowrap; }
.topbtn .ico, .iconbtn .ico, .briefbtn .ico, .mode .ico { flex: none; }
.topbtn {
  appearance: none; cursor: pointer; height: 46px; padding: 0 16px; border-radius: 14px;
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; color: var(--shell-ink);
  border: 1px solid color-mix(in oklab, var(--shell-ink) 26%, transparent);
  font: 700 14px/1 "Barlow", sans-serif;
  transition: background-color .2s ease, border-color .2s ease;
}
.topbtn:hover { background: color-mix(in oklab, var(--shell-ink) 8%, transparent); border-color: color-mix(in oklab, var(--shell-ink) 45%, transparent); }
.topbtn svg { transition: transform .2s ease; }
.topbtn:hover svg { transform: translateX(2px); }
.case-short { display: none; }

/* ---------------------------------------------------------------- settings panel */
.custom {
  /* starts under the top bar so Customise itself stays clickable, and stops well clear of the bottom right,
     where the host drops its own badge over whatever is there */
  position: fixed; top: calc(var(--topbar-h, 82px) - 12px); right: 12px; bottom: 72px; z-index: 40;
  width: min(460px, calc(100vw - 24px));
  display: flex; flex-direction: column;
  background: var(--panel-bg); color: var(--panel-ink);
  --focus: var(--panel-ink);
  --panel-r: 24px;
  border-radius: var(--panel-r);
  box-shadow: 0 30px 70px -30px rgba(0, 0, 0, .6), 0 0 0 1px var(--panel-line);
  transform: translateX(calc(100% + 24px));
  transition: transform .45s cubic-bezier(.2, .7, .2, 1);
}
.custom.is-open { transform: none; }
.custom-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 24px 20px 20px 28px; border-bottom: 1px solid var(--panel-line); }
.custom-head h2 { font: 900 30px/1 "Big Shoulders Display", sans-serif; letter-spacing: .02em; text-transform: uppercase; }
.custom-sub { margin: 6px 0 0; font: 500 14px/1.4 "Barlow", sans-serif; color: var(--panel-mute); }
.custom-body { overflow-y: auto; padding: 8px 28px 28px; background: var(--panel-bg); font-family: "Barlow", sans-serif; }
.pgroup { padding: 24px 0 24px; border-bottom: 1px solid var(--panel-line); }
.pgroup:last-of-type { border-bottom: 0; }
.group-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 16px; }
.group { font: 700 13px/1 "Barlow Condensed", sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--panel-mute); margin: 0; }
.group-head .group { margin: 0; }
.linkbtns { display: flex; gap: 4px; }
.linkbtn {
  appearance: none; border: 0; cursor: pointer; padding: 6px 10px; border-radius: 8px; background: transparent;
  font: 700 13px/1 "Barlow", sans-serif; color: var(--panel-ink);
}
.linkbtn:hover { background: color-mix(in oklab, var(--panel-ink) 7%, transparent); }
.linkbtn:disabled { opacity: .35; cursor: not-allowed; background: transparent; }

/* theme tiles */
.themes { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.theme-tile {
  appearance: none; cursor: pointer; text-align: left; padding: 10px; border-radius: 16px;
  display: grid; gap: 12px;
  background: #FFFFFF; color: var(--panel-ink); border: 2px solid var(--panel-line);
  transition: border-color .15s ease, box-shadow .15s ease;
}
.theme-tile:hover { border-color: color-mix(in oklab, var(--panel-ink) 30%, transparent); }
.theme-tile[aria-checked="true"] { border-color: var(--panel-ink); box-shadow: 0 10px 24px -16px rgba(0, 0, 0, .45); }
.theme-tile:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 3px; }
.theme-prev { position: relative; height: 92px; border-radius: 10px; overflow: hidden; display: grid; place-items: center; }
.theme-prev.arena { background: radial-gradient(90% 60% at 50% 0%, rgba(255, 236, 214, .22), transparent 70%), #0E0E10; }
.theme-prev span { font: 900 38px/1 "Big Shoulders Display", sans-serif; letter-spacing: .02em; text-transform: uppercase; color: #F5F3EF; }
.theme-prev::after { content: ""; position: absolute; left: 18%; right: 18%; bottom: 16px; height: 6px; border-radius: 3px; background: #EB1110; }
.theme-txt { display: grid; gap: 4px; padding: 0 4px 2px; }
.theme-txt b { font: 700 16px/1.1 "Barlow", sans-serif; }
.theme-txt i { font: 500 13px/1.35 "Barlow", sans-serif; font-style: normal; color: var(--panel-mute); }
.theme-tile .check {
  position: absolute; top: 18px; right: 18px; width: 22px; height: 22px; border-radius: 50%;
  display: grid; place-items: center; background: var(--panel-ink); color: #FFFFFF; opacity: 0; transition: opacity .15s ease;
}
.theme-tile { position: relative; }
.theme-tile[aria-checked="true"] .check { opacity: 1; }

/* logo marks */
.group-note { font: 600 13px/1 "Barlow", sans-serif; color: var(--panel-mute); }
.logos { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.logo-tile {
  appearance: none; cursor: pointer; position: relative; padding: 8px 6px 10px; border-radius: 14px;
  display: grid; justify-items: center; gap: 8px;
  background: #FFFFFF; border: 2px solid var(--panel-line); color: var(--panel-ink);
  font: 600 12px/1.1 "Barlow", sans-serif; text-align: center;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.logo-tile:hover { border-color: color-mix(in oklab, var(--panel-ink) 30%, transparent); }
.logo-tile[aria-checked="true"] { border-color: var(--panel-ink); box-shadow: 0 8px 18px -12px rgba(0, 0, 0, .5); }
.logo-tile:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 3px; }
.logo-prev { display: grid; place-items: center; width: 100%; aspect-ratio: 16 / 11; border-radius: 10px; background: #0E0E10; }
.logo-prev img { width: 58%; height: 58%; object-fit: contain; }

/* device tiles */
.dev-prev { display: grid; place-items: center; height: 92px; border-radius: 10px; background: radial-gradient(70% 80% at 50% 20%, rgba(235, 17, 16, .35), transparent 70%), #0E0E10; }
.dev-phone { position: relative; width: 38px; height: 76px; border-radius: 9px; background: #060606; box-shadow: 0 0 0 2px #4A4D54, 0 0 0 3px #17181B; }
.dev-phone i { position: absolute; left: 50%; top: 4px; width: 14px; height: 4px; border-radius: 2px; background: #000; transform: translateX(-50%); box-shadow: 0 0 0 1px #222; }
.dev-phone.android { border-radius: 6px; width: 36px; height: 74px; box-shadow: 0 0 0 2px #2F3136, 0 0 0 3px #111; }
.dev-phone.android i { width: 4px; height: 4px; border-radius: 50%; }

/* controls */
.ctl { display: grid; grid-template-columns: 1fr auto; align-items: baseline; row-gap: 10px; margin-bottom: 20px; }
.ctl:last-child { margin-bottom: 0; }
.ctl label { font: 700 15px/1.2 "Barlow", sans-serif; }
.ctl output { font: 600 14px/1.2 "Barlow", sans-serif; color: var(--panel-mute); font-variant-numeric: tabular-nums; }
.ctl input[type="range"] { grid-column: 1 / -1; }
.ctl .ctl-help { grid-column: 1 / -1; margin: -2px 0 0; font: 500 13px/1.4 "Barlow", sans-serif; color: var(--panel-mute); }
/* a locked control dims its track, while its name and "as designed" stay readable: they are the explanation */
.ctl.is-locked input { opacity: .4; cursor: not-allowed; }
.ctl.is-locked label { color: var(--panel-mute); }
.lock-note, .fit-note { margin: 0 0 16px; padding: 12px 16px; border-radius: 12px; background: color-mix(in oklab, var(--panel-ink) 5%, transparent); font: 500 14px/1.45 "Barlow", sans-serif; color: var(--panel-ink); }
.lock-note { margin: 16px 0 0; }
.fit-note { display: flex; gap: 10px; align-items: flex-start; }
.fit-note::before { content: ""; flex: none; width: 8px; height: 8px; margin-top: 6px; border-radius: 50%; background: #1F9D55; }
.fit-note.is-scaled::before { background: #C97A00; }

input[type="range"] { -webkit-appearance: none; appearance: none; width: 100%; height: 24px; margin: 0; background: transparent; cursor: pointer; }
input[type="range"]::-webkit-slider-runnable-track { height: 6px; border-radius: 3px; background: linear-gradient(to right, var(--panel-ink) 0 var(--fill, 50%), var(--panel-line) var(--fill, 50%) 100%); }
input[type="range"]::-moz-range-track { height: 6px; border-radius: 3px; background: var(--panel-line); }
input[type="range"]::-moz-range-progress { height: 6px; border-radius: 3px; background: var(--panel-ink); }
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 20px; height: 20px; margin-top: -8px; border-radius: 50%; background: var(--panel-bg); border: 2px solid var(--panel-ink); box-shadow: 0 2px 6px rgba(0, 0, 0, .18); }
input[type="range"]::-moz-range-thumb { width: 16px; height: 16px; border-radius: 50%; background: var(--panel-bg); border: 2px solid var(--panel-ink); }
input[type="range"]:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 4px; border-radius: 4px; }

.seg { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 4px; border-radius: 12px; background: color-mix(in oklab, var(--panel-ink) 6%, transparent); margin-bottom: 20px; }
.seg button { appearance: none; border: 0; cursor: pointer; padding: 10px 8px; border-radius: 9px; background: transparent; font: 700 14px/1 "Barlow", sans-serif; color: var(--panel-mute); }
.seg button:hover { color: var(--panel-ink); }
.seg button[aria-pressed="true"] { background: #FFFFFF; color: var(--panel-ink); box-shadow: 0 2px 8px -3px rgba(0, 0, 0, .25); }
.seg button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.seg-appearance { margin: 12px 0 0; }
.ctl-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 16px; }
.ctl-label { font: 700 15px/1.2 "Barlow", sans-serif; }
.seg-inline { margin: 0; flex: none; min-width: 230px; }

.replay {
  appearance: none; cursor: pointer; width: 100%; min-height: 44px; margin: -4px 0 24px; padding: 12px; border-radius: 12px;
  display: flex; align-items: center; justify-content: center; gap: 8px;
  border: 1px solid var(--panel-line); background: #FFFFFF;
  font: 700 14px/1 "Barlow", sans-serif; color: var(--panel-ink);
}
.replay:hover { border-color: color-mix(in oklab, var(--panel-ink) 35%, transparent); }
.sec-rows + .replay { margin: 10px 0 0; }

/* fine tuning, folded away */
.more { border-top: 1px solid var(--panel-line); }
.more summary {
  list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between;
  padding: 20px 0; font: 700 13px/1 "Barlow Condensed", sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--panel-mute);
}
.more summary::-webkit-details-marker { display: none; }
.more summary::after { content: ""; width: 9px; height: 9px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg) translateY(-3px); transition: transform .2s ease; }
.more[open] summary::after { transform: rotate(-135deg) translateY(-2px); }
.more summary:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 2px; border-radius: 6px; }
.more-body { padding-bottom: 8px; }

/* the last thing in the panel, flush to its edges: its bottom corners are the panel's own, and a rule on top
   separates it from the body rather than a box drawn around it */
.resetall {
  appearance: none; cursor: pointer; width: 100%; margin-top: 0; padding: 16px;
  border: 0; border-top: 1px solid var(--panel-line);
  border-radius: 0 0 var(--panel-r) var(--panel-r);
  background: transparent;
  font: 700 14px/1 "Barlow", sans-serif; color: var(--panel-ink);
}
.resetall:hover { background: color-mix(in oklab, var(--panel-ink) 5%, transparent); }

/* one row per section: show or hide, the design name and dots, previous and next */
.sec-rows { display: grid; gap: 8px; }
.sec-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 16px;
  padding: 10px 10px 10px 16px; border-radius: 14px; border: 1px solid var(--panel-line); background: #FFFFFF;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.sec-row.is-plain { grid-template-columns: minmax(0, 1fr) auto; padding-left: 16px; }
.sec-row:hover, .sec-row:focus-within { border-color: color-mix(in oklab, var(--panel-ink) 35%, transparent); box-shadow: 0 6px 16px -10px rgba(0, 0, 0, .3); }
.sec-row.is-off .sec-meta { opacity: .45; }
.sec-meta { display: grid; gap: 6px; min-width: 0; }
.sec-name { font: 700 12px/1 "Barlow Condensed", sans-serif; letter-spacing: .14em; text-transform: uppercase; color: var(--panel-mute); }
/* the dots step under the name when both do not fit, so a design's name is never cut */
.sec-design { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; min-width: 0; }
.sec-design b { font: 700 16px/1.15 "Barlow", sans-serif; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sec-dots { display: flex; gap: 4px; flex: none; }
.sec-dots i { width: 6px; height: 6px; border-radius: 50%; background: var(--panel-line); }
.sec-dots i.on { background: var(--panel-ink); }
.sec-arrows { display: flex; gap: 6px; }
.sec-btn {
  appearance: none; border: 0; cursor: pointer; width: 40px; height: 40px; border-radius: 11px;
  display: grid; place-items: center; background: color-mix(in oklab, var(--panel-ink) 6%, transparent); color: var(--panel-ink);
}
.sec-btn:hover { background: color-mix(in oklab, var(--panel-ink) 12%, transparent); }
.sec-btn:disabled { opacity: .3; cursor: not-allowed; }
.sec-btn:focus-visible { outline-offset: -2px; }
.eye {
  -webkit-appearance: none; appearance: none; cursor: pointer; margin: 0; flex: none;
  width: 38px; height: 22px; border-radius: 11px; background: #8F877F; position: relative; transition: background-color .2s ease;
}
.eye::after { content: ""; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #FFFFFF; box-shadow: 0 1px 3px rgba(0, 0, 0, .25); transition: transform .2s ease; }
.eye:checked { background: var(--panel-ink); }
.eye:checked::after { transform: translateX(16px); }
.eye:disabled { opacity: .35; cursor: not-allowed; }
.eye:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 3px; }
.eye-spacer { display: block; width: 38px; }

/* the panel opens under the top bar, so the bar keeps its full width. From 1180 px the stage makes room for it;
   narrower, it lies over the page, which goes quiet behind a veil until the panel closes */
@media (min-width: 1180px) {
  body.custom-open .stage, body.custom-open .phone-stage { padding-right: 488px; }
}
.custom-scrim {
  position: fixed; inset: 0; z-index: 25;
  background: color-mix(in oklab, var(--stage-base) 72%, transparent);
  opacity: 0; transition: opacity .3s ease;
}
.custom-scrim.is-on { opacity: 1; }
@media (min-width: 1180px) { .custom-scrim { display: none; } }

/* the top bar, one step at a time as the window narrows */
@media (min-width: 1380px) { .topbar { padding-block: 16px; } }
@media (max-width: 1379px) { .crumb-text > span { display: none; } }
@media (min-width: 961px) and (max-width: 1199px) {
  .mode .long, .case-long { display: none; }
  .mode .short, .case-short { display: inline; }
}
@media (min-width: 961px) and (max-width: 1059px) {
  .crumb-title b { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
}
@media (max-width: 960px) {
  .topbar { grid-template-columns: minmax(max-content, 1fr) auto; }
  .modes { grid-row: 2; grid-column: 1 / -1; justify-self: center; }
  .stage { padding-top: 128px; }
}
@media (max-width: 800px) {
  .topbar { padding: 10px 12px; }
  .crumb { gap: 12px; }
  .crumb-logo { width: 78px; }
  .crumb b { font-size: 13px; }
}

/* ---------------------------------------------------------------- small screens */
@media (max-width: 720px) {
  .briefbtn span { display: none; }
  .mode .long { display: none; }
  .mode .short { display: inline; }
  .mode { padding: 0 12px 0 10px; gap: 6px; }
  .briefbtn { padding: 0 10px; }
  .topactions { gap: 6px; }
  .iconbtn .btn-label { display: none; }
  .topbtn { padding: 0 12px; }
  .case-long { display: none; }
  .case-short { display: inline; }
  .stage { padding: 128px 12px 40px; }
  .custom { right: 8px; bottom: 8px; width: calc(100vw - 16px); }
  .custom-body { padding: 4px 20px 24px; }
  .custom-head { padding: 20px 16px 16px 20px; }
}
/* the Robotenc logo already names the client, so the title steps back for screen readers only */
@media (max-width: 520px) {
  .crumb-title b { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
}
@media (max-width: 359px) {
  .crumb-logo { width: 64px; }
  .topactions { gap: 4px; }
  .topbtn { padding: 0 10px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-delay: 0s !important; }
  .loader { animation-delay: 9s !important; animation-duration: 0s !important; }
  /* the loader is one still that fades: the rest of the page's motion is off, the fade is kept */
  .loader { transition-duration: .42s, 0s !important; transition-delay: 0s, .42s !important; }
}

/* ---------------------------------------------------------------- the machine flow: six screens around the result
   Each is the glass itself (1080 x 3840) drawn in the same tokens, so the appearance applies.
   Their own layouts live in mscreens/KEY.css; this sets the frame they share. */
.mpagebar { margin: 0 auto 24px; }
/* seven screens do not fit one row on a phone: wrap into two centred rows rather than scroll the current one out of sight */
@media (max-width: 730px) {
  .pagebar.mpagebar { flex-wrap: wrap; justify-content: center; overflow: visible; border-radius: 24px; row-gap: 4px; }
  .pagebar.mpagebar button { padding: 0 12px; }
}
.mscreen {
  /* the parts every flow screen shares, drawn once here so the six can never drift apart */
  --ms-brand-top: 100px;
  --ms-brand-h: 124.42px;
  --ms-ad-h: 140px;
  --ms-ground: var(--screen-bg);
  --ms-light: rgba(255, 226, 196, .12);
  --ms-light-2: color-mix(in oklab, var(--strike) 14%, transparent);
  --ms-photo-r: var(--r);
  --ms-photo-edge: inset 0 0 0 2px rgba(255, 255, 255, .06);

  position: relative; isolation: isolate; overflow: hidden;
  width: 1080px; height: 3840px; flex: none;
  background: var(--ms-ground); color: var(--ink-1);
  border-radius: 12px;
  box-shadow: 0 0 0 6px var(--bezel), 0 0 0 8px color-mix(in oklab, var(--shell-ink) 10%, transparent), 0 80px 160px -60px rgba(0, 0, 0, .7);
}
:root[data-appearance="light"] .mscreen {
  --ms-light: rgba(255, 170, 120, .18);
  --ms-light-2: color-mix(in oklab, var(--strike) 8%, transparent);
  --ms-photo-edge: none;
}

/* the backdrop host .ms-lights and its six shapes are drawn in mscreens/_backdrops.css, one look per html[data-mbackdrop] */

/* the logo lockup: the chosen mark and the PunchApp wordmark, centred, top-aligned as the frames draw it */
.mscreen .ms-brand {
  position: absolute; z-index: 2; top: var(--ms-brand-top); left: 0; right: 0; height: var(--ms-brand-h); margin: 0;
  display: flex; justify-content: center; align-items: flex-start; gap: 24px;
  pointer-events: none;
}
.mscreen .ms-mark { flex: none; width: 118px; height: var(--ms-brand-h); object-fit: contain; }
.mscreen .ms-word { flex: none; width: 452px; height: 98.36px; }
.mscreen .ms-on-light { display: none; }
:root[data-appearance="light"] .mscreen .ms-on-dark { display: none; }
:root[data-appearance="light"] .mscreen .ms-on-light { display: block; }

/* the photo card: 40 px in from each side (each screen's own column), its corners and edge from the look */
.mscreen .ms-photo { border-radius: var(--ms-photo-r); background: #0B0B0C; }
.mscreen .ms-photo::after { box-shadow: var(--ms-photo-edge); }

/* the sponsor slot .ms-ad is drawn in mscreens/_ads.css */

/* reduced motion on the glass: the page-wide rule turns every change into a .01ms transition (transition-property
   defaults to all), so a script that sets a size and measures in the same frame reads the size from before, and the
   Rollover reels ran past the glass. Nothing on the glass needs a transition to end, so they are off here outright. */
@media (prefers-reduced-motion: reduce) {
  .machine, .machine *, .machine *::before, .machine *::after { transition-duration: 0s !important; transition-delay: 0s !important; }
}

/* embedded beside the phone: only the glass, sized to its frame, no shell around it */
:root[data-embed="machine"] body { min-height: 0; overflow: hidden; background: transparent; }
:root[data-embed="machine"] .topbar,
:root[data-embed="machine"] .loader,
:root[data-embed="machine"] .mpagebar,
:root[data-embed="machine"] .custom,
:root[data-embed="machine"] .panel-veil,
:root[data-embed="machine"] .brief,
:root[data-embed="machine"] .case { display: none !important; }
/* the host injects its own badge into every HTML response, which lands inside this iframe as a second copy
   sitting over the glass; the page that embeds it already shows one */
:root[data-embed="machine"] netlify-hud,
:root[data-embed="machine"] [id^="netlify-"],
:root[data-embed="machine"] [class*="netlify-badge"] { display: none !important; }
:root[data-embed="machine"] .stage { padding: 0 !important; min-height: 0; display: block; }
:root[data-embed="machine"] .machine { margin: 0; }
:root[data-embed="machine"] .screen,
:root[data-embed="machine"] .mscreen { box-shadow: none; border-radius: 0; }

/* the brief's full-length score, 999,999.000: the three decimals sit smaller and quieter than the whole number
   (format.js writes them as <span class="dec">); every surface may tune this in its own rules */
.dec { font-size: .46em; letter-spacing: .01em; opacity: .72; font-variant-numeric: tabular-nums; }

/* ---------------------------------------------------------------- round six: the shell
   The top bar: the Robotenc logo with the task's title, the brief and its line stacked under it on the left; the tabs
   at the top of the centre column, and in the Animation tab its Start and Reset right under them. The stages start
   under the bar's measured height (--topbar-h, app.js), whatever it holds. */
.topbar { grid-template-rows: auto auto; align-items: start; }
.crumb.crumb-stack { grid-column: 1; grid-row: 1 / span 2; flex-direction: column; align-items: flex-start; gap: 12px; }
.crumb-stack .crumb-logo { width: 100px; }
.crumb-stack .crumb-text { gap: 8px; }
.crumb-stack .crumb-text > span { max-width: 36ch; }
@media (min-width: 1100px) { .crumb-stack .crumb-text > span { display: block; } }
.topbar > .modes { grid-column: 2; grid-row: 1; }
.topbar > .topactions { grid-column: 3; grid-row: 1; }
.topbar > .anim-bar { grid-column: 2; grid-row: 2; justify-self: center; }
body:not([data-mode="animation"]) .topbar > .anim-bar { display: none; }
@media (max-width: 960px) {
  .crumb.crumb-stack { grid-row: 1; }
  .topbar > .topactions { grid-column: 2; grid-row: 1; }
  .topbar > .modes { grid-row: 2; grid-column: 1 / -1; }
  .topbar > .anim-bar { grid-row: 3; grid-column: 1 / -1; }
}
body .stage, body .phone-stage, body .ds-stage { padding-top: calc(var(--topbar-h, 96px) + 16px); }
/* phone widths: the logo and the actions share the first row, and the title and the brief take the full width under
   them, so neither has to step back to a screen reader */
@media (max-width: 720px) {
  .crumb.crumb-stack { display: contents; }
  .crumb-stack .crumb-logo { grid-column: 1; grid-row: 1; align-self: center; width: 92px; }
  .crumb-stack .crumb-text { grid-column: 1 / -1; grid-row: 2; gap: 6px; }
  .crumb-stack .crumb-title b { position: static; width: auto; height: auto; overflow: visible; clip-path: none; font-size: 14px; }
  .crumb-stack .briefbtn span { display: inline; }
  .crumb-stack .briefbtn { padding: 0 10px 0 8px; }
  .topbar > .modes { grid-row: 3; }
  .topbar > .anim-bar { grid-row: 4; }
}
/* the line itself waits for a wider window (1100 px, above): on a phone it would push the device's foot below the fold */

.anim-bar {
  display: flex; align-items: center; gap: 4px; padding: 6px; border-radius: 999px;
  background: var(--shell-pill);
  box-shadow: inset 0 0 0 1px var(--shell-pill-line), 0 16px 32px -20px rgba(0, 0, 0, .5);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
}
.anim-bar .anim-play, .anim-bar .anim-reset {
  appearance: none; cursor: pointer; height: 38px; padding: 0 16px 0 12px; border-radius: 999px; border: 0;
  display: inline-flex; align-items: center; gap: 8px;
  font: 700 14px/1 "Barlow", sans-serif; white-space: nowrap;
  transition: background-color .2s ease, color .2s ease;
}
.anim-bar .anim-play { background: var(--shell-pill-on); color: var(--shell-pill-on-ink); }
.anim-bar .anim-play[aria-pressed="true"] { background: transparent; color: var(--shell-ink); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--shell-ink) 30%, transparent); }
.anim-bar .anim-reset { background: transparent; color: var(--shell-pill-ink); }
.anim-bar .anim-reset:hover { color: var(--shell-ink); background: var(--shell-pill-hover); }
.anim-bar button:focus-visible { outline: 2px solid var(--shell-ink); outline-offset: 2px; }

/* ---------------------------------------------------------------- Customise, as accordions
   "This screen" (the page on show, its sections), "Across every screen", then theme, logo, the phone and the glass */
.custom-body { padding-top: 12px; }
.acc { border-bottom: 1px solid var(--panel-line); }
.acc:last-of-type { border-bottom: 0; }
.acc[hidden] { display: none; }
.acc-sum {
  list-style: none; cursor: pointer; display: flex; align-items: center; gap: 12px;
  padding: 20px 2px; border-radius: 10px;
}
.acc-sum::-webkit-details-marker { display: none; }
.acc-sum:focus-visible { outline: 2px solid var(--panel-ink); outline-offset: 2px; }
.acc-t { display: grid; gap: 6px; min-width: 0; flex: 1; }
.acc-k { font: 700 12px/1 "Barlow Condensed", sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--panel-mute); }
.acc-title { font: 700 18px/1.15 "Barlow", sans-serif; color: var(--panel-ink); overflow-wrap: anywhere; }
.acc-note { flex: none; font: 600 13px/1 "Barlow", sans-serif; color: var(--panel-mute); }
.acc-note:empty { display: none; }
.acc-chev { flex: none; width: 9px; height: 9px; margin: 0 6px 4px 0; border-right: 2px solid var(--panel-mute); border-bottom: 2px solid var(--panel-mute); transform: rotate(45deg); transition: transform .2s ease; }
.acc[open] > .acc-sum .acc-chev { transform: rotate(-135deg) translate(-3px, -3px); }
.acc-body { display: grid; gap: 16px; padding: 2px 0 24px; }
.acc-body > .seg, .acc-body > .replay, .acc-body > .themes, .acc-body > .logos, .acc-body > .lock-note, .acc-body > .ctl-row, .acc-body > .ctl { margin: 0; }
.acc-sub { font: 700 12px/1 "Barlow Condensed", sans-serif; letter-spacing: .16em; text-transform: uppercase; color: var(--panel-mute); }
/* round eleven: everything shared sits in one accordion, each part under its own small heading */
.cus-shared { display: grid; gap: 24px; }
.cus-sub { display: grid; gap: 10px; min-width: 0; }
.cus-sub > .acc-sub { display: block; }
.cus-sub + .cus-sub { padding-top: 20px; border-top: 1px solid var(--panel-line, rgba(255, 255, 255, .08)); }
.acc-result { display: grid; gap: 10px; }
.acc-result .group-head { margin: 0; align-items: center; }
.acc-empty { margin: 0; font: 500 14px/1.45 "Barlow", sans-serif; color: var(--panel-mute); }
/* the section a row points at, marked on the screen itself */
[data-sec].is-target { outline: 3px dashed #EB1110; outline-offset: -3px; }
.mscreen [data-sec].is-target { outline-width: 10px; outline-offset: -10px; }

/* ---------------------------------------------------------------- the page bars in two steps (pagenav.js)
   The groups on top in the shell's pill; the chosen group's screens under it, a step smaller and quieter */
.pagenav { display: grid; justify-items: center; gap: 8px; max-width: 100%; }
.stage > .pagenav { margin: 0 auto 24px; }
.pagenav .mpagebar { margin: 0; }
.pagenav .pagesub {
  gap: 2px; padding: 4px;
  background: color-mix(in oklab, var(--shell-pill) 55%, transparent);
  box-shadow: inset 0 0 0 1px var(--shell-pill-line);
}
.pagenav .pagesub button { height: 32px; padding: 0 16px; font-size: 13px; }
.pagenav .pagesub button[aria-current="page"] { background: color-mix(in oklab, var(--shell-pill-on) 16%, transparent); color: var(--shell-ink); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--shell-ink) 28%, transparent); }
.pagenav .pagegroups button[aria-current="true"] { background: var(--shell-pill-on); color: var(--shell-pill-on-ink); }
.phone-stage.is-anim .pagenav { display: none; }
:root[data-embed="machine"] .pagenav { display: none; }

/* ---------------------------------------------------------------- round seven: a 44 px touch on every shell control
   (the sweep's rule for the 390 wide shell). Where the drawn control is smaller than 44, an invisible ::after grows its
   hit area into the air around it, never over a neighbour: the brief chip (26), the tabs, the page bars and Start and
   Reset (38) inside their 4 to 5 px pill padding, Customise's segments (35) into the rows' spacing, its close button (36).
   The sub page bar grows to 36 so its extension stays inside its own pill. The design arrows grow to a real 44. */
:is(.briefbtn, .mode, .pagebar button, .anim-bar .anim-play, .anim-bar .anim-reset, .seg button, .iconbtn.small) { position: relative; }
:is(.briefbtn, .mode, .pagebar button, .anim-bar .anim-play, .anim-bar .anim-reset, .seg button, .iconbtn.small)::after { content: ""; position: absolute; }
.briefbtn::after { inset: -9px -2px; }
:is(.mode, .pagebar button, .anim-bar .anim-play, .anim-bar .anim-reset)::after { inset: -3px 0; }
.pagenav .pagesub button { height: 36px; }
.pagenav .pagesub button::after { inset: -4px 0; }
.seg button::after { inset: -5px 0; }
.iconbtn.small::after { inset: -4px; }
.sec-btn { width: 44px; height: 44px; }
input[type="range"] { height: 44px; }

/* ---------------------------------------------------------------- the page bars live in the top bar (round eight)
   Right under the tabs, where the Animation tab's Start and Reset sit: the tabs, then the groups a step smaller, then
   the chosen group's screens smaller again. Each surface's bar shows only in its own tab. */
.topbar > .pagenav { grid-column: 2; grid-row: 2; justify-self: center; gap: 6px; }
body:not([data-mode="machine"]) .topbar > [data-pagenav="mscreen"],
body:not([data-mode="mobile"]) .topbar > [data-pagenav="page"] { display: none; }
@media (max-width: 960px) { .topbar > .pagenav { grid-row: 3; grid-column: 1 / -1; } }
.pagenav .pagegroups { padding: 4px; gap: 2px; }
.pagenav .pagegroups button { height: 34px; padding: 0 16px; font-size: 14px; }
.pagenav .pagesub { padding: 4px; }
.pagenav .pagesub button { height: 28px; padding: 0 12px; font-size: 13px; }

/* ------------------------------------------------------------ How this works: a short, centred overlay.
   Its own shell rather than the brief's side panel: this one is a quick read, not a document. */
.helpwrap {
  position: fixed; inset: 0; z-index: 70;
  display: grid; place-items: center; padding: 24px;
  opacity: 0; transition: opacity .22s ease;
}
.helpwrap[hidden] { display: none; }
.helpwrap.is-open { opacity: 1; }
.help-scrim { position: absolute; inset: 0; background: rgba(6, 6, 8, .72); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
.help-card {
  position: relative; z-index: 1;
  width: min(680px, 100%); max-height: min(84vh, 760px); overflow-y: auto;
  padding: 28px; border-radius: 24px;
  background: var(--panel-bg); color: var(--panel-ink);
  box-shadow: 0 40px 90px -30px rgba(0, 0, 0, .7), 0 0 0 1px var(--panel-line);
  transform: translateY(12px) scale(.985); transition: transform .28s cubic-bezier(.2, .7, .2, 1);
}
.helpwrap.is-open .help-card { transform: none; }
.help-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.help-head h2 { margin: 0; font: var(--w-display) 26px/1 var(--f-display); letter-spacing: .01em; text-transform: uppercase; }
.help-sub { margin: 8px 0 0; font: 400 15px/1.5 "Barlow", sans-serif; color: var(--panel-ink-2, inherit); opacity: .8; max-width: 46ch; }
.help-x {
  appearance: none; border: 0; cursor: pointer; flex: none;
  width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center;
  background: color-mix(in srgb, var(--panel-ink) 8%, transparent); color: inherit;
}
.help-x:hover { background: color-mix(in srgb, var(--panel-ink) 16%, transparent); }
.help-tabs { list-style: none; margin: 24px 0 0; padding: 0; display: grid; gap: 12px; }
.help-tabs li {
  display: grid; grid-template-columns: 36px auto minmax(0, 1fr); align-items: center; gap: 12px;
  padding: 12px; border-radius: 12px; background: color-mix(in srgb, var(--panel-ink) 5%, transparent);
  font: 400 15px/1.4 "Barlow", sans-serif;
}
.help-ico { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: var(--panel-bg); box-shadow: 0 0 0 1px var(--panel-line); }
.help-tabs b { font-weight: 700; white-space: nowrap; }
.help-tabs span:last-child { opacity: .75; }
.help-point { margin-top: 24px; padding-top: 20px; border-top: 1px solid var(--panel-line); }
.help-point h3 { margin: 0 0 8px; font: 700 17px/1.2 "Barlow", sans-serif; }
.help-point p { margin: 0; font: 400 15px/1.55 "Barlow", sans-serif; opacity: .85; }
@media (max-width: 620px) {
  .help-tabs li { grid-template-columns: 36px minmax(0, 1fr); }
  .help-tabs li span:last-child { grid-column: 2; }
}
@media (prefers-reduced-motion: reduce) {
  .helpwrap, .help-card { transition: none; }
}

/* ------------------------------------------------------------ the desktop gate.
   Hidden on anything wide enough to hold the pair; below that it covers the page and the page stops scrolling. */
.deskgate { display: none; }
/* The embedded machine glass loads this same page in a 486px wide iframe, which is narrower than any phone.
   The gate is about the device the reader is on, not the width of a frame inside the page, so embeds are exempt. */
@media (max-width: 767px) {
  :root[data-embed="machine"] .deskgate { display: none !important; }
  :root:not([data-embed="machine"]) .deskgate {
    display: grid; place-items: center;
    position: fixed; inset: 0; z-index: 200;
    padding: 24px;
    background: #0A0A0B; color: #F5F3EF;
  }
  .deskgate::before {
    content: ""; position: absolute; inset: 0; pointer-events: none;
    background: radial-gradient(60% 40% at 50% 8%, rgba(235, 17, 16, .22), transparent 70%);
  }
  .deskgate-card { position: relative; max-width: 42ch; text-align: center; display: grid; justify-items: center; gap: 20px; }
  .deskgate-mark { width: 64px; height: 64px; }
  .deskgate-t { margin: 0; font: var(--w-display, 900) 32px/1.05 var(--f-display, sans-serif); text-transform: uppercase; letter-spacing: .01em; }
  .deskgate-p { margin: 0; font: 400 16px/1.55 "Barlow", system-ui, sans-serif; color: #B5B0A8; }
  .deskgate-p-quiet { font-weight: 600; color: #F5F3EF; }
  /* nothing behind the gate should scroll, animate or be reachable */
  :root:not([data-embed="machine"]) body { overflow: hidden !important; }
  :root:not([data-embed="machine"]) :is(.topbar, .stage, .phone-stage, .ds-stage, .custom, .custom-scrim, .brief, .case, .helpwrap, .loader) { display: none !important; }
}

/* ------------------------------------------------------------ the typeface, chosen in Customise under General settings.
   Each face brings its own two metrics as well as its name: --num-w is how wide a digit sits on its own width and
   --cap is its cap height, and every big number on both surfaces is sized from those, so a face swapped without them
   would overflow its column. Body text stays in Barlow throughout: Orbitron and Chakra Petch are display faces and
   neither is readable at fourteen pixels on a phone. */
:root[data-typeface="orbitron"] {
  --f-display: "Orbitron", "Arial Black", Arial, sans-serif;
  --w-display: 900;
  --display-track: .005em;
  --num-w: .72; --cap: .7;
  --f-label: "Orbitron", "Arial Black", sans-serif;
  --w-label: 700; --label-track: .1em;
}
:root[data-typeface="orbitron"] .m-app {
  --m-f-title: "Orbitron", system-ui, sans-serif;
  --m-w-title: 700; --m-w-heavy: 900;
  --m-f-label: "Orbitron", sans-serif;
  --m-w-label: 700; --m-track-label: .1em;
  --m-num-w: .78;
}
:root[data-typeface="chakra"] {
  --f-display: "Chakra Petch", "Arial Narrow", sans-serif;
  --w-display: 700;
  --display-track: .01em;
  --num-w: .55; --cap: .72;
  --f-label: "Chakra Petch", sans-serif;
  --w-label: 600; --label-track: .14em;
}
:root[data-typeface="chakra"] .m-app {
  --m-f-title: "Chakra Petch", system-ui, sans-serif;
  --m-w-title: 700; --m-w-heavy: 700;
  --m-f-label: "Chakra Petch", sans-serif;
  --m-w-label: 600;
  --m-num-w: .58;
}
/* the picker's own samples, each set in the face it offers */
.faces { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.face-tile {
  appearance: none; border: 0; cursor: pointer; display: grid; gap: 6px; justify-items: center;
  padding: 16px 8px 12px; border-radius: 12px;
  background: var(--shell-pill, rgba(0, 0, 0, .05)); color: inherit;
  box-shadow: inset 0 0 0 1px transparent;
}
.face-tile[aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--panel-ink); }
.face-tile-s { font-size: 22px; line-height: 1; font-variant-numeric: tabular-nums; }
.face-tile-n { font: 500 12px/1 "Barlow", sans-serif; opacity: .7; }
.face-tile[data-typeface="arena"] .face-tile-s { font: 900 22px/1 "Big Shoulders Display", sans-serif; }
.face-tile[data-typeface="orbitron"] .face-tile-s { font: 900 18px/1 "Orbitron", sans-serif; }
.face-tile[data-typeface="chakra"] .face-tile-s { font: 700 20px/1 "Chakra Petch", sans-serif; }

sections.css:
/* The Result glass on one grid (round seven: "some cards do not have a proper width and need the rules of UX, and simpler").
   Loaded first of the section sheets (/sections.css sorts by file name), so every section designs against it.
   - One margin: the glass's own side margin, --ms-gut on every flow screen, 88 px at breathing room 100.
     Full bleed designs still run to the glass edge; whatever they print on it starts on this margin.
   - One column split: a row of cards divides the column into equal parts with one gap (--gap-grid), halves, thirds
     or quarters, never a card sized by its own content next to one sized by the row.
   - One card: the surface radius (--r), one inner padding (--card-pad), one border, no card inside a card. */
#screen { --pad: calc(88px * var(--space)); }

/* Result: Recent punches (sections/clips.html). Round nine: "in results no need for the slo-mo replay clips, just show
   others' punch history". Other players' punches at this machine, newest first, each with a face (avatar or the punch
   photo), a name, the score through PunchFormat and when. Five designs on the Result grid (sections/_grid.css): one
   margin, equal columns on --gap-grid, one card on --r and --card-pad. The section keeps the height the clips had
   (about 330 glass px with its title), so the glass still fits at full size. Reference shows the first design only,
   in its frame (the ref card, 24 px corners, Sora and Archivo Black). Scope every rule under .s-clips. */

.s-clips :is(ol, p, figure) { margin: 0; padding: 0; }
.s-clips ol { list-style: none; }
/* the pieces every design uses */
.s-clips .rp-ava { display: block; flex: none; width: 72px; height: 72px; border-radius: 50%; object-fit: cover; background: var(--badge); }
.s-clips .rp-who { display: grid; gap: 8px; min-width: 0; }
.s-clips .rp-name { min-width: 0; font-weight: var(--w-strong); line-height: 1.1; color: var(--ink-1); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* when, in the label face but as said ("2 min ago"): sentence case and untracked, so it stays short beside a score */
.s-clips :is(.rp-when, .rp-chip) { text-transform: none; letter-spacing: 0; white-space: nowrap; }
.s-clips .rp-when { color: var(--ink-3); }
/* a score: the cap asked for, or the size at which its characters fit the column (9 counts the decimals at .46) */
.s-clips .rp-score {
  --top: 52px; --chars: 9;
  display: block; min-width: 0; line-height: .9; font-variant-numeric: tabular-nums; color: var(--ink-1);
  font-size: min(calc(var(--top) / var(--cap)), calc(100cqi / (var(--chars) * var(--num-w))));
}
:root[data-decimals="off"] .s-clips .rp-score { --chars: 7; }
/* the when, on a dark chip over a photo, so its type reads on any frame */
.s-clips .rp-chip {
  position: absolute; z-index: 2; top: 16px; left: 16px; padding: 10px 16px 8px; border-radius: calc(var(--r) * .5);
  color: #FFFFFF; background: rgba(10, 10, 12, .7);
}

/* A  Photo cards: the three latest, each a card with the punch photo (the when on its corner, the name at its foot)
   and the score under it */
.s-clips .v-a .rp-a { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--gap-grid); }
.s-clips .v-a .rp-a-card { min-width: 0; overflow: hidden; display: grid; grid-template-rows: 172px auto; container-type: inline-size; }
.s-clips .v-a .rp-a-shot { height: 172px; background: var(--raised); }
.s-clips .v-a .rp-a-shot::after { background: linear-gradient(180deg, rgba(8, 8, 9, 0) 34%, rgba(8, 8, 9, .86)); }
/* the name stands clear of the photo's foot, and the score keeps a margin of its own under it */
.s-clips .v-a .rp-a-shot .rp-name { position: absolute; z-index: 2; left: 18px; right: 18px; bottom: 18px; color: #FFFFFF; font-size: 26px; }
.s-clips .v-a .rp-score { --top: 40px; padding: 20px 24px 24px; font-size: min(calc(var(--top) / var(--cap)), calc((100cqi - 64px) / (var(--chars) * var(--num-w)))); }

/* B  List: the three latest as rows, the face, the name over when, the score standing on the right */
.s-clips .v-b .rp-b { display: grid; gap: 16px; }
.s-clips .v-b .rp-b-row {
  display: grid; grid-template-columns: 72px minmax(0, 1fr) 290px; align-items: center; column-gap: 28px;
  height: 104px; padding: 0 40px 0 16px; container-type: inline-size;
}
.s-clips .v-b .rp-b-row .rp-who { gap: 8px; }
.s-clips .v-b .rp-b-row .rp-score { --top: 50px; justify-self: end; font-size: min(calc(var(--top) / var(--cap)), calc(290px / (var(--chars) * var(--num-w)))); }

/* C  Latest first: the newest punch as a photo on half the row, the three before it as rows beside it */
.s-clips .v-c .rp-c { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid); height: 264px; }
.s-clips .v-c .rp-c-lead { min-width: 0; border-radius: var(--r); background: var(--raised); }
.s-clips .v-c .rp-c-lead > img { position: absolute; inset: 0; }
.s-clips .v-c .rp-c-lead::after { background: linear-gradient(180deg, rgba(8, 8, 9, .35), rgba(8, 8, 9, 0) 36%, rgba(8, 8, 9, .1) 50%, rgba(8, 8, 9, .86)); }
.s-clips .v-c .rp-c-cap {
  position: absolute; z-index: 2; left: 0; right: 0; bottom: 0; container-type: inline-size;
  display: grid; gap: 10px; padding: 0 28px 28px;
}
.s-clips .v-c .rp-c-cap .rp-name { color: #FFFFFF; }
.s-clips .v-c .rp-c-cap .rp-score { --top: 64px; color: #FFFFFF; text-shadow: 0 4px 24px rgba(0, 0, 0, .5); }
.s-clips .v-c .rp-c-list { display: grid; grid-template-rows: repeat(3, minmax(0, 1fr)); gap: 12px; min-width: 0; }
.s-clips .v-c .rp-c-row {
  min-width: 0; display: grid; grid-template-columns: 56px minmax(0, 1fr) auto; align-items: center; column-gap: 16px;
  padding: 0 24px 0 12px;
}
.s-clips .v-c .rp-c-row .rp-ava { width: 56px; height: 56px; }
.s-clips .v-c .rp-c-row .rp-who { gap: 4px; }
.s-clips .v-c .rp-c-row .rp-score { font-size: min(calc(36px / var(--cap)), calc(170px / (var(--chars) * var(--num-w)))); }

/* D  Faces: the four latest side by side, face, name, score and when; the newest ringed in the strike colour */
.s-clips .v-d .rp-d { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--gap-grid); }
.s-clips .v-d .rp-d-col { min-width: 0; container-type: inline-size; display: grid; justify-items: center; align-content: start; gap: 12px; text-align: center; }
.s-clips .v-d .rp-d-col .rp-ava { width: 112px; height: 112px; margin-bottom: 4px; box-shadow: 0 0 0 4px var(--line); }
.s-clips .v-d .rp-d-col.is-new .rp-ava { box-shadow: 0 0 0 6px var(--strike), var(--strike-glow); }
.s-clips .v-d .rp-d-col .rp-name { max-width: 100%; }
.s-clips .v-d .rp-d-col .rp-score { --top: 44px; --chars: 9.4; }

/* E  Bars: the five latest in the order they punched, oldest on the left; each bar stands at the score's share of
   the top score, the face at its head, the score over it; the best of them in the strike colour */
.s-clips .v-e .rp-e { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: var(--gap-grid); align-items: end; }
.s-clips .v-e .rp-e-col { min-width: 0; container-type: inline-size; display: grid; justify-items: center; align-content: end; gap: 8px; text-align: center; }
.s-clips .v-e .rp-e-col .rp-score { --top: 30px; --chars: 9.6; margin-bottom: 4px; }
/* the bar: the face's width, from the face alone at .6 of the top score to 64 px more at the top score */
.s-clips .v-e .rp-e-bar {
  --w: 84px;
  display: grid; justify-items: center; align-content: start; width: var(--w); padding-top: 8px;
  height: calc(var(--w) + (var(--h, .7) - .6) / .4 * 64px); border-radius: calc(var(--w) / 2) calc(var(--w) / 2) 16px 16px;
  background: var(--track);
}
.s-clips .v-e .rp-e-bar .rp-ava { width: 70px; height: 70px; }
.s-clips .v-e .rp-e-col.is-top .rp-e-bar { background: var(--strike); box-shadow: var(--strike-glow); }
.s-clips .v-e .rp-e-col .rp-name { max-width: 100%; margin-top: 2px; }

/* cta: designs B to E. Scope every rule under .s-cta .v-<letter>.
   Punch again is the one red thing in every design. Display words are trimmed to cap height and baseline (text-box),
   so they sit optically centred in their slabs. */

/* B  Button pair: two equal halves of the column. Punch again is the red one; the other half says where the hit went,
      a status, not a second button, since the glass takes no touch. */
.s-cta .v-b .cta-b-pair {
  container-type: inline-size;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid); height: 168px;
}
.s-cta .v-b .cta-b-play { display: grid; place-items: center; border-radius: var(--r); }
.s-cta .v-b .cta-b-word {
  display: block; font-size: min(calc(60px / var(--cap)), calc((50cqi - var(--gap-grid) / 2 - 2 * var(--card-pad)) / 5.4));
  letter-spacing: .04em; margin-right: -.04em; text-box: trim-both cap alphabetic;
}
.s-cta .v-b .cta-b-save {
  min-width: 0; display: flex; align-items: center; gap: 24px; padding-inline: var(--card-pad);
}
/* Lucide smartphone at 48 px: 1.5 on the 24 grid draws the 3 px line every glass icon uses */
.s-cta .v-b .cta-b-icon { flex: none; font-size: 48px; line-height: 0; color: var(--up, #2BC46B); }
.s-cta .v-b .cta-b-txt { min-width: 0; display: grid; gap: 8px; }
.s-cta .v-b .cta-b-cap { font-size: 22px; color: var(--ink-3); }
.s-cta .v-b .cta-b-say { min-width: 0; font-size: 30px; line-height: 1.15; color: var(--ink-1); text-wrap: balance; }

/* C  Countdown: the red slab and a shot clock side by side on one row, the clock's caption over the end of the slab */
.s-cta .v-c .cta-c-dock {
  --ring: 200px;
  container-type: inline-size;
  display: grid; grid-template-columns: minmax(0, 1fr) var(--ring); grid-template-rows: minmax(0, 1fr) 144px;
  column-gap: var(--gap-grid); height: var(--ring);
}
.s-cta .v-c .cta-c-next { grid-area: 1 / 1; align-self: start; justify-self: end; white-space: nowrap; text-box: trim-both cap alphabetic; }
.s-cta .v-c .cta-c-play { grid-area: 2 / 1; display: grid; align-items: center; padding-inline: var(--card-pad); border-radius: var(--r); }
.s-cta .v-c .cta-c-word {
  display: block; font-size: min(calc(64px / var(--cap)), calc((100cqi - var(--ring) - 120px) / 5.2));
  letter-spacing: .04em; text-box: trim-both cap alphabetic;
}
.s-cta .v-c .cta-c-clock { grid-area: 1 / 2 / 3 / 3; width: var(--ring); height: var(--ring); display: grid; }
.s-cta .v-c .cta-c-clock > * { grid-area: 1 / 1; }
.s-cta .v-c .cta-c-ring { display: block; width: 100%; height: 100%; transform: rotate(-90deg); }
.s-cta .v-c .cta-c-track,
.s-cta .v-c .cta-c-left { fill: none; stroke-width: 22; stroke-dashoffset: -.55; }
.s-cta .v-c .cta-c-track { stroke: var(--track); stroke-dasharray: 3.9 1.1; }
.s-cta .v-c .cta-c-left { stroke: var(--ink-1); stroke-dasharray: 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 0 40; }
.s-cta .v-c .cta-c-read { place-self: center; display: grid; justify-items: center; row-gap: 12px; }
.s-cta .v-c .cta-c-num { font-size: calc(60px / var(--cap)); font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic; }
.s-cta .v-c .cta-c-unit { font-size: 32px; color: var(--ink-3); text-box: trim-both cap alphabetic; }

/* D  Code handoff: two equal halves, Punch again on the left, the run's code on the right with what it is for.
      The code is the shared PunchQR tile, 200 px (about 150 px of code), for a phone held at arm's length. */
.s-cta .v-d .cta-d-row {
  container-type: inline-size;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid); height: 200px;
}
.s-cta .v-d .cta-d-play { display: grid; place-items: center; border-radius: var(--r); }
.s-cta .v-d .cta-d-word {
  display: block; font-size: min(calc(60px / var(--cap)), calc((50cqi - var(--gap-grid) / 2 - 2 * var(--card-pad)) / 5.4));
  letter-spacing: .04em; margin-right: -.04em; text-box: trim-both cap alphabetic;
}
.s-cta .v-d .cta-d-hand { min-width: 0; display: grid; grid-template-columns: 200px minmax(0, 1fr); align-items: center; column-gap: 28px; }
.s-cta .v-d .cta-d-qr {
  --pqr-size: 200px;
  display: block; padding: 0; border: 0; border-radius: 10px;
  background: none; cursor: pointer;
}
/* the code is the way into the phone flow, so it is a button with the shared focus ring. The glass is drawn at a
   fraction of its size, so the ring is set in screen pixels */
.s-cta .v-d .cta-d-qr:focus-visible {
  outline: min(calc(2.5px / (var(--zoom) * var(--fit))), 9px) solid var(--focus);
  outline-offset: min(calc(1.5px / (var(--zoom) * var(--fit))), 5px);
}
.s-cta .v-d .cta-d-copy { min-width: 0; display: grid; gap: 20px; }
.s-cta .v-d .cta-d-keep { font-size: 32px; line-height: 1.2; color: var(--ink-1); text-wrap: balance; }
.s-cta .v-d .cta-d-code { font-size: calc(32px / var(--cap)); letter-spacing: .14em; color: var(--ink-2); text-box: trim-both cap alphabetic; }

/* E  Big pad: the machine's strike pad, the hit sends rings out across the glass and they fade as they travel */
.s-cta .v-e .cta-e-band {
  --d: 200px; --cx: calc(var(--pad) + var(--d) / 2);
  position: relative; margin-inline: calc(-1 * var(--pad)); height: var(--d); overflow: hidden;
  display: flex; align-items: center; gap: calc(56px * var(--space)); padding-left: var(--pad);
}
.s-cta .v-e .cta-e-waves {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at var(--cx) 50%,
    transparent 115px, var(--line) 116px 119px, transparent 120px 137px, var(--line) 138px 141px, transparent 142px 165px,
    var(--line) 166px 169px, transparent 170px 201px, var(--line) 202px 205px, transparent 206px 245px,
    var(--line) 246px 249px, transparent 250px 297px, var(--line) 298px 301px, transparent 302px 357px,
    var(--line) 358px 361px, transparent 362px 427px, var(--line) 428px 431px, transparent 432px 507px,
    var(--line) 508px 511px, transparent 512px 597px, var(--line) 598px 601px, transparent 602px 697px,
    var(--line) 698px 701px, transparent 702px 807px, var(--line) 808px 811px, transparent 812px);
  -webkit-mask-image: radial-gradient(circle at var(--cx) 50%, black 180px, transparent 860px), linear-gradient(to bottom, transparent, black 24%, black 76%, transparent);
  mask-image: radial-gradient(circle at var(--cx) 50%, black 180px, transparent 860px), linear-gradient(to bottom, transparent, black 24%, black 76%, transparent);
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
}
.s-cta .v-e .cta-e-pad { position: relative; flex: none; width: var(--d); height: var(--d); display: grid; place-items: center; }
.s-cta .v-e .cta-e-rings { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: var(--line); stroke-width: 2; }
.s-cta .v-e .cta-e-core { position: relative; width: 156px; height: 156px; border-radius: 50%; display: grid; place-items: center; }
.s-cta .v-e .cta-e-core > svg { grid-area: 1 / 1; }
.s-cta .v-e .cta-e-stitch { width: 100%; height: 100%; fill: none; stroke: var(--cta-ink); stroke-opacity: .4; stroke-width: 2; stroke-dasharray: 5 6; }
/* Lucide rotate-ccw at 76 px: .95 on the 24 grid draws the 3 px line every glass icon uses */
.s-cta .v-e .cta-e-again { width: 76px; height: 76px; color: var(--cta-ink); stroke-width: .95; }
.s-cta .v-e .cta-e-hit { position: relative; font-size: 48px; color: var(--ink-1); white-space: nowrap; text-box: trim-both cap alphabetic; }

/* ---------------------------------------------------------------- Light: the same designs on a daylight ground */


/* header: designs B to E. Every rule is scoped under .s-header .v-<letter>. */

/* B: fight bill. A banner slapped across the whole glass, tilted upward, crossing a steeper tape behind it.
   The band carries the mark, the name and the venue; every item rides the slope, the type stays upright. */
.s-header .v-b { container-type: inline-size; }
.s-header .v-b .header-b-bill {
  position: relative; isolation: isolate;
  display: grid; align-items: center;
  margin-inline: calc(-1 * var(--pad));
  padding-block: 20px;
}
.s-header .v-b .header-b-under {
  position: absolute; left: 0; right: 0; top: 20px; bottom: 20px; z-index: -1;
  background: var(--track);
  transform: skewY(-4.5deg);
}
.s-header .v-b .header-b-band {
  height: 124px; border-radius: 0; border-inline-width: 0;
  padding-inline: var(--pad);
  display: grid; align-items: center;
  transform: skewY(-2deg);
}
.s-header .v-b .header-b-row { display: flex; align-items: center; gap: calc(24px * var(--space)); }
.s-header .v-b .header-b-row > * { transform: skewY(2deg); }
.s-header .v-b .header-b-mark { width: 76px; height: 76px; background: var(--ink-1); color: var(--ground); }
.s-header .v-b .header-b-word { font-size: calc(72px / var(--cap)); }
.s-header .v-b .header-b-word span { color: var(--ink-3); }
.s-header .v-b .header-b-venue { margin-left: auto; font-size: 32px; line-height: 1.15; text-align: right; white-space: nowrap; }

/* C: title belt. A stamped seal with a burst edge, the name and the venue set around its ring,
   buckled onto a stitched strap that fades out toward the edges of the column. */
.s-header .v-c { container-type: inline-size; }
.s-header .v-c .header-c-belt { position: relative; display: grid; place-items: center; height: 176px; }
.s-header .v-c .header-c-strap {
  position: absolute; left: 0; right: 0; top: 50%; height: 84px; translate: 0 -50%;
  border-radius: 0;
  -webkit-mask-image: linear-gradient(90deg, transparent, rgba(0, 0, 0, 1) 34%, rgba(0, 0, 0, 1) 66%, transparent);
  mask-image: linear-gradient(90deg, transparent, rgba(0, 0, 0, 1) 34%, rgba(0, 0, 0, 1) 66%, transparent);
}
.s-header .v-c .header-c-strap::before,
.s-header .v-c .header-c-strap::after {
  content: ""; position: absolute; left: 0; right: 0; height: 2px;
  background: repeating-linear-gradient(90deg, var(--ink-3) 0 12px, transparent 12px 22px);
}
.s-header .v-c .header-c-strap::before { top: 12px; }
.s-header .v-c .header-c-strap::after { bottom: 12px; }
.s-header .v-c .header-c-seal { position: relative; width: 176px; height: 176px; }
.s-header .v-c .header-c-disc {
  position: absolute; inset: 0; border-radius: 0;
  clip-path: polygon(50.00% 0.00%, 54.09% 3.30%, 58.68% 0.76%, 62.13% 4.72%, 67.10% 3.02%, 69.81% 7.52%, 75.00% 6.70%, 76.89% 11.60%, 82.14% 11.70%, 83.15% 16.85%, 88.30% 17.86%, 88.40% 23.11%, 93.30% 25.00%, 92.48% 30.19%, 96.98% 32.90%, 95.28% 37.87%, 99.24% 41.32%, 96.70% 45.91%, 100.00% 50.00%, 96.70% 54.09%, 99.24% 58.68%, 95.28% 62.13%, 96.98% 67.10%, 92.48% 69.81%, 93.30% 75.00%, 88.40% 76.89%, 88.30% 82.14%, 83.15% 83.15%, 82.14% 88.30%, 76.89% 88.40%, 75.00% 93.30%, 69.81% 92.48%, 67.10% 96.98%, 62.13% 95.28%, 58.68% 99.24%, 54.09% 96.70%, 50.00% 100.00%, 45.91% 96.70%, 41.32% 99.24%, 37.87% 95.28%, 32.90% 96.98%, 30.19% 92.48%, 25.00% 93.30%, 23.11% 88.40%, 17.86% 88.30%, 16.85% 83.15%, 11.70% 82.14%, 11.60% 76.89%, 6.70% 75.00%, 7.52% 69.81%, 3.02% 67.10%, 4.72% 62.13%, 0.76% 58.68%, 3.30% 54.09%, 0.00% 50.00%, 3.30% 45.91%, 0.76% 41.32%, 4.72% 37.87%, 3.02% 32.90%, 7.52% 30.19%, 6.70% 25.00%, 11.60% 23.11%, 11.70% 17.86%, 16.85% 16.85%, 17.86% 11.70%, 23.11% 11.60%, 25.00% 6.70%, 30.19% 7.52%, 32.90% 3.02%, 37.87% 4.72%, 41.32% 0.76%, 45.91% 3.30%);
}
.s-header .v-c .header-c-ring { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.s-header .v-c .header-c-edge { fill: none; stroke: var(--line); stroke-width: 2; stroke-linejoin: round; }
.s-header .v-c .header-c-rim { fill: none; stroke: var(--line); stroke-width: 2; }
.s-header .v-c .header-c-name {
  font-family: var(--f-display); font-weight: var(--w-display); font-size: 30px; letter-spacing: .02em;
  fill: var(--ink-1);
}
.s-header .v-c .header-c-place {
  font-family: var(--f-label); font-weight: var(--w-label); font-size: 24px; letter-spacing: .06em;
  text-transform: uppercase; fill: var(--ink-2);
}
.s-header .v-c .header-c-dot { fill: var(--ink-3); }
.s-header .v-c .header-c-mark {
  position: absolute; left: 50%; top: 50%; width: 88px; height: 88px; translate: -50% -50%;
  background: var(--ink-1); color: var(--ground);
}
/* the mark is sized by its shape to sit inside the inner rim (r 51): a round mark fills 88 px, a rounded square is cut
   to 72 px so its corners (about 44 px from the centre) clear the rim and the lettering set around it */
.s-header .v-c .header-c-mark:is([data-mark="glove"], [data-mark="upright"], [data-mark="pair"], [data-mark="bag"]) { width: 72px; height: 72px; }
/* C in daylight: the strap turns to a warm leather tone so the white seal stands proud of it, the seal casts a
   soft shadow, and its burst edge and rims are cut in ink rather than in a hairline that vanishes on white */
:root[data-appearance="light"] .s-header .v-c .header-c-strap {
  background: color-mix(in oklab, var(--ink-1) 8%, var(--ground));
  border-color: color-mix(in oklab, var(--ink-1) 10%, transparent); box-shadow: none;
}
:root[data-appearance="light"] .s-header .v-c .header-c-seal { filter: drop-shadow(0 12px 14px rgba(70, 45, 30, .2)); }
:root[data-appearance="light"] .s-header .v-c .header-c-edge,
:root[data-appearance="light"] .s-header .v-c .header-c-rim { stroke: color-mix(in oklab, var(--ink-1) 22%, transparent); }

/* D: player plate. A fight night lower third, level and on the margins: one plate across the column, the player's
   portrait and name on the left, the brand on the right, on the card's one padding. */
.s-header .v-d { container-type: inline-size; }
.s-header .v-d .header-d-plate {
  height: 160px; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  column-gap: calc(28px * var(--space)); padding-inline: var(--card-pad);
}
.s-header .v-d .header-d-avatar { width: 104px; height: 104px; border-radius: 50%; }
.s-header .v-d .header-d-who { display: grid; gap: 12px; min-width: 0; }
.s-header .v-d .header-d-name { font-size: calc(60px / var(--cap)); }
.s-header .v-d .header-d-brand { display: flex; align-items: center; gap: 16px; }
.s-header .v-d .header-d-mark { width: 68px; height: 68px; background: var(--ink-1); color: var(--ground); }
.s-header .v-d .header-d-word { font-size: calc(36px / var(--cap)); }
.s-header .v-d .header-d-word span { color: var(--ink-3); }

/* E: masthead. The name set like a newspaper masthead on a heavy rule, a giant outlined PUNCH behind it
   as texture, cut off by the rule the way a headline runs off a page. */
.s-header .v-e { container-type: inline-size; }
.s-header .v-e .header-e-mast {
  position: relative; overflow: clip;
  height: 162px;
  display: flex; align-items: flex-end;
  padding-bottom: calc(24px * var(--space));
  border-bottom: 6px solid var(--ink-1);
}
.s-header .v-e .header-e-echo {
  position: absolute; left: 0; top: 0;
  font-size: calc(100cqi / 2.54); line-height: .8; letter-spacing: 0;
  color: transparent; -webkit-text-stroke: 3px var(--line); text-shadow: none;
}
.s-header .v-e .header-e-lock {
  position: relative; flex: 1;
  display: flex; align-items: baseline; justify-content: space-between; gap: calc(24px * var(--space));
}
.s-header .v-e .header-e-word { font-size: calc(64px / var(--cap)); }
.s-header .v-e .header-e-word span { color: var(--ink-3); }
.s-header .v-e .header-e-venue { font-size: 32px; white-space: nowrap; }

/* hero F "Slot reels": the score lands on spinning reels, like a jackpot. app.js builds the reels from the
   live score and spins them on the reveal, on switching to this design and on releasing the Score slider.
   The one red thing is the charge: the bulb row lights up to the height of the hit.
   The cabinet and the drums are set by local tokens: at night the drums are dark glass lit from the middle,
   in daylight they are bright drums in a recessed window, shaded over the digits where they turn away. */
.s-hero .v-f {
  container-type: inline-size;
  --cab-bg: var(--surface-hi-bg);
  --cab-bezel: inset 0 0 0 6px var(--ground), inset 0 0 0 8px rgba(255, 255, 255, .14), 0 40px 70px -40px rgba(0, 0, 0, .9);
  --drum: linear-gradient(#060607 0%, #1B1B1E 16%, #2E2E33 50%, #1B1B1E 84%, #060607 100%);
  --drum-rim: inset 0 0 0 2px rgba(255, 255, 255, .08), inset 0 .12em .2em rgba(0, 0, 0, .8), inset 0 -.12em .2em rgba(0, 0, 0, .8);
  --drum-fade: linear-gradient(transparent 2%, #000 27%, #000 73%, transparent 98%);
  --drum-turn: none;
  --drum-edge: none;
  --drum-ink: var(--ink-1);
  --bulb-glow: drop-shadow(0 0 8px var(--strike));
}
:root[data-appearance="light"] .s-hero .v-f {
  --cab-bg: linear-gradient(180deg, color-mix(in oklab, var(--ink-1) 9%, var(--ground)), color-mix(in oklab, var(--ink-1) 4%, var(--ground)));
  --cab-bezel: inset 0 0 0 6px var(--raised), inset 0 0 0 8px var(--line), inset 0 22px 26px -22px color-mix(in oklab, var(--ink-1) 30%, transparent), 0 40px 70px -40px rgba(70, 45, 30, .38);
  --drum: linear-gradient(color-mix(in oklab, var(--ink-1) 3%, var(--raised)), var(--raised) 50%, color-mix(in oklab, var(--ink-1) 3%, var(--raised)));
  --drum-rim: none;
  --drum-edge: inset 0 0 0 2px var(--line);
  /* the rows above and below fade into the recessed window, so the neighbours of each digit do not sit on the
     bright drum as grey smudges */
  --drum-fade: linear-gradient(transparent 7%, #000 25%, #000 75%, transparent 93%);
  --drum-shade: color-mix(in oklab, var(--ink-1) 38%, var(--raised));
  --drum-turn: linear-gradient(var(--drum-shade), color-mix(in oklab, var(--drum-shade) 55%, transparent) 12%, color-mix(in oklab, var(--drum-shade) 18%, transparent) 24%,
    transparent 34%, transparent 66%, color-mix(in oklab, var(--drum-shade) 18%, transparent) 76%, color-mix(in oklab, var(--drum-shade) 55%, transparent) 88%, var(--drum-shade));
  --bulb-glow: drop-shadow(0 0 5px color-mix(in oklab, var(--strike) 55%, transparent));
}
.s-hero .v-f .hero-f { display: grid; justify-items: center; gap: calc(28px * var(--space)); }
.s-hero .v-f .hero-f-label { font-size: 32px; }

/* the reel bank: a chrome-edged cabinet with payline markers pointing at the centre row */
.s-hero .v-f .hero-f-cabinet {
  position: relative; width: 100%;
  padding: calc(24px * var(--space)) 48px;
  display: flex; justify-content: center;
  border-radius: calc(var(--r) * 1.2);
  background: var(--cab-bg);
  box-shadow: var(--cab-bezel);
}
.s-hero .v-f .hero-f-cabinet::before,
.s-hero .v-f .hero-f-cabinet::after {
  content: ""; position: absolute; top: 50%; width: 0; height: 0;
  border-block: 18px solid transparent; transform: translateY(-50%);
}
.s-hero .v-f .hero-f-cabinet::before { left: -2px; border-left: 22px solid var(--ink-1); }
.s-hero .v-f .hero-f-cabinet::after { right: -2px; border-right: 22px solid var(--ink-1); }

/* reel sizing: the brief's full length, 999,999.000. Six digit reels and a comma cell take the full size, and the
   three decimals turn on a small bank of their own after the point (.reel-dec), so the width in em is
   6 x .64 + .24 + 6 gaps x .045 for the whole points, plus a gap and the bank at .46: .04 + (.3 + 3 x .64 + 3 x .06) x .46,
   5.47em in all; whole points only, 4.35em */
.s-hero .v-f { --reel-ems: 5.52; }
:root[data-decimals="off"] .s-hero .v-f { --reel-ems: 4.4; }
.s-hero .v-f .hero-f-window { width: 100%; container-type: inline-size; display: flex; justify-content: center; }
.s-hero .v-f .hero-f-reels {
  --fs: min(190px, calc(100cqi / var(--reel-ems)));
  display: flex; align-items: stretch; gap: calc(var(--fs) * .045);
  margin: 0; font-size: var(--fs); line-height: 1;
  text-shadow: none;
}
.s-hero .v-f .reel {
  position: relative; overflow: hidden; flex: none;
  width: .64em; height: 1.46em; border-radius: .07em;
  background: var(--drum);
  box-shadow: var(--drum-rim);
  -webkit-mask-image: var(--drum-fade);
  mask-image: var(--drum-fade);
}
/* where the drum turns away from the eye: shade over the digits, so the rows above and below sink into it */
.s-hero .v-f .reel::after {
  content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;
  border-radius: inherit; background: var(--drum-turn); box-shadow: var(--drum-edge);
}
.s-hero .v-f .reel-strip {
  position: absolute; left: 0; right: 0; top: .21em;
  display: flex; flex-direction: column;
  will-change: transform;
}
.s-hero .v-f .reel-strip > span { display: grid; place-items: center; height: 1.04em; color: var(--drum-ink); font-variant-numeric: tabular-nums; }
.s-hero .v-f .reel-sep { display: grid; place-items: end center; width: .24em; padding-bottom: .24em; color: var(--ink-1); }
/* the decimal bank: the same drums at the .dec size, set on the whole reels' baseline (the big digit's baseline
   stands .33em above its drum's foot, the small one's .33em above its own), and a step quieter, like the text .dec */
.s-hero .v-f .reel-dec {
  display: flex; gap: .06em; align-self: flex-end; margin-left: .04em;
  font-size: .46em; margin-bottom: calc(.33em / .46 - .19em);
}
/* the small drums are cut down to the digit row, so they read as three counters, not as a strip of half digits;
   the whole bank's drums are 1.46em with the row at .21em, these 1.14em with the row at .05em */
.s-hero .v-f .reel-dec .reel { height: 1.14em; border-radius: .1em; -webkit-mask-image: none; mask-image: none; }
.s-hero .v-f .reel-dec .reel-strip { top: .05em; }
.s-hero .v-f .reel-dec .reel-strip > span { color: color-mix(in oklab, var(--drum-ink) 72%, transparent); }
.s-hero .v-f .reel-dec .reel-point { width: .3em; padding-bottom: .19em; color: color-mix(in oklab, var(--ink-1) 72%, transparent); }

/* the charge: a bulb row that lights up to the height of the hit. The pitch divides the row exactly,
   so the last bulb is never cut, and the lit row shares the same pitch so its bulbs sit on the unlit ones. */
.s-hero .v-f .hero-f-bulbs {
  --pitch: calc(100cqi / 26);
  position: relative; width: 100%; height: 24px;
  background: radial-gradient(circle, var(--track) 0 7px, transparent 8px) 0 50% / var(--pitch) 24px repeat-x;
}
.s-hero .v-f .hero-f-lit {
  position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--charge, 1) * 100%);
  background: radial-gradient(circle, var(--strike) 0 7px, transparent 8px) 0 50% / var(--pitch) 24px repeat-x;
  filter: var(--bulb-glow);
}
.s-hero .v-f .hero-f-grade { font-size: 64px; letter-spacing: .06em; color: var(--ink-1); }

/* hero: designs B to E. Scope every rule under .s-hero .v-<letter>.
   Big figures are trimmed to cap height and baseline (text-box), so edges and baselines line up exactly. */

/* the score is the brief's full length, 999,999.000 (app.js paints it through PunchFormat), and every design sizes
   it by the big-number rule with CHARS = --score-chars: the width of the whole score in average display characters.
   Measured with the three decimals at their .46em: 9.77 in Big Shoulders (Arena), 9.15 in Archivo Black (Reference);
   whole points only: 7.81 and 7.31. The larger of each pair, so either face fits. */
.s-hero { --score-chars: 9.8; }
:root[data-decimals="off"] .s-hero { --score-chars: 7.9; }
/* the decimals ride on the whole number's baseline, .46em and a step quieter (the base .dec in styles.css), with the
   face's own point before them, so 999,999.000 reads as one number whose whole points are the event */

/* B  Power gauge: a segmented arc across the glass, the needle crosses the band, the score sits on the diameter */
/* the dial ends on the arc's feet (viewBox 1080 x 504), and the gap under it leaves room for the comma's tail, which
   hangs below the diameter the score stands on */
.s-hero .v-b { display: grid; row-gap: calc(20px * var(--space) + 24px); text-align: center; }
.s-hero .v-b .hero-b-dial { position: relative; margin-inline: calc(-1 * var(--pad)); }
.s-hero .v-b .hero-b-svg { display: block; width: 100%; height: auto; overflow: visible; }
.s-hero .v-b .hero-b-mask { mask-type: alpha; }
.s-hero .v-b .hero-b-cellpath { fill: none; stroke: currentColor; stroke-width: 80; stroke-dasharray: 3.9 1.1; stroke-dashoffset: -.55; }
.s-hero .v-b .hero-b-track,
.s-hero .v-b .hero-b-fill { fill: none; stroke-width: 38; }
.s-hero .v-b .hero-b-track { stroke: var(--track); }
.s-hero .v-b .hero-b-fill { stroke: var(--strike); stroke-dasharray: 100 200; stroke-dashoffset: calc(100 - var(--charge, 1) * 100); }
.s-hero .v-b .hero-b-minor { fill: none; stroke: var(--ink-3); stroke-width: 4; stroke-linecap: round; }
.s-hero .v-b .hero-b-major { fill: none; stroke: var(--ink-1); stroke-width: 8; stroke-linecap: round; }
.s-hero .v-b .hero-b-needle {
  fill: var(--ink-1);
  transform-box: view-box; transform-origin: 540px 504px;
  transform: rotate(calc(var(--charge, 1) * 180deg - 90deg));
}
.s-hero .v-b .hero-b-read {
  position: absolute; left: 0; right: 0; top: 0; height: 100%;
  display: grid; align-content: end; justify-items: center; row-gap: calc(36px * var(--space));
}
.s-hero .v-b .hero-b-label { text-box: trim-both cap alphabetic; }
.s-hero .v-b .hero-b-num { container-type: inline-size; width: 68%; display: grid; justify-items: center; }
.s-hero .v-b .hero-b-score {
  font-size: min(calc(150px / var(--cap)), calc(100cqi / (var(--score-chars) * var(--num-w))));
  font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic;
}
.s-hero .v-b .hero-b-grade { justify-self: center; font-size: calc(40px / var(--cap)); text-box: trim-both cap alphabetic; }

/* C  Strength tower: the fairground tester stands on the right, the reading stands on the same floor */
.s-hero .v-c {
  display: grid; grid-template-columns: minmax(0, 1fr) 160px; grid-template-rows: auto 6px;
  column-gap: calc(40px * var(--space));
}
.s-hero .v-c .hero-c-copy {
  grid-area: 1 / 1; align-self: end; container-type: inline-size;
  display: grid; justify-items: start; row-gap: calc(32px * var(--space));
  padding-bottom: 48px;
}
.s-hero .v-c .hero-c-label { text-box: trim-both cap alphabetic; }
.s-hero .v-c .hero-c-score {
  font-size: min(calc(150px / var(--cap)), calc(100cqi / (var(--score-chars) * var(--num-w))));
  font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic;
}
.s-hero .v-c .hero-c-grade {
  font-size: min(calc(56px / var(--cap)), calc(100cqi / (13 * var(--num-w))));
  margin-top: calc(16px * var(--space)); color: var(--ink-2); text-box: trim-both cap alphabetic;
}
.s-hero .v-c .hero-c-tower { grid-area: 1 / 2; height: 580px; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; justify-items: center; }
.s-hero .v-c .hero-c-bell { display: block; width: 160px; height: auto; fill: var(--ink-1); }
.s-hero .v-c .hero-c-rays path {
  fill: none; stroke: var(--ink-1); stroke-width: 7; stroke-linecap: round;
  opacity: calc((var(--charge, 1) - .95) * 20);
}
.s-hero .v-c .hero-c-board { position: relative; width: 120px; margin-top: 6px; border-bottom-width: 0; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.s-hero .v-c .hero-c-scale {
  position: absolute; top: 18px; bottom: 18px; left: 14px; right: 14px;
  background:
    repeating-linear-gradient(to top, var(--ink-2) 0 6px, transparent 6px calc((100% - 6px) / 4)) center / 100% 100% no-repeat,
    repeating-linear-gradient(to top, var(--ink-3) 0 3px, transparent 3px calc((100% - 3px) / 20)) center / 64% 100% no-repeat;
}
.s-hero .v-c .hero-c-rail {
  position: absolute; top: 18px; bottom: 18px; left: 50%; width: 40px; margin-left: -20px;
  border-radius: min(var(--r), 20px); background: var(--track); overflow: hidden;
}
.s-hero .v-c .hero-c-fill { position: absolute; left: 0; right: 0; bottom: 0; height: calc(var(--charge, 1) * 100%); }
.s-hero .v-c .hero-c-puck {
  position: absolute; left: 50%; bottom: calc(18px + var(--charge, 1) * (100% - 36px));
  width: 88px; height: 24px; transform: translate(-50%, 50%);
  border-radius: min(var(--r), 8px); background: var(--ink-1);
}
.s-hero .v-c .hero-c-base { display: block; width: 160px; height: 44px; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.s-hero .v-c .hero-c-floor { grid-area: 2 / 1 / 3 / 3; background: var(--ink-3); }
/* C in daylight: a white board on a pale ground needs a drawn edge, and the base is cast in ink like the bell and
   the puck, so the tester reads as one solid object standing on the floor line */
:root[data-appearance="light"] .s-hero .v-c .hero-c-board { border-color: color-mix(in oklab, var(--ink-1) 16%, transparent); }
:root[data-appearance="light"] .s-hero .v-c .hero-c-base { background: var(--ink-1); border-color: var(--ink-1); box-shadow: none; }

/* D  Impact: the score lands in a tilted starburst, speed lines fly off it, the grade is stamped across its edge */
.s-hero .v-d { display: grid; row-gap: calc(24px * var(--space)); }
.s-hero .v-d .hero-d-hit { position: relative; margin-inline: calc(-1 * var(--pad)); aspect-ratio: 1080 / 540; }
.s-hero .v-d .hero-d-hit > * { position: absolute; }
.s-hero .v-d .hero-d-rays {
  inset: 0; width: 100%; height: 100%; fill: var(--ink-1); opacity: .08;
  -webkit-mask-image: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 24%, rgba(0, 0, 0, 1) 76%, rgba(0, 0, 0, 0));
  mask-image: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 24%, rgba(0, 0, 0, 1) 76%, rgba(0, 0, 0, 0));
}
.s-hero .v-d .hero-d-blast { inset: 0; transform: rotate(-3deg) scale(.95); }
.s-hero .v-d .hero-d-burst,
.s-hero .v-d .hero-d-edge { position: absolute; inset: 0; width: 100%; height: 100%; }
.s-hero .v-d .hero-d-edge { overflow: visible; }
.s-hero .v-d .hero-d-edge polygon { fill: none; stroke: var(--ink-3); stroke-width: 3; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.s-hero .v-d .hero-d-burst {
  border-radius: 0;
  clip-path: polygon(50% 0.7%, 56.3% 10.2%, 65.6% 7%, 68.4% 14.1%, 77.5% 10.6%, 78.7% 21.5%, 88.7% 23.6%, 86.1% 31.7%, 96.9% 33.9%, 90.1% 43.7%, 95.5% 51%, 90.1% 56.3%, 96.3% 65%, 86.1% 68.3%, 89.2% 76.5%, 78.7% 78.5%, 78% 90.2%, 68.4% 85.9%, 63.8% 93.6%, 56.3% 89.8%, 50.7% 99.3%, 43.7% 89.8%, 34.3% 93.9%, 31.6% 85.9%, 22% 89.1%, 21.3% 78.5%, 12% 75.7%, 13.9% 68.3%, 3.6% 66.1%, 9.9% 56.3%, 2.9% 49.4%, 9.9% 43.7%, 3.1% 33.9%, 13.9% 31.7%, 12.2% 24.2%, 21.3% 21.5%, 22.3% 10.4%, 31.6% 14.1%, 35% 5.4%, 43.7% 10.2%);
}
/* the number's box stops short of the burst's inner valleys (about 12% in, after the tilt and the .95 scale), so the
   full length, 999,999.000, never reaches the edge line */
.s-hero .v-d .hero-d-num {
  inset: 0 15%; container-type: inline-size;
  display: grid; place-items: center;
}
.s-hero .v-d .hero-d-score {
  font-size: min(calc(160px / var(--cap)), calc(100cqi / (var(--score-chars) * var(--num-w))));
  font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic;
}
.s-hero .v-d .hero-d-stamp {
  right: var(--pad); bottom: 6px;
  display: grid; justify-items: start; row-gap: 16px;
  padding: 28px 36px; transform: rotate(-6deg); transform-origin: 0 100%;
  outline: 3px solid var(--line); outline-offset: -12px;
}
.s-hero .v-d .hero-d-stamp-label { font-size: 32px; text-box: trim-both cap alphabetic; }
.s-hero .v-d .hero-d-grade { font-size: calc(46px / var(--cap)); text-box: trim-both cap alphabetic; }
.s-hero .v-d .hero-d-bar { height: 14px; border-radius: min(var(--r), 7px); background: var(--track); overflow: hidden; }
.s-hero .v-d .hero-d-fill { display: block; height: 100%; transform-origin: 0 50%; transform: scaleX(var(--charge, 1)); }
/* D in daylight: the burst is a real white card, lifted off the paper by a warm shadow and cut with a soft ink edge
   (the ground-coloured fill and grey hairline read as a wireframe), and the rays turn to light: white beams, where
   ink rays read as smudges on paper */
:root[data-appearance="light"] .s-hero .v-d .hero-d-burst { background: #FFFFFF; }
:root[data-appearance="light"] .s-hero .v-d .hero-d-blast { filter: drop-shadow(0 22px 26px rgba(70, 45, 30, .2)); }
:root[data-appearance="light"] .s-hero .v-d .hero-d-edge polygon { stroke: color-mix(in oklab, var(--ink-1) 22%, transparent); }
:root[data-appearance="light"] .s-hero .v-d .hero-d-rays { fill: #FFFFFF; opacity: 1; }

/* E  Glass: the fight photo runs edge to edge, a frosted panel floats over it with the reading, the charge on its lower edge */
.s-hero .v-e .hero-e-stage { position: relative; margin-inline: calc(-1 * var(--pad)); height: calc(450px + 150px * var(--space)); }
.s-hero .v-e .hero-e-photo { position: absolute; inset: 0; clip-path: polygon(0 40px, 100% 0, 100% 100%, 0 100%); }
.s-hero .v-e .hero-e-photo > img { position: absolute; inset: 0; object-position: 55% 24%; }
.s-hero .v-e .hero-e-scrim {
  position: absolute; inset: 0; z-index: 2;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 34%, rgba(0, 0, 0, .38) 64%, rgba(0, 0, 0, .64));
}
/* E in daylight: the photo no longer melts into a dark ground, it ends on a pale one, so the scrim only has to
   carry the panel, not bury the lower edge in black */
:root[data-appearance="light"] .s-hero .v-e .hero-e-scrim {
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 40%, rgba(0, 0, 0, .22) 70%, rgba(0, 0, 0, .36));
}
.s-hero .v-e .hero-e-panel {
  position: absolute; left: var(--pad); right: var(--pad); bottom: calc(40px * var(--space));
  display: grid; row-gap: calc(36px * var(--space)); overflow: hidden;
  padding: calc(40px * var(--space)) calc(48px * var(--space)) calc(64px * var(--space));
}
.s-hero .v-e .hero-e-top { display: flex; justify-content: space-between; align-items: end; gap: 32px; }
.s-hero .v-e .hero-e-label { color: inherit; text-box: trim-both cap alphabetic; }
.s-hero .v-e .hero-e-grade { font-size: calc(40px / var(--cap)); text-box: trim-both cap alphabetic; }
.s-hero .v-e .hero-e-num { container-type: inline-size; }
.s-hero .v-e .hero-e-score {
  font-size: min(calc(180px / var(--cap)), calc(100cqi / (var(--score-chars) * var(--num-w))));
  font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic;
}
.s-hero .v-e .hero-e-bar { position: absolute; left: 0; right: 0; bottom: 0; height: 16px; background: var(--track); }
.s-hero .v-e .hero-e-fill { display: block; height: 100%; transform-origin: 0 50%; transform: scaleX(var(--charge, 1)); }

/* photo: designs B to E. Scope every rule under .s-photo .v-<letter>.
   Display lines are trimmed to cap height and baseline (text-box), so edges and baselines line up exactly. */

/* B  Full bleed: the fight runs glass edge to glass edge, a frosted panel holds the night's line over the lower third */
.s-photo .v-b .photo-b-band { position: relative; margin-inline: calc(-1 * var(--pad)); height: 424px; container-type: inline-size; }
.s-photo .v-b .photo-b-frame { position: absolute; inset: 0; }
.s-photo .v-b .photo-b-frame > img { object-position: 50% 38%; }
.s-photo .v-b .photo-b-frame::before {
  content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background: linear-gradient(to top, rgba(0, 0, 0, .5), rgba(0, 0, 0, 0) 60%);
}
.s-photo .v-b .photo-b-panel {
  position: absolute; z-index: 2; left: var(--pad); bottom: calc(36px * var(--space)); max-width: calc(100% - 2 * var(--pad));
  display: grid; justify-items: start; row-gap: calc(24px * var(--space));
  padding: calc(36px * var(--space)) calc(56px * var(--space)) calc(36px * var(--space)) calc(48px * var(--space));
}
.s-photo .v-b .photo-b-where { color: rgba(255, 255, 255, .82); text-box: trim-both cap alphabetic; }
.s-photo .v-b .photo-b-title {
  font-size: min(calc(72px / var(--cap)), calc((100cqi - 2 * var(--pad) - 100px * var(--space)) / (19 * .5)));
  text-box: trim-both cap alphabetic;
}

/* C  Slant cut: the photo sheared into a forward-leaning blade across the column (its lower left and upper right corners
      on the margins), a raised slab leans with it over the bottom corner, its foot on the left margin */
.s-photo .v-c .photo-c-stage { position: relative; padding-bottom: 48px; --lean: .2126; --cut: calc(382px * var(--lean)); }
.s-photo .v-c .photo-c-cut {
  height: 382px;
  clip-path: polygon(var(--cut) 0, 100% 0, calc(100% - var(--cut)) 100%, 0 100%);
}
.s-photo .v-c .photo-c-cut > img { object-position: 40% 42%; }
.s-photo .v-c .photo-c-slab {
  position: absolute; z-index: 2; left: 0; bottom: 0;
  padding: var(--card-pad) calc(var(--card-pad) + 32px) var(--card-pad) var(--card-pad);
  transform-origin: 0 100%; transform: skewX(-12deg);
}
.s-photo .v-c .photo-c-lines { display: grid; justify-items: start; row-gap: calc(24px * var(--space)); }
/* each line stands upright from its own baseline, so the left edges step along the slant */
.s-photo .v-c .photo-c-title,
.s-photo .v-c .photo-c-where { transform-origin: 0 100%; transform: skewX(12deg); text-box: trim-both cap alphabetic; }
.s-photo .v-c .photo-c-title { font-size: calc(64px / var(--cap)); }

/* D  Promo banner: a swallowtail fight banner across the column, the sponsor line on the dark end */
.s-photo .v-d .photo-d-banner {
  position: relative; container-type: inline-size; aspect-ratio: 21 / 9; background: rgba(0, 0, 0, 1);
  --notch: 44px;
  clip-path: polygon(0 0, 100% 0, calc(100% - var(--notch)) 50%, 100% 100%, 0 100%, var(--notch) 50%);
}
.s-photo .v-d .photo-d-shot {
  position: absolute; top: 0; right: 0; bottom: 0; width: 64%;
  -webkit-mask-image: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 38%);
  mask-image: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 38%);
}
.s-photo .v-d .photo-d-shot > img { object-position: 45% 30%; }
.s-photo .v-d .photo-d-copy {
  position: absolute; z-index: 2; left: calc(var(--notch) + 44px); top: 0; bottom: 0; width: 44cqi;
  display: grid; align-content: center; justify-items: start; row-gap: calc(40px * var(--space));
}
.s-photo .v-d .photo-d-head { display: grid; justify-items: start; row-gap: calc(20px * var(--space)); white-space: normal; }
.s-photo .v-d .photo-d-lead { font-size: calc(34px / var(--cap)); color: var(--ink-2); white-space: nowrap; text-box: trim-both cap alphabetic; }
.s-photo .v-d .photo-d-big { font-size: min(calc(72px / var(--cap)), calc(44cqi / (10 * .5))); white-space: nowrap; text-box: trim-both cap alphabetic; }
.s-photo .v-d .photo-d-brand { text-box: trim-both cap alphabetic; }

/* E  Poster print: the fight as a print across the column, level, held up by one strip of tape at the top */
.s-photo .v-e .photo-e-wall { padding-top: 24px; }
.s-photo .v-e .photo-e-stack { position: relative; }
.s-photo .v-e .photo-e-print { position: relative; margin: 0; padding: var(--card-pad) var(--card-pad) 0; }
.s-photo .v-e .photo-e-frame { height: 256px; border-radius: calc(var(--r) * .5); }
.s-photo .v-e .photo-e-frame > img { object-position: 45% 62%; }
.s-photo .v-e .photo-e-cap { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; padding: 32px 0 36px; }
.s-photo .v-e .photo-e-title { font-weight: var(--w-strong); color: var(--ink-1); white-space: nowrap; text-box: trim-both cap alphabetic; }
.s-photo .v-e .photo-e-where { font-size: 32px; color: var(--ink-3); white-space: nowrap; text-box: trim-both cap alphabetic; }
.s-photo .v-e .photo-e-tape {
  position: absolute; z-index: 3; top: -22px; left: 50%; width: 168px; height: 44px; translate: -50% 0;
  background: color-mix(in oklab, var(--ink-1) 24%, transparent);
  clip-path: polygon(0 8%, 6% 0, 12% 10%, 18% 0, 82% 0, 88% 10%, 94% 0, 100% 8%, 100% 92%, 94% 100%, 88% 90%, 82% 100%, 18% 100%, 12% 90%, 6% 100%, 0 92%);
}

/* ---------------------------------------------------------------- Light: the same designs on a daylight ground */

/* D: the banner turns to paper and the fight smokes out of it; the fade starts past the headline, so the copy sits on clean paper */
:root[data-appearance="light"] .s-photo .v-d { filter: drop-shadow(0 18px 22px color-mix(in oklab, var(--ink-1) 12%, transparent)); }
:root[data-appearance="light"] .s-photo .v-d .photo-d-banner { background: var(--raised); }
:root[data-appearance="light"] .s-photo .v-d .photo-d-shot {
  -webkit-mask-image: linear-gradient(to right, rgba(0, 0, 0, 0) 19%, rgba(0, 0, 0, 1) 40%);
  mask-image: linear-gradient(to right, rgba(0, 0, 0, 0) 19%, rgba(0, 0, 0, 1) 40%);
}

/* E: masking tape, not grey duct tape: a warm translucent strip that shows on the white print and on the ground */
:root[data-appearance="light"] .s-photo .v-e .photo-e-tape {
  background: color-mix(in oklab, color-mix(in oklab, var(--ink-1) 16%, var(--ground)) 80%, transparent);
}

/* ranks: designs B to E. Scope every rule under .s-ranks .v-<letter>. */

/* B  Podium: Global on a raised banner, three podium blocks below. The steps rise with the
      size of the pool each rank was won in (country, then city, then this machine), so they still say something
      when the ranks tie, as they do for a best score that is first everywhere. */
.s-ranks .v-b .ranks-b-stage { display: grid; gap: calc(16px * var(--space)); }
.s-ranks .v-b .ranks-b-banner {
  display: grid; grid-template-columns: auto auto minmax(0, 1fr); align-items: center;
  column-gap: calc(28px * var(--space));
  padding: 16px var(--card-pad);
}
.s-ranks .v-b .ranks-b-badge-lg { width: 104px; height: 104px; }
/* every line icon on the glass draws 3 glass px: stroke-width = 3 x 40 / badge size (see .badge-rank in styles.css) */
.s-ranks .v-b .ranks-b-badge-lg svg g { stroke-width: 1.25; }
.s-ranks .v-b .ranks-b-banner-label { color: var(--ink-1); font-size: 32px; }
.s-ranks .v-b .ranks-b-banner-num { container-type: inline-size; min-width: 0; display: grid; justify-items: end; }
.s-ranks .v-b .ranks-b-banner-value { font-size: min(calc(72px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(100cqi / (max(6, var(--rank-chars, 6)) * var(--num-w)))); }

.s-ranks .v-b .ranks-b-podium { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: end; border-bottom: 6px solid var(--line); }
.s-ranks .v-b .ranks-b-col { container-type: inline-size; min-width: 0; display: grid; justify-items: center; text-align: center; }
.s-ranks .v-b .ranks-b-label { font-size: 32px; }
.s-ranks .v-b .ranks-b-value {
  margin: 12px 0 16px;
  font-size: min(calc(50px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(86cqi / (max(5, var(--rank-chars, 5)) * var(--num-w))));
}
.s-ranks .v-b .ranks-b-block {
  position: relative; overflow: hidden;
  width: 100%; display: grid; justify-items: center; align-content: start;
  padding-top: 28px; border-bottom: 0; border-bottom-left-radius: 0; border-bottom-right-radius: 0;
}
.s-ranks .v-b .ranks-b-block::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 12px; background: var(--line); }
.s-ranks .v-b .ranks-b-left .ranks-b-block { height: 114px; }
.s-ranks .v-b .ranks-b-mid { position: relative; z-index: 1; }
.s-ranks .v-b .ranks-b-mid .ranks-b-block { height: 144px; }
.s-ranks .v-b .ranks-b-right .ranks-b-block { height: 88px; padding-top: 20px; }
.s-ranks .v-b .ranks-b-badge { width: 76px; height: 76px; }
.s-ranks .v-b .ranks-b-badge svg g { stroke-width: 1.6; }

/* C  Ladder: two thick rails, a rung per rank, badges as the nodes; the label reads off its rung, the figure holds the right edge.
      No leader runs between them: a line between two words reads as a dash. */
.s-ranks .v-c .ranks-c-ladder {
  --zone: 216px; --rail: 22px;
  position: relative;
  display: grid; grid-template-rows: 132px repeat(3, 88px);
}
.s-ranks .v-c .ranks-c-rail { position: absolute; top: 18px; bottom: 6px; width: var(--rail); z-index: 0; }
.s-ranks .v-c .ranks-c-rail-l { left: 44px; }
.s-ranks .v-c .ranks-c-rail-r { left: calc(var(--zone) - 44px - var(--rail)); }
.s-ranks .v-c .ranks-c-step {
  position: relative; min-width: 0;
  display: grid; grid-template-columns: var(--zone) minmax(0, 1fr); align-items: center;
  column-gap: calc(24px * var(--space));
}
.s-ranks .v-c .ranks-c-rung {
  position: absolute; left: 36px; width: calc(var(--zone) - 72px); top: 50%; height: 18px; margin-top: -10px;
  z-index: 1; border-radius: 9px;
}
.s-ranks .v-c .ranks-c-node { position: relative; z-index: 2; grid-column: 1; justify-self: center; width: 68px; height: 68px; }
.s-ranks .v-c .ranks-c-read {
  container-type: inline-size; min-width: 0;
  display: flex; align-items: center; gap: calc(24px * var(--space));
}
.s-ranks .v-c .ranks-c-label { flex: none; min-width: 200px; font-size: 32px; }
.s-ranks .v-c .ranks-c-value { margin-left: auto; font-size: min(calc(44px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(44cqi / (max(5, var(--rank-chars, 5)) * var(--num-w)))); }
.s-ranks .v-c .ranks-c-top .ranks-c-rung { left: 8px; width: calc(var(--zone) - 16px); height: 28px; margin-top: -16px; border-radius: 14px; }
.s-ranks .v-c .ranks-c-top .ranks-c-node { width: 108px; height: 108px; }
/* one glass line through the ladder, 3 px: 1.76 on the 68 px nodes, 1.11 on the 108 px top node */
.s-ranks .v-c .ranks-c-node svg g { stroke-width: 1.76; }
.s-ranks .v-c .ranks-c-top .ranks-c-node svg g { stroke-width: 1.11; }
.s-ranks .v-c .ranks-c-top .ranks-c-label { color: var(--ink-1); font-size: 32px; }
.s-ranks .v-c .ranks-c-top .ranks-c-value { font-size: min(calc(72px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(56cqi / (max(6, var(--rank-chars, 6)) * var(--num-w)))); }

/* D  Scoreboard: one raised board, digits on flip tiles, right aligned */
.s-ranks .v-d .ranks-d-board { display: grid; padding: calc(12px * var(--space)) var(--card-pad); }
.s-ranks .v-d .ranks-d-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center;
  column-gap: calc(40px * var(--space)); padding-block: 12px;
}
.s-ranks .v-d .ranks-d-row + .ranks-d-row { border-top: 2px solid var(--line); }
.s-ranks .v-d .ranks-d-label { font-size: 32px; }
.s-ranks .v-d .ranks-d-key .ranks-d-label { color: var(--ink-1); font-size: 32px; }
.s-ranks .v-d .ranks-d-row > .ranks-d-digits { container-type: inline-size; }
.s-ranks .v-d .ranks-d-digits {
  display: flex; justify-content: flex-end; align-items: stretch; gap: 6px;
  --c: 42px; --n: 4.6;
}
.s-ranks .v-d .ranks-d-key .ranks-d-digits { --c: 72px; --n: 5.8; }
.s-ranks .v-d .ranks-d-tile,
.s-ranks .v-d .ranks-d-sep {
  font-size: min(calc(var(--c) / var(--cap)), calc(100cqi / (var(--n) * (var(--num-w) + .3))));
}
.s-ranks .v-d .ranks-d-tile {
  position: relative; isolation: isolate; display: grid; place-items: center;
  width: calc((var(--num-w) + .22) * 1em); height: calc((var(--cap) + .34) * 1em);
  background: linear-gradient(var(--track), var(--track)), var(--surface-hi-bg); border-radius: calc(var(--r) * .3);
  font-variant-numeric: tabular-nums; line-height: 1;
}
.s-ranks .v-d .ranks-d-tile::after {
  content: ""; position: absolute; z-index: -1; left: 0; right: 0; top: 50%; height: 3px; margin-top: -1px;
  background: var(--surface-hi-bg);
}
.s-ranks .v-d .ranks-d-sep { display: grid; align-items: end; width: .3em; padding-bottom: .08em; line-height: 1; text-align: center; }
/* the rank sign sits beside the tiles, not on one: only digits flip */
.s-ranks .v-d .ranks-d-hash {
  display: grid; align-items: center; padding-right: .06em; line-height: 1; color: var(--ink-2);
  font-size: min(calc(var(--c) / var(--cap)), calc(100cqi / (var(--n) * (var(--num-w) + .3))));
}

/* E  Split slabs: four slanted slabs of one width, stacked on the column, the key rank on the taller raised one.
      The stack is inset by the slant's overhang (tan 12deg x half the key slab's height), so every corner lands on the margins. */
.s-ranks .v-e .ranks-e-stack { --tilt: -12deg; display: grid; gap: calc(12px * var(--space)); padding-inline: 12px; }
.s-ranks .v-e .ranks-e-slab { position: relative; height: 80px; transform: skewX(var(--tilt)); }
.s-ranks .v-e .ranks-e-in {
  height: 100%; transform: skewX(calc(-1 * var(--tilt)));
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center;
  column-gap: calc(24px * var(--space)); padding-inline: var(--card-pad);
}
.s-ranks .v-e .ranks-e-badge { width: 52px; height: 52px; }
.s-ranks .v-e .ranks-e-label { font-size: 32px; }
.s-ranks .v-e .ranks-e-value { font-size: min(calc(44px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(40cqi / (max(5, var(--rank-chars, 5)) * var(--num-w)))); }
.s-ranks .v-e .ranks-e-stack { container-type: inline-size; }
.s-ranks .v-e .ranks-e-key { height: 120px; }
.s-ranks .v-e .ranks-e-key .ranks-e-badge { width: 84px; height: 84px; }
/* 3 px lines: 2.31 on the 52 px slab badges, 1.43 on the 84 px key badge */
.s-ranks .v-e .ranks-e-badge svg g { stroke-width: 2.31; }
.s-ranks .v-e .ranks-e-key .ranks-e-badge svg g { stroke-width: 1.43; }
.s-ranks .v-e .ranks-e-key .ranks-e-label { color: var(--ink-1); font-size: 32px; }
.s-ranks .v-e .ranks-e-key .ranks-e-value { font-size: min(calc(72px / var(--cap) * min(1, 3 / max(3, var(--rank-chars, 3)))), calc(50cqi / (max(6, var(--rank-chars, 6)) * var(--num-w)))); }

/* sponsor: designs A to E, all for Monster Energy. Every rule is scoped under .s-sponsor .v-<letter>.
   The lockup (claw mark, MONSTER ENERGY wordmark) and the brand colours come from the kit in mscreens/_ads.css,
   the same one the machine's sponsor slot draws with; each design keeps its own shape and sets the lockup its way. */

/* A: centred credit. The host's quiet Powered by, then the brand's own lockup in one line. */
.s-sponsor .v-a b.mon-lock { display: inline-flex; align-items: center; gap: 16px; }
.s-sponsor .v-a .mon-claw { width: 36px; height: 48px; }
/* the design's own rules (Arena's and Reference's) style every span in it as a label, so the wordmark restates its
   type here, matching their weight so this later sheet wins */
:root .s-sponsor .v-a span.mon-word { font: 400 42px/1 "Anton", "Archivo Black", sans-serif; letter-spacing: .012em; text-transform: uppercase; color: var(--ink-1); }
:root .s-sponsor .v-a span.mon-word > span { font: inherit; letter-spacing: inherit; color: var(--mon-mark); }

/* B: sponsor card. One card across the column: the brand's own lockup on the left, the offer and what to do with it
   on the right, both on the card's one padding. */
.s-sponsor .v-b .sponsor-b-card {
  container-type: inline-size;
  display: flex; align-items: center; justify-content: space-between; gap: calc(32px * var(--space));
  height: calc(104px + 12px * var(--space)); padding-inline: var(--card-pad);
}
.s-sponsor .v-b .sponsor-b-name { display: flex; align-items: center; gap: 16px; margin: 0; font-size: min(50px, 5.4cqi); }
.s-sponsor .v-b .sponsor-b-name .mon-claw { width: 1em; height: 1.3em; }
.s-sponsor .v-b .sponsor-b-body { min-width: 0; display: grid; justify-items: end; gap: 12px; text-align: right; }
.s-sponsor .v-b .sponsor-b-offer { font-size: 32px; line-height: 1.1; color: var(--ink-1); white-space: nowrap; }
.s-sponsor .v-b .sponsor-b-desk { font-size: 32px; white-space: nowrap; }

/* C: two sides. A quiet footer. The hairline is a strength tester's scale laid on its side,
   ticks growing taller toward the right; who powers the machine sits left, where it stands sits right. */
.s-sponsor .v-c { container-type: inline-size; display: grid; gap: calc(24px * var(--space)); }
.s-sponsor .v-c .sponsor-c-scale { position: relative; height: 20px; border-top: 2px solid var(--line); }
.s-sponsor .v-c .sponsor-c-ticks {
  position: absolute; left: 0; right: 0; top: 0; height: 18px;
  background:
    repeating-linear-gradient(90deg, var(--ink-3) 0 2px, transparent 2px 10%),
    repeating-linear-gradient(90deg, var(--track) 0 2px, transparent 2px 2%);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 22%);
}
.s-sponsor .v-c .sponsor-c-ticks::after { content: ""; position: absolute; right: 0; top: 0; bottom: 0; width: 2px; background: var(--ink-3); }
.s-sponsor .v-c .sponsor-c-row { display: flex; align-items: center; justify-content: space-between; gap: calc(32px * var(--space)); }
.s-sponsor .v-c .sponsor-c-credit,
.s-sponsor .v-c .sponsor-c-venue { font-size: 32px; line-height: 1; white-space: nowrap; color: var(--ink-3); }
.s-sponsor .v-c .sponsor-c-credit { display: flex; align-items: center; gap: 12px; }
.s-sponsor .v-c .sponsor-c-credit b.mon-lock { display: inline-flex; align-items: center; gap: 10px; }
.s-sponsor .v-c .sponsor-c-credit .mon-claw { width: 26px; height: 34px; }
.s-sponsor .v-c .sponsor-c-credit .mon-word { font-size: 32px; }
.s-sponsor .v-c .sponsor-c-venue { display: flex; align-items: center; gap: 16px; color: var(--ink-2); }
.s-sponsor .v-c .sponsor-c-pin { width: 44px; height: 44px; }
/* every line icon on the glass draws 3 glass px: 3 x 40 / 44 */
.s-sponsor .v-c .sponsor-c-pin svg g { stroke-width: 2.73; }

/* D: ticket. An arcade redemption ticket as the machine would print it, notched at both ends: the brand on one half,
   the run code and the offer on the other, two equal halves on the card's one padding. */
.s-sponsor .v-d { container-type: inline-size; --d-notch: 16px; }
.s-sponsor .v-d .sponsor-d-ticket {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: center; column-gap: var(--gap-grid);
  height: calc(100px + 14px * var(--space)); padding-inline: var(--card-pad);
  border-radius: calc(var(--r) * .6);
  -webkit-mask-image:
    radial-gradient(circle at 0 50%, transparent var(--d-notch), rgba(0, 0, 0, 1) calc(var(--d-notch) + .5px)),
    radial-gradient(circle at 100% 50%, transparent var(--d-notch), rgba(0, 0, 0, 1) calc(var(--d-notch) + .5px));
  mask-image:
    radial-gradient(circle at 0 50%, transparent var(--d-notch), rgba(0, 0, 0, 1) calc(var(--d-notch) + .5px)),
    radial-gradient(circle at 100% 50%, transparent var(--d-notch), rgba(0, 0, 0, 1) calc(var(--d-notch) + .5px));
  -webkit-mask-composite: source-in; mask-composite: intersect;
}
.s-sponsor .v-d .sponsor-d-brand,
.s-sponsor .v-d .sponsor-d-copy { display: grid; gap: 12px; min-width: 0; }
.s-sponsor .v-d .sponsor-d-copy { justify-items: end; text-align: right; }
.s-sponsor .v-d .sponsor-d-by { font-size: 32px; color: var(--ink-3); }
.s-sponsor .v-d .sponsor-d-name { display: flex; align-items: center; gap: 12px; margin: 0; font-size: 40px; }
.s-sponsor .v-d .sponsor-d-name .mon-claw { width: 34px; height: 46px; }
.s-sponsor .v-d .sponsor-d-code { font-size: 32px; white-space: nowrap; }
.s-sponsor .v-d .sponsor-d-offer { font-size: min(calc(44px / var(--cap)), 7.6cqi); color: var(--ink-1); }

/* E: seal. A round seal read as a force gauge: the dial ticks sweep round and stop short at the base, the claw mark
   torn across the disc; the wordmark and its role set beside it as one centred lockup. */
.s-sponsor .v-e { container-type: inline-size; }
.s-sponsor .v-e .sponsor-e-lockup { display: flex; align-items: center; justify-content: center; gap: calc(32px * var(--space)); }
.s-sponsor .v-e .sponsor-e-seal { position: relative; flex: none; width: 116px; height: 116px; display: grid; place-items: center; }
.s-sponsor .v-e .sponsor-e-dial { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.s-sponsor .v-e .sponsor-e-minor,
.s-sponsor .v-e .sponsor-e-major { fill: none; stroke-linecap: round; }
.s-sponsor .v-e .sponsor-e-minor { stroke: var(--ink-3); stroke-width: 1.6; }
.s-sponsor .v-e .sponsor-e-major { stroke: var(--ink-1); stroke-width: 2.6; }
.s-sponsor .v-e .sponsor-e-disc { position: absolute; left: 50%; top: 50%; width: 82px; height: 82px; translate: -50% -50%; border-radius: 50%; }
.s-sponsor .v-e .sponsor-e-claw { position: relative; width: 38px; height: 50px; }
.s-sponsor .v-e .sponsor-e-copy { display: grid; gap: 16px; min-width: 0; }
.s-sponsor .v-e .sponsor-e-name { margin: 0; }
.s-sponsor .v-e .sponsor-e-name .mon-word { font-size: 46px; }
.s-sponsor .v-e .sponsor-e-role { font-size: 32px; white-space: nowrap; }

/* ---------------------------------------------------------------- Light: the same designs on a daylight ground */

/* C: the pin's badge tone is built to sit on a white card; on the bare ground it vanished, so here it is the card */
:root[data-appearance="light"] .s-sponsor .v-c .sponsor-c-pin { background: var(--raised); box-shadow: inset 0 0 0 2px var(--line); }


/* stats: designs B to E. Scope every rule under .s-stats .v-<letter>. */

/* A  Card grid lives in styles.css. The Lucide gauge is open at the bottom, so its ink sits high in the badge: one grid unit down centres it */
.s-stats .v-a .badge[data-glyph="speed"] svg g { transform: translateY(1px); }

/* B  Rings: four round dials, a tachometer scale around each, the arc reads against this machine's best */
.s-stats .v-b .stats-b-energy { --share: .72; }
.s-stats .v-b .stats-b-force { --share: .86; }
.s-stats .v-b .stats-b-speed { --share: .64; }
.s-stats .v-b .stats-b-acc { --share: .78; }
.s-stats .v-b .stats-b-row { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--gap-grid); }
.s-stats .v-b .stats-b-gauge { min-width: 0; display: grid; justify-items: center; gap: calc(24px * var(--space)); }
.s-stats .v-b .stats-b-dial {
  position: relative; width: 100%; aspect-ratio: 1; border-radius: 50%;
  display: grid; place-items: center;
}
.s-stats .v-b .stats-b-svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible; }
.s-stats .v-b .stats-b-major, .s-stats .v-b .stats-b-minor { fill: none; stroke: var(--ink-3); stroke-linecap: butt; }
.s-stats .v-b .stats-b-major { stroke-width: 3; }
.s-stats .v-b .stats-b-minor { stroke-width: 2; opacity: .7; }
.s-stats .v-b .stats-b-track, .s-stats .v-b .stats-b-arc { fill: none; stroke-width: 18; stroke-linecap: butt; }
.s-stats .v-b .stats-b-track { stroke: var(--track); }
.s-stats .v-b .stats-b-arc { stroke: var(--ink-1); stroke-dasharray: 100 200; stroke-dashoffset: calc(100 - var(--share) * 100); }
.s-stats .v-b .stats-b-needle {
  fill: none; stroke: var(--ink-1); stroke-width: 5;
  transform-box: view-box; transform-origin: 100px 100px; transform: rotate(calc(var(--share) * 270deg));
}
.s-stats .v-b .stats-b-read { container-type: inline-size; width: 48%; display: grid; justify-items: center; }
.s-stats .v-b .stats-b-value {
  font-size: min(calc(40px / var(--cap)), calc(100cqi / (4 * var(--num-w))));
  font-variant-numeric: tabular-nums;
}
.s-stats .v-b .stats-b-unit { position: absolute; left: 0; right: 0; bottom: 13%; text-align: center; font-size: 32px; color: var(--ink-3); }
.s-stats .v-b .stats-b-label { font-size: 32px; color: var(--ink-1); }
.s-stats .v-b .stats-b-note { margin-top: calc(32px * var(--space)); text-align: center; font-size: 32px; color: var(--ink-3); }

/* C  Power bars: four slanted tubes, each filled in ink to its share, the reading rides the tip of the fill */
.s-stats .v-c .stats-c-energy { --share: .72; }
.s-stats .v-c .stats-c-force { --share: .86; }
.s-stats .v-c .stats-c-speed { --share: .64; }
.s-stats .v-c .stats-c-acc { --share: .78; }
.s-stats .v-c { --slant: 12deg; --bar-h: 100px; --inset: 12px; }
.s-stats .v-c .stats-c-head { margin: 0 calc(var(--bar-h) * .22) calc(20px * var(--space)) 0; text-align: right; font-size: 32px; color: var(--ink-3); }
.s-stats .v-c .stats-c-list { display: grid; gap: var(--gap-grid); padding-inline: calc(var(--bar-h) * .11 + 2px); }
.s-stats .v-c .stats-c-bar {
  position: relative; height: var(--bar-h); padding: var(--inset);
  transform: skewX(calc(-1 * var(--slant)));
}
.s-stats .v-c .stats-c-bar::before {
  content: ""; position: absolute; inset: var(--inset); pointer-events: none;
  border-radius: max(0px, calc(var(--r) - var(--inset)));
  background: repeating-linear-gradient(90deg, var(--track) 0 16px, transparent 16px 26px);
}
.s-stats .v-c .stats-c-fill {
  position: relative; width: calc(var(--share) * 100%); height: 100%;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding-inline: 28px 24px;
  border-radius: max(0px, calc(var(--r) - var(--inset)));
  background: var(--ink-1); color: var(--ground);
  box-shadow: var(--display-glow);
}
.s-stats .v-c .stats-c-fill > * { transform: skewX(var(--slant)); }
.s-stats .v-c .stats-c-label { font-size: 32px; color: var(--ground); }
.s-stats .v-c .stats-c-read { display: flex; align-items: baseline; gap: 12px; }
.s-stats .v-c .stats-c-num { container-type: inline-size; width: 190px; display: grid; justify-items: end; }
.s-stats .v-c .stats-c-value {
  font-size: min(calc(46px / var(--cap)), calc(100cqi / (4 * var(--num-w))));
  font-variant-numeric: tabular-nums; text-shadow: none;
}
.s-stats .v-c .stats-c-unit { min-width: 64px; font-size: 32px; letter-spacing: .08em; color: var(--ground); opacity: .72; }

/* D  Radar: the four readings plotted as a kite that juts toward force, the numbers on one card beneath.
      No sunburst behind the chart and no rules between the readings: the grid spaces them, a line between two words reads as a dash. */
.s-stats .v-d { display: grid; gap: calc(24px * var(--space)); }
.s-stats .v-d .stats-d-field { position: relative; display: grid; justify-items: center; }
.s-stats .v-d .stats-d-note { position: absolute; top: 0; right: 0; width: 280px; text-align: right; font-size: 32px; line-height: 1.25; color: var(--ink-3); }
.s-stats .v-d .stats-d-radar { position: relative; width: min(480px, 100% - 300px); display: grid; justify-items: center; row-gap: 16px; }
.s-stats .v-d .stats-d-svg { display: block; width: 100%; height: auto; overflow: visible; }
.s-stats .v-d .stats-d-ring, .s-stats .v-d .stats-d-axis { fill: none; stroke: var(--line); stroke-width: 2; }
.s-stats .v-d .stats-d-best { fill: none; stroke: var(--ink-3); stroke-width: 3; }
.s-stats .v-d .stats-d-shape { fill: var(--ink-1); fill-opacity: .22; stroke: var(--ink-1); stroke-width: 6; stroke-linejoin: round; }
.s-stats .v-d .stats-d-dot { fill: var(--ink-1); }
.s-stats .v-d .stats-d-axis-label { font-size: 32px; color: var(--ink-1); }
.s-stats .v-d .stats-d-left, .s-stats .v-d .stats-d-right { position: absolute; top: 50%; transform: translateY(-50%); }
.s-stats .v-d .stats-d-left { right: calc(100% + 22px); }
.s-stats .v-d .stats-d-right { left: calc(100% + 22px); }
.s-stats .v-d .stats-d-values { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); column-gap: var(--gap-grid); padding: var(--card-pad); }
.s-stats .v-d .stats-d-cell { min-width: 0; display: grid; justify-items: center; gap: 16px; }
.s-stats .v-d .stats-d-key { font-size: 32px; }
.s-stats .v-d .stats-d-read { container-type: inline-size; width: 100%; display: flex; justify-content: center; align-items: baseline; gap: 10px; }
.s-stats .v-d .stats-d-value {
  font-size: min(calc(44px / var(--cap)), calc(56cqi / (4 * var(--num-w))));
  font-variant-numeric: tabular-nums;
}
.s-stats .v-d .stats-d-unit { font-size: 32px; letter-spacing: .04em; color: var(--ink-3); }

/* E  Force first: force on its own raised card across the column, speed lines driving into the number, the other three
      readings on three equal cards beneath. Level and on the margins: no tilt, no bleed. */
.s-stats .v-e .stats-e-stage { display: grid; gap: var(--gap-grid); }
.s-stats .v-e .stats-e-slab { position: relative; overflow: hidden; }
.s-stats .v-e .stats-e-slab-in {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; column-gap: calc(32px * var(--space));
  padding: var(--card-pad);
}
.s-stats .v-e .stats-e-id { display: grid; justify-items: start; gap: 20px; }
.s-stats .v-e .stats-e-badge { width: 88px; height: 88px; }
.s-stats .v-e .stats-e-badge svg g { stroke-width: 1.36; }
.s-stats .v-e .stats-e-kicker { font-size: 32px; color: var(--ink-1); }
.s-stats .v-e .stats-e-lines {
  display: block; width: 100%; height: 132px; color: var(--ink-1);
  -webkit-mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 75%);
  mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), rgba(0, 0, 0, 1) 75%);
}
.s-stats .v-e .stats-e-lines path { fill: currentColor; }
.s-stats .v-e .stats-e-s0 { opacity: .55; }
.s-stats .v-e .stats-e-s1 { opacity: .32; }
.s-stats .v-e .stats-e-s2 { opacity: .22; }
.s-stats .v-e .stats-e-s3 { opacity: .4; }
.s-stats .v-e .stats-e-hit { display: flex; align-items: baseline; gap: 16px; }
.s-stats .v-e .stats-e-num { container-type: inline-size; width: 180px; display: grid; justify-items: end; }
.s-stats .v-e .stats-e-value {
  font-size: min(calc(72px / var(--cap)), calc(100cqi / (4 * var(--num-w))));
  font-variant-numeric: tabular-nums;
}
.s-stats .v-e .stats-e-unit { font-size: calc(40px / var(--cap)); color: var(--ink-2); }
.s-stats .v-e .stats-e-tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--gap-grid); }
.s-stats .v-e .stats-e-tile { min-width: 0; padding: var(--card-pad); }
.s-stats .v-e .stats-e-tile-in { display: grid; gap: calc(20px * var(--space)); }
.s-stats .v-e .stats-e-label { font-size: 32px; }
.s-stats .v-e .stats-e-tile-read { container-type: inline-size; display: flex; align-items: baseline; gap: 12px; }
.s-stats .v-e .stats-e-tile-value {
  font-size: min(calc(44px / var(--cap)), calc(64cqi / (4 * var(--num-w))));
  font-variant-numeric: tabular-nums;
}
.s-stats .v-e .stats-e-tile-unit { font-size: 32px; color: var(--ink-3); }

/* Unit symbols are case sensitive (kJ, since a capital K is kelvin; acceleration is m/s², M/S would read as a speed),
   so every unit keeps the case it is written in, inside labels that are otherwise set in capitals */
.s-stats .v-b .stats-b-unit, .s-stats .v-c .stats-c-unit, .s-stats .v-d .stats-d-unit,
.s-stats .v-e .stats-e-unit, .s-stats .v-e .stats-e-tile-unit { text-transform: none; }

/* Light: the same readings on a daylight ground.
   D: the kite keeps its line and loses its murk. */
:root[data-appearance="light"] .s-stats .v-d .stats-d-shape { fill-opacity: .08; }
/* C: a white tube needs a firmer rim than a dark one to hold its edge against the paper */
:root[data-appearance="light"] .s-stats .v-c .stats-c-bar { border-color: var(--line); }

/* video: designs B to E. Scope every rule under .s-video .v-<letter>.
   Red appears once per design: the contact mark in B, the replay progress in C, D and E.
   Round nine review: every design plays Sara's reel (video.rv, driven by the script at the foot of video.html); the
   progress fills read --rv, the share of the reel played, which the script sets on the design. No play keys: the glass
   takes no touch and the reel runs by itself. */
.s-video .rv { display: block; width: 100%; height: 100%; object-fit: cover; object-position: 50% 50%; background: #000; }
.s-video .player > .rv { position: absolute; inset: 0; }
:root .s-video .timeline .progress { width: calc(var(--rv, .294) * 100%); }

/* B  Filmstrip: a wide player, and under it six frames of the hit on the six columns, contact ringed and marked.
      Level and on the margins (the strip used to lie tilted across the player's lower edge and past both margins). */
.s-video .v-b .video-b-wrap { display: grid; gap: var(--gap-grid); }
.s-video .v-b .video-b-player { aspect-ratio: 7 / 3; border-radius: var(--r); background: rgba(0, 0, 0, 1); }
.s-video .v-b .video-b-control {
  position: absolute; z-index: 2; top: calc(32px * var(--space)); left: calc(32px * var(--space));
  display: flex; align-items: center; gap: 20px; padding: 20px 32px; border-radius: 999px;
}
.s-video .v-b .video-b-control-copy { display: grid; gap: 8px; }
.s-video .v-b .video-b-replay { color: inherit; font-size: 32px; text-box: trim-both cap alphabetic; }
.s-video .v-b .video-b-time { font-size: 32px; line-height: 1; color: rgba(255, 255, 255, .82); font-variant-numeric: tabular-nums; }
.s-video .v-b .video-b-strip { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); align-items: start; gap: var(--gap-grid); }
.s-video .v-b .video-b-frame { aspect-ratio: 4 / 3; border-radius: calc(var(--r) * .5); background: var(--track); }
.s-video .v-b .video-b-strip > .video-b-frame { opacity: .62; transition: opacity .2s ease; }
/* the frame nearest the reel's playhead lights (contact is always lit) */
.s-video .v-b .video-b-strip > .video-b-frame.is-now { opacity: 1; }
.s-video .v-b .video-b-contact { position: relative; display: grid; justify-items: center; gap: 16px; }
.s-video .v-b .video-b-contact .video-b-frame { width: 100%; box-shadow: 0 0 0 4px var(--ink-1); border-bottom: 6px solid var(--strike); }
.s-video .v-b .video-b-mark { font-size: 32px; color: var(--ink-1); white-space: nowrap; }

/* C  Phone clip: the replay held upright in a drawn phone on the first column, the line and the replay on the other two */
.s-video .v-c .video-c-wrap { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); column-gap: var(--gap-grid); }
.s-video .v-c .video-c-phone { position: relative; height: 540px; padding: 12px 16px; border-radius: 52px; }
.s-video .v-c .video-c-screen { height: 100%; border-radius: 40px; background: rgba(0, 0, 0, 1); }
.s-video .v-c .video-c-screen::before { content: ""; position: absolute; z-index: 2; left: 0; right: 0; bottom: 0; height: 30%; background: linear-gradient(to top, rgba(0, 0, 0, .66), rgba(0, 0, 0, 0)); }
.s-video .v-c .video-c-island { position: absolute; z-index: 3; top: 14px; left: 50%; width: 92px; height: 28px; border-radius: 14px; background: rgba(0, 0, 0, .94); transform: translateX(-50%); }
.s-video .v-c .video-c-scrub { position: absolute; z-index: 3; left: 26px; right: 26px; bottom: 30px; height: 8px; border-radius: 4px; background: rgba(255, 255, 255, .3); }
.s-video .v-c .video-c-scrub-fill { display: block; width: calc(var(--rv, .294) * 100%); height: 100%; border-radius: inherit; }

.s-video .v-c .video-c-copy {
  grid-column: 2 / span 2; container-type: inline-size; min-width: 0;
  display: grid; grid-template-columns: minmax(0, 1fr); align-content: space-between; padding: 36px 0 24px var(--card-pad);
}
.s-video .v-c .video-c-head { display: grid; gap: calc(28px * var(--space)); }
.s-video .v-c .video-c-title { display: grid; gap: 12px; font-size: min(calc(72px / var(--cap)), calc(100cqi / (11 * .53))); }
.s-video .v-c .video-c-title span { display: block; text-box: trim-both cap alphabetic; }
.s-video .v-c .video-c-line { color: var(--ink-2); text-wrap: balance; }
.s-video .v-c .video-c-play { display: flex; align-items: baseline; gap: 24px; }
.s-video .v-c .video-c-play-label { font-size: 32px; color: var(--ink-1); }
.s-video .v-c .video-c-time { font-size: 32px; line-height: 1; color: var(--ink-2); font-variant-numeric: tabular-nums; }

/* D  Cinema: the replay runs to the glass edges, letterbox bars carry the credits and the progress */
.s-video .v-d .video-d-scope { margin-inline: calc(-1 * var(--pad)); height: 556px; background: rgba(0, 0, 0, 1); }
.s-video .v-d .video-d-scrim {
  position: absolute; inset: 0; z-index: 2;
  background:
    linear-gradient(to left, rgba(0, 0, 0, .62), rgba(0, 0, 0, 0) 58%),
    linear-gradient(to top, rgba(0, 0, 0, .7), rgba(0, 0, 0, 0) 48%);
}
.s-video .v-d .video-d-bar { position: absolute; z-index: 3; left: 0; right: 0; background: rgba(0, 0, 0, .9); }
.s-video .v-d .video-d-top { top: 0; height: 52px; display: flex; align-items: center; justify-content: space-between; padding-inline: var(--pad); }
.s-video .v-d .video-d-cap { font-size: 32px; color: var(--ink-2); }
.s-video .v-d .video-d-title {
  position: absolute; z-index: 3; right: var(--pad); bottom: calc(84px + 36px * var(--space));
  font-size: calc(72px / var(--cap)); color: var(--ink-1); text-box: trim-both cap alphabetic;
}
.s-video .v-d .video-d-bottom { bottom: 0; height: 84px; }
.s-video .v-d .video-d-line { position: absolute; left: 0; right: 0; top: 0; height: 6px; background: rgba(255, 255, 255, .2); }
.s-video .v-d .video-d-fill { display: block; width: calc(var(--rv, .294) * 100%); height: 100%; }
.s-video .v-d .video-d-row { height: 100%; padding: 6px var(--pad) 0; display: flex; align-items: center; justify-content: space-between; }
.s-video .v-d .video-d-time { font-size: 32px; line-height: 1; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.s-video .v-d .video-d-replay { display: flex; align-items: center; gap: 16px; color: var(--ink-1); }

/* E  Reel and contact: the reel and its moment of contact cut apart on a slant, stamped, one progress line beneath */
.s-video .v-e .video-e-wrap { display: grid; gap: calc(28px * var(--space)); }
.s-video .v-e .video-e-pair { position: relative; height: 470px; }
.s-video .v-e .video-e-shot { position: absolute; top: 0; bottom: 0; width: 58%; margin: 0; border-radius: var(--r); background: rgba(0, 0, 0, 1); }
.s-video .v-e .video-e-shot > img { display: block; }
.s-video .v-e .video-e-windup { left: 0; clip-path: polygon(0 0, calc(100% - 10px) 0, calc(72.41% - 10px) 100%, 0 100%); }
.s-video .v-e .video-e-hit { right: 0; clip-path: polygon(calc(27.59% + 10px) 0, 100% 0, 100% 100%, 10px 100%); }
.s-video .v-e .video-e-stamp {
  position: absolute; z-index: 3; color: var(--ink-1);
  border: 3px solid currentColor; border-radius: 6px; background: rgba(0, 0, 0, .42);
  transform: rotate(-6deg);
}
.s-video .v-e .video-e-stamp-a { top: calc(36px * var(--space)); left: calc(36px * var(--space)); padding: 12px 20px; font-size: 32px; }
.s-video .v-e .video-e-stamp-b {
  right: calc(40px * var(--space)); bottom: calc(40px * var(--space)); padding: 16px 24px 16px;
  letter-spacing: .04em; font-size: calc(48px / var(--cap));
}
.s-video .v-e .video-e-time { display: grid; gap: 16px; }
.s-video .v-e .video-e-line { height: 6px; border-radius: 3px; background: var(--track); overflow: hidden; }
.s-video .v-e .video-e-fill { display: block; width: calc(var(--rv, .294) * 100%); height: 100%; border-radius: inherit; }
.s-video .v-e .video-e-ends { display: flex; justify-content: space-between; color: var(--ink-2); }
.s-video .v-e .video-e-ends .text { font-size: 32px; line-height: 1; font-variant-numeric: tabular-nums; }

/* ---------------------------------------------------------------- Light
   The photographs stay dark, the chrome around them joins the daylight page.
   Anything that sits on a photograph or on film keeps photo ink (white); anything on the page takes the page tokens. */

/* D: the letterbox bars become the page itself, so credits and controls sit on daylight and the photograph is the band between them */
:root[data-appearance="light"] .s-video .v-d .video-d-scope { background: transparent; }
:root[data-appearance="light"] .s-video .v-d .video-d-scope > :is(img, video) { margin-top: 56px; height: calc(100% - 136px); }
:root[data-appearance="light"] .s-video .v-d .video-d-scrim { inset: 52px 0 84px; }
:root[data-appearance="light"] .s-video .v-d .video-d-bar { background: transparent; }
:root[data-appearance="light"] .s-video .v-d .video-d-line { background: var(--track); }
:root[data-appearance="light"] .s-video .v-d .video-d-title { color: #FFFFFF; }

/* E: the stamps become paper labels stuck on the photographs, ink on white */
:root[data-appearance="light"] .s-video .v-e .video-e-stamp {
  background: var(--raised); color: var(--ink-1);
  box-shadow: 0 10px 24px -12px rgba(0, 0, 0, .55);
}

mscreens.css:
/* The sponsor slot shared by every machine flow screen (parts/ms-ad.html), and the Monster Energy brand kit that the
   slot and the Result screen's sponsor section (sections/sponsor.*) both draw from.

   The kit: the brand's own colours, an original claw mark (three torn scratches swiped on a diagonal, drawn for this
   project, not the brand's logo file) and a MONSTER ENERGY wordmark set in heavy condensed type. A sponsor's lockup
   keeps its own type and colour whatever the host look is, so these ignore Arena and Reference; only the claw's green
   darkens on a daylight ground, where the brand lime would fall to 1.7:1. */
:root {
  --mon-green: #95D600;
  --mon-black: #080908;
  --mon-steel: #C9CCC6;
  --mon-mark: var(--mon-green);
}
:root[data-appearance="light"] { --mon-mark: #4F8C00; }

.mon-claw { display: block; flex: none; overflow: visible; fill: var(--mon-mark); }

/* stacked: MONSTER over a tracked-out ENERGY in the brand green, the two lines one width */
.mon-word {
  display: inline-grid; justify-items: center; align-content: center;
  font: 400 1em/.86 "Anton", "Archivo Black", sans-serif; letter-spacing: .012em; text-transform: uppercase;
  color: var(--mon-ink, var(--ink-1)); white-space: nowrap; font-synthesis: none;
}
.mon-word > span {
  display: block; margin-top: .14em; padding-left: 1.02em;
  font: 700 .38em/1 "Barlow Condensed", "Barlow", sans-serif; letter-spacing: 1.02em; color: var(--mon-mark);
}
/* in one line: the same two words side by side, ENERGY in green at the same size */
.mon-word.is-line { display: inline-flex; align-items: baseline; gap: .26em; line-height: 1; }
.mon-word.is-line > span { margin: 0; padding: 0; font: inherit; letter-spacing: inherit; }

/* ---------------------------------------------------------------- the slot: a 1080 x 140 media unit
   Same size and place on every flow screen. Read from a metre: the CTA is 38 px, the frames' big words 72 px.
   The loop is 7 s and moves in hard cuts, the way a banner GIF does, never a tween:
     0 to 2 %    the claws rip in, three frames, and the can slams down
     2 to 33 %   frame one, the wordmark
     33 to 35 %  green flash, then a lone bolt
     35 to 64 %  frame two, Refuel between rounds
     64 to 66 %  green flash, then a lone bolt
     66 to 95 %  frame three, Ice cold at the kiosk
     95 to 100 % the end card: can and CTA alone, the CTA knocks twice
   The CTA and the AD tag never leave. Two flashes in seven seconds stays far under three a second. */
.mscreen .ms-ad {
  --mon-ink: #FFFFFF;
  --mon-mark: var(--mon-green);
  --ad-loop: 7s;
  position: absolute; z-index: 3; left: 0; right: 0; bottom: 0; height: var(--ms-ad-h); margin: 0; overflow: hidden;
  background:
    radial-gradient(120px 110px at 118px 70px, rgba(149, 214, 0, .24), transparent 70%),
    repeating-linear-gradient(118deg, rgba(149, 214, 0, .055) 0 2px, transparent 2px 16px),
    var(--mon-black);
  box-shadow: inset 0 3px 0 var(--mon-green);
  color: var(--mon-ink);
}
.mscreen .ms-ad-art { position: absolute; inset: 0; }
.mscreen .ms-ad-art > * { animation-duration: var(--ad-loop); animation-iteration-count: infinite; animation-timing-function: steps(1, end); }

/* the rip: a big claw mark torn through the ground behind the copy */
.mscreen .ms-ad-rip {
  position: absolute; left: 470px; top: -34px; width: 176px; height: 212px;
  fill: var(--mon-green); opacity: .26;
  animation-name: ms-ad-rip;
}
@keyframes ms-ad-rip {
  0% { clip-path: inset(0 0 100% 0); }
  1% { clip-path: inset(0 0 62% 0); }
  2% { clip-path: inset(0 0 26% 0); }
  3%, 100% { clip-path: inset(0); }
}

/* the can: black, a steel lid and foot, the claw on its face; it drops in and shakes on each flash */
.mscreen .ms-ad-can {
  position: absolute; left: 88px; top: 16px; width: 62px; height: 110px; z-index: 2;
  display: grid; place-items: center;
  border-radius: 10px / 8px;
  background: linear-gradient(90deg, #030303 0%, #2E302C 20%, #111210 44%, #000 68%, #262824 90%, #070707 100%);
  box-shadow: 0 0 22px rgba(149, 214, 0, .32);
  transform: rotate(-8deg);
  animation-name: ms-ad-can;
}
.mscreen .ms-ad-can::before,
.mscreen .ms-ad-can::after {
  content: ""; position: absolute; left: 4px; right: 4px; border-radius: 50%;
  background: linear-gradient(90deg, #6E716B, #E2E4DF 34%, #8C8F89 60%, #D6D8D2 84%, #74776F);
}
.mscreen .ms-ad-can::before { top: -5px; height: 12px; }
.mscreen .ms-ad-can::after { bottom: -3px; height: 8px; }
.mscreen .ms-ad-can .mon-claw { width: 40px; height: 54px; }
@keyframes ms-ad-can {
  0% { transform: translateY(-150px) rotate(-8deg); }
  1% { transform: translateY(-46px) rotate(-15deg); }
  2% { transform: translateY(7px) rotate(-3deg); }
  3% { transform: rotate(-8deg); }
  33% { transform: rotate(-1deg); }
  34% { transform: translateX(-4px) rotate(-15deg); }
  35% { transform: rotate(-8deg); }
  64% { transform: rotate(-1deg); }
  65% { transform: translateX(-4px) rotate(-15deg); }
  66% { transform: rotate(-8deg); }
  100% { transform: rotate(-8deg); }
}

/* the three frames share one column beside the can; each punches in (too big, too small, set) over three steps */
.mscreen .ms-ad-f {
  position: absolute; left: 196px; top: 0; bottom: 0; z-index: 1;
  display: flex; flex-direction: column; justify-content: center; align-items: flex-start;
  transform-origin: 0 50%; opacity: 0;
  text-transform: uppercase; white-space: nowrap; font-synthesis: none;
}
.mscreen .ms-ad-f1 { font-size: 76px; animation-name: ms-ad-f1; }
.mscreen .ms-ad-f1 .mon-word { transform: skewX(-7deg); }
.mscreen .ms-ad-still { display: none; }
.mscreen :is(.ms-ad-f2, .ms-ad-f3) { gap: 8px; animation-name: ms-ad-f2; }
.mscreen .ms-ad-f3 { animation-name: ms-ad-f3; }
.mscreen :is(.ms-ad-f2, .ms-ad-f3) b {
  font: 400 72px/.86 "Anton", "Archivo Black", sans-serif; letter-spacing: .012em; color: var(--mon-green);
  transform: skewX(-7deg);
}
.mscreen :is(.ms-ad-f2, .ms-ad-f3) span {
  font: 700 36px/1 "Barlow Condensed", "Barlow", sans-serif; letter-spacing: .08em; color: var(--mon-ink);
}
@keyframes ms-ad-f1 {
  0% { opacity: 0; }
  2% { opacity: 1; transform: scale(1.16); }
  3% { transform: scale(.95); }
  4% { transform: none; }
  33%, 100% { opacity: 0; }
}
@keyframes ms-ad-f2 {
  0% { opacity: 0; }
  35% { opacity: 1; transform: scale(1.16); }
  36% { transform: scale(.95); }
  37% { transform: none; }
  64%, 100% { opacity: 0; }
}
@keyframes ms-ad-f3 {
  0% { opacity: 0; }
  66% { opacity: 1; transform: scale(1.16); }
  67% { transform: scale(.95); }
  68% { transform: none; }
  95%, 100% { opacity: 0; }
}

/* green lightning: a lone bolt after each flash, and a flicker in the middle of each frame, out past the copy */
.mscreen .ms-ad-bolt {
  position: absolute; left: 300px; top: -8px; width: 132px; height: 156px; z-index: 1;
  fill: var(--mon-green); filter: drop-shadow(0 0 10px rgba(149, 214, 0, .7));
  opacity: 0; animation-name: ms-ad-bolt;
}
@keyframes ms-ad-bolt {
  0% { opacity: 0; }
  17% { opacity: 1; transform: translate(292px, 34px) scale(.5); }
  18% { opacity: 0; }
  34% { opacity: 1; transform: none; }
  35% { opacity: 0; }
  49% { opacity: 1; transform: translate(292px, 34px) scale(.5) scaleX(-1); }
  50% { opacity: 0; }
  65% { opacity: 1; transform: scaleX(-1); }
  66% { opacity: 0; }
  81% { opacity: 1; transform: translate(292px, 34px) scale(.5); }
  82%, 100% { opacity: 0; }
}

/* the flash: one frame of solid brand green with the bolt knocked out in black */
.mscreen .ms-ad-flash {
  position: absolute; inset: 0; z-index: 3; display: grid; place-items: center;
  background: var(--mon-green); opacity: 0;
  animation-name: ms-ad-flash;
}
.mscreen .ms-ad-flash svg { width: 150px; height: 176px; fill: var(--mon-black); }
@keyframes ms-ad-flash {
  0% { opacity: 0; }
  33% { opacity: 1; }
  34% { opacity: 0; }
  64% { opacity: 1; }
  65%, 100% { opacity: 0; }
}

/* the CTA: a slanted green plate; it turns black on the flashes and knocks twice on the end card */
.mscreen .ms-ad-cta {
  position: absolute; right: 40px; top: 27px; height: 86px; z-index: 4;
  display: flex; align-items: center; gap: 20px; padding: 0 36px 0 40px;
  background: var(--mon-green); color: var(--mon-black);
  clip-path: polygon(16px 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
  font: 400 38px/1 "Anton", "Archivo Black", sans-serif; letter-spacing: .03em; text-transform: uppercase; white-space: nowrap;
  animation-name: ms-ad-cta;
}
@keyframes ms-ad-cta {
  0% { background: var(--mon-green); color: var(--mon-black); transform: none; }
  33% { background: var(--mon-black); color: var(--mon-green); }
  34% { background: var(--mon-green); color: var(--mon-black); }
  64% { background: var(--mon-black); color: var(--mon-green); }
  65% { background: var(--mon-green); color: var(--mon-black); }
  95% { transform: scale(1.08); }
  96% { transform: none; }
  97% { transform: scale(1.08); }
  98%, 100% { transform: none; }
}
.mscreen .ms-ad-chev { display: flex; gap: 4px; }
.mscreen .ms-ad-chev i {
  width: 15px; height: 26px; background: currentColor; opacity: .28;
  clip-path: polygon(0 0, 48% 0, 100% 50%, 48% 100%, 0 100%, 52% 50%);
  animation: ms-ad-chev 1.05s steps(1, end) infinite;
}
.mscreen .ms-ad-chev i:nth-child(2) { animation-delay: .35s; }
.mscreen .ms-ad-chev i:nth-child(3) { animation-delay: .7s; }
@keyframes ms-ad-chev { 0% { opacity: 1; } 33.3%, 100% { opacity: .28; } }

/* ---------------------------------------------------------------- the strip as a global section
   parts/ms-ad.html is one section (data-sec="sponsor", scope global) with five creatives as its [data-sv] children;
   psec.js hides all but the chosen one, and showing it again restarts its loop the way a banner GIF starts over.
   Every creative fills the 1080 x 140 unit, keeps a green call to action on the right and moves in hard cuts. */
.mscreen .ms-ad > [data-sv][hidden] { display: none !important; }
.mscreen .ms-ad-d { position: absolute; inset: 0; }
.mscreen .ms-ad .msa-art { position: absolute; inset: 0; --ad-loop: 6s; }
.mscreen .ms-ad .msa-art > *,
.mscreen .ms-ad .msa-art .msa-num i { animation-duration: var(--ad-loop); animation-iteration-count: infinite; animation-timing-function: steps(1, end); }

/* the kit pieces the four share: a can, a one-frame flash, the frames' type, the slanted CTA plate */
.mscreen .ms-ad .msa-can {
  position: absolute; left: 88px; top: 16px; width: 62px; height: 110px; z-index: 2;
  display: grid; place-items: center; border-radius: 10px / 8px;
  background: var(--can-body, linear-gradient(90deg, #030303 0%, #2E302C 20%, #111210 44%, #000 68%, #262824 90%, #070707 100%));
  box-shadow: 0 0 22px var(--can-glow, rgba(149, 214, 0, .32));
  transform: rotate(-8deg);
}
.mscreen .ms-ad .msa-can::before,
.mscreen .ms-ad .msa-can::after {
  content: ""; position: absolute; left: 4px; right: 4px; border-radius: 50%;
  background: linear-gradient(90deg, #6E716B, #E2E4DF 34%, #8C8F89 60%, #D6D8D2 84%, #74776F);
}
.mscreen .ms-ad .msa-can::before { top: -5px; height: 12px; }
.mscreen .ms-ad .msa-can::after { bottom: -3px; height: 8px; }
.mscreen .ms-ad .msa-can .mon-claw { width: 40px; height: 54px; fill: var(--can-mark, var(--mon-green)); }
.mscreen .ms-ad .msa-flash { position: absolute; inset: 0; z-index: 3; background: var(--mon-green); opacity: 0; }
.mscreen .ms-ad .msa-f {
  position: absolute; left: 196px; top: 0; bottom: 0; z-index: 1;
  display: flex; flex-direction: column; justify-content: center; align-items: flex-start; gap: 8px;
  transform-origin: 0 50%; opacity: 0;
  text-transform: uppercase; white-space: nowrap; font-synthesis: none;
}
.mscreen .ms-ad .msa-f b { font: 400 72px/.86 "Anton", "Archivo Black", sans-serif; letter-spacing: .012em; color: var(--mon-green); transform: skewX(-7deg); }
.mscreen .ms-ad .msa-f > span:not(.mon-word) { font: 700 34px/1 "Barlow Condensed", "Barlow", sans-serif; letter-spacing: .08em; color: var(--mon-ink); }
.mscreen .ms-ad .msa-cta {
  position: absolute; right: 40px; top: 27px; height: 86px; z-index: 4;
  display: flex; align-items: center; padding: 0 36px 0 40px;
  background: var(--mon-green); color: var(--mon-black);
  clip-path: polygon(16px 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
  font: 400 38px/1 "Anton", "Archivo Black", sans-serif; letter-spacing: .03em; text-transform: uppercase; white-space: nowrap;
}

/* Score deal, a 6 s loop: the score flicks up to the target in three cuts, a green flash, FREE CAN, the wordmark */
.mscreen .ms-ad .msa-deal .msa-deal-a { opacity: 1; animation-name: msa-deal-a; }
.mscreen .ms-ad .msa-deal .msa-deal-a b { color: var(--mon-ink); }
.mscreen .ms-ad .msa-num { display: inline-grid; color: var(--mon-green); }
.mscreen .ms-ad .msa-num i { grid-area: 1 / 1; font-style: normal; opacity: 0; }
.mscreen .ms-ad .msa-num i:nth-child(1) { animation-name: msa-n1; }
.mscreen .ms-ad .msa-num i:nth-child(2) { animation-name: msa-n2; }
.mscreen .ms-ad .msa-num i:nth-child(3) { animation-name: msa-n3; }
@keyframes msa-n1 { 0% { opacity: 1; } 3%, 100% { opacity: 0; } }
@keyframes msa-n2 { 0% { opacity: 0; } 3% { opacity: 1; } 6%, 100% { opacity: 0; } }
@keyframes msa-n3 { 0% { opacity: 0; } 6%, 100% { opacity: 1; } }
@keyframes msa-deal-a { 0% { opacity: 1; transform: scale(1.14); } 1% { transform: scale(.96); } 2% { transform: none; } 6% { transform: scale(1.08); } 7% { transform: none; } 38%, 100% { opacity: 0; } }
.mscreen .ms-ad .msa-deal .msa-flash { animation-name: msa-deal-flash; }
@keyframes msa-deal-flash { 0% { opacity: 0; } 38% { opacity: 1; } 40%, 100% { opacity: 0; } }
.mscreen .ms-ad .msa-deal .msa-deal-b { animation-name: msa-deal-b; }
.mscreen .ms-ad .msa-deal .msa-deal-b b { font-size: 84px; }
@keyframes msa-deal-b { 0% { opacity: 0; } 40% { opacity: 1; transform: scale(1.16); } 41% { transform: scale(.95); } 42% { transform: none; } 70%, 100% { opacity: 0; } }
.mscreen .ms-ad .msa-deal .msa-deal-c { font-size: 70px; animation-name: msa-deal-c; }
.mscreen .ms-ad .msa-deal .msa-deal-c .mon-word { transform: skewX(-7deg); }
@keyframes msa-deal-c { 0% { opacity: 0; } 70% { opacity: 1; transform: scale(1.16); } 71% { transform: scale(.95); } 72% { transform: none; } 100% { opacity: 1; } }
.mscreen .ms-ad .msa-deal .msa-can { animation-name: msa-can-shake; }
@keyframes msa-can-shake {
  0% { transform: translateY(-120px) rotate(-8deg); } 1% { transform: translateY(8px) rotate(-3deg); } 2% { transform: rotate(-8deg); }
  40% { transform: translateX(-5px) rotate(-16deg); } 41% { transform: rotate(-8deg); }
  70% { transform: translateX(-5px) rotate(-16deg); } 71%, 100% { transform: rotate(-8deg); }
}
.mscreen .ms-ad .msa-deal .msa-cta { animation-name: msa-knock; }
@keyframes msa-knock {
  0% { background: var(--mon-green); color: var(--mon-black); transform: none; }
  38% { background: var(--mon-black); color: var(--mon-green); } 40% { background: var(--mon-green); color: var(--mon-black); }
  94% { transform: scale(1.08); } 95% { transform: none; } 96% { transform: scale(1.08); } 97%, 100% { transform: none; }
}

/* Claw rip, a 5 s loop: a big claw tears down the strip in three cuts, the wordmark, a jolt, then the line */
.mscreen .ms-ad .msa-claw .msa-art { --ad-loop: 5s; background: radial-gradient(170px 120px at 142px 70px, rgba(149, 214, 0, .3), transparent 70%); }
.mscreen .ms-ad .msa-bigclaw {
  position: absolute; left: 80px; top: 4px; width: 118px; height: 132px; z-index: 2;
  fill: var(--mon-green); filter: drop-shadow(0 0 12px rgba(149, 214, 0, .6));
  animation-name: msa-rip;
}
@keyframes msa-rip {
  0% { clip-path: inset(0 0 100% 0); } 1% { clip-path: inset(0 0 64% 0); } 2% { clip-path: inset(0 0 28% 0); } 3% { clip-path: inset(0); }
  50% { clip-path: inset(0); transform: translateX(-8px) rotate(-4deg); } 51%, 100% { clip-path: inset(0); transform: none; }
}
.mscreen .ms-ad .msa-claw .msa-f { left: 228px; }
.mscreen .ms-ad .msa-claw .msa-claw-a { font-size: 66px; animation-name: msa-claw-a; }
.mscreen .ms-ad .msa-claw .msa-claw-a .mon-word { transform: skewX(-7deg); }
@keyframes msa-claw-a { 0% { opacity: 0; } 3% { opacity: 1; transform: scale(1.14); } 4% { transform: scale(.96); } 5% { transform: none; } 50%, 100% { opacity: 0; } }
.mscreen .ms-ad .msa-claw .msa-claw-b { gap: 4px; animation-name: msa-claw-b; }
.mscreen .ms-ad .msa-claw .msa-claw-b b { font-size: 58px; color: var(--mon-ink); }
.mscreen .ms-ad .msa-claw .msa-claw-b b.is-green { color: var(--mon-green); }
@keyframes msa-claw-b { 0% { opacity: 0; } 50% { opacity: 1; transform: translateX(-10px); } 51% { transform: translateX(4px); } 52%, 100% { opacity: 1; transform: none; } }
.mscreen .ms-ad .msa-claw .msa-cta { animation-name: msa-knock-end; }
@keyframes msa-knock-end { 0% { transform: none; } 93% { transform: scale(1.08); } 94% { transform: none; } 96% { transform: scale(1.08); } 97%, 100% { transform: none; } }

/* Flavours, a 6 s loop: three cans in three colourways, each cut in with its name; the swatch behind takes its colour */
.mscreen .ms-ad .msa-swatch {
  position: absolute; left: 52px; top: 0; bottom: 0; width: 140px; z-index: 0;
  clip-path: polygon(30px 0, 100% 0, calc(100% - 30px) 100%, 0 100%);
  background: rgba(149, 214, 0, .24);
  animation-name: msa-swatch;
}
@keyframes msa-swatch { 0% { background: rgba(149, 214, 0, .24); } 33.33% { background: rgba(120, 206, 245, .24); } 66.66%, 100% { background: rgba(255, 210, 31, .24); } }
.mscreen .ms-ad .msa-can-2 { --can-body: linear-gradient(90deg, #B9BDB7 0%, #F4F5F2 22%, #D9DCD6 46%, #A9ADA6 70%, #EEF0EC 90%, #BFC3BC 100%); --can-mark: #1E8FD0; --can-glow: rgba(120, 206, 245, .35); }
.mscreen .ms-ad .msa-can-3 { --can-mark: #FFD21F; --can-glow: rgba(255, 210, 31, .32); }
.mscreen .ms-ad .msa-flav .msa-can { opacity: 0; }
.mscreen .ms-ad .msa-flav .msa-can-1 { animation-name: msa-can-1; }
.mscreen .ms-ad .msa-flav .msa-can-2 { animation-name: msa-can-2; }
.mscreen .ms-ad .msa-flav .msa-can-3 { animation-name: msa-can-3; }
@keyframes msa-can-1 { 0% { opacity: 1; transform: translateY(-90px) rotate(-8deg); } 1% { transform: translateY(8px) rotate(-3deg); } 2% { transform: rotate(-8deg); } 33.33%, 100% { opacity: 0; } }
@keyframes msa-can-2 { 0% { opacity: 0; } 33.33% { opacity: 1; transform: translateY(-90px) rotate(-8deg); } 34.33% { transform: translateY(8px) rotate(-3deg); } 35.33% { transform: rotate(-8deg); } 66.66%, 100% { opacity: 0; } }
@keyframes msa-can-3 { 0% { opacity: 0; } 66.66% { opacity: 1; transform: translateY(-90px) rotate(-8deg); } 67.66% { transform: translateY(8px) rotate(-3deg); } 68.66%, 100% { opacity: 1; transform: rotate(-8deg); } }
.mscreen .ms-ad .msa-flav-1 { animation-name: msa-flav-1; }
.mscreen .ms-ad .msa-flav-2 { animation-name: msa-flav-2; }
.mscreen .ms-ad .msa-flav-3 { animation-name: msa-flav-3; }
.mscreen .ms-ad .msa-flav-2 b { color: #8AD8F8; }
.mscreen .ms-ad .msa-flav-3 b { color: #FFD21F; }
@keyframes msa-flav-1 { 0% { opacity: 0; } 1% { opacity: 1; transform: scale(1.14); } 2% { transform: none; } 33.33%, 100% { opacity: 0; } }
@keyframes msa-flav-2 { 0% { opacity: 0; } 34.33% { opacity: 1; transform: scale(1.14); } 35.33% { transform: none; } 66.66%, 100% { opacity: 0; } }
@keyframes msa-flav-3 { 0% { opacity: 0; } 67.66% { opacity: 1; transform: scale(1.14); } 68.66%, 100% { opacity: 1; transform: none; } }
.mscreen .ms-ad .msa-flav .msa-cta { animation-name: msa-flav-cta; }
@keyframes msa-flav-cta { 0% { background: var(--mon-green); } 33.33% { background: #8AD8F8; } 66.66%, 100% { background: #FFD21F; } }

/* Split, a 6 s loop: a green panel with the wordmark beside a black field, then one hard cut swaps the two */
.mscreen .ms-ad .msa-split .msa-art { animation: msa-split-ground var(--ad-loop) steps(1, end) infinite; }
@keyframes msa-split-ground { 0% { background: transparent; } 50%, 100% { background: var(--mon-green); } }
.mscreen .ms-ad .msa-panel {
  position: absolute; left: 0; top: 0; bottom: 0; width: 470px; z-index: 1;
  display: grid; align-items: center; padding-left: 72px; font-size: 64px;
  clip-path: polygon(0 0, 100% 0, calc(100% - 56px) 100%, 0 100%);
  background: var(--mon-green);
  animation-name: msa-panel;
}
.mscreen .ms-ad .msa-panel .mon-word { color: var(--mon-black); transform: skewX(-7deg); animation: msa-panel-word var(--ad-loop) steps(1, end) infinite; }
.mscreen .ms-ad .msa-panel .mon-word > span { color: var(--mon-black); animation: msa-panel-energy var(--ad-loop) steps(1, end) infinite; }
@keyframes msa-panel { 0% { background: var(--mon-green); } 50%, 100% { background: var(--mon-black); } }
@keyframes msa-panel-word { 0% { color: var(--mon-black); } 50%, 100% { color: #FFFFFF; } }
@keyframes msa-panel-energy { 0% { color: var(--mon-black); } 50%, 100% { color: var(--mon-green); } }
.mscreen .ms-ad .msa-split .msa-f { left: 468px; }
.mscreen .ms-ad .msa-split-a { animation-name: msa-split-a; }
.mscreen .ms-ad .msa-split-b { animation-name: msa-split-b; }
.mscreen .ms-ad .msa-split-b b { color: var(--mon-black); }
.mscreen .ms-ad .msa-split-b > span:not(.mon-word) { color: var(--mon-black); }
@keyframes msa-split-a { 0% { opacity: 1; transform: scale(1.12); } 1% { transform: none; } 50%, 100% { opacity: 0; } }
@keyframes msa-split-b { 0% { opacity: 0; } 50% { opacity: 1; transform: scale(1.12); } 51%, 100% { opacity: 1; transform: none; } }
.mscreen .ms-ad .msa-split .msa-cta { animation-name: msa-split-cta; }
@keyframes msa-split-cta { 0% { background: var(--mon-green); color: var(--mon-black); } 50%, 100% { background: var(--mon-black); color: var(--mon-green); } }

/* the disclosure: a tab in the bottom corner, above everything, at the glass's 32 px floor so the queue can read it
   too (it was a 17 px chip with a hairline border); the cans, claw and swatch stand 16 px further in to clear it */
.mscreen .ms-ad-tag {
  position: absolute; left: 0; bottom: 0; z-index: 5;
  height: 44px; padding: 0 10px 0 calc(10px + .1em); display: grid; place-items: center;
  border-radius: 0 12px 0 0; background: rgba(0, 0, 0, .78); color: #FFFFFF;
  font: 600 32px/1 "Barlow", system-ui, sans-serif; letter-spacing: .1em;
}

/* reduced motion: one calm still that carries the whole message: can, wordmark, the line, the CTA */
@media (prefers-reduced-motion: reduce) {
  .mscreen .ms-ad-art > *,
  .mscreen .ms-ad-chev i { animation: none !important; }
  .mscreen .ms-ad-f1 { opacity: 1; font-size: 56px; gap: 10px; }
  .mscreen .ms-ad-still { display: block; font: 700 32px/1 "Barlow Condensed", "Barlow", sans-serif; letter-spacing: .08em; color: var(--mon-ink); }
  .mscreen .ms-ad-bolt { opacity: 1; transform: translate(292px, 34px) scale(.5); }
  .mscreen .ms-ad-chev i { opacity: 1; }
  /* the four others: each held on the frame that says it all */
  .mscreen .ms-ad .msa-art, .mscreen .ms-ad .msa-art * { animation: none !important; }
  .mscreen .ms-ad :is(.msa-num i:nth-child(3), .msa-deal-a, .msa-claw-a, .msa-flav-1, .msa-split-a) { opacity: 1; }
  .mscreen .ms-ad .msa-flav .msa-can-1 { opacity: 1; }
}

/* Punch again on the Results screens after the Result: Big score, New record and Your run (parts/ms-again.html; Your
   run joined in round nine, machine fixes A: its frame, stats.js playing it in after the crown). Round nine: "all
   the result tab pages have a Punch again button". A section of its own at the foot of each frame, 200 px of room, with
   the Result's five designs (sections/cta.html, sections/cta.css) set for the machine's spacing scale: Full button is
   the Result's own .cta slab, the rest restate cta.css under .ag-* with the same tokens, so every look applies.
   Motion only under .is-play (the screen's script adds it on the section's beat); without it every design stands. */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-sec {
  --room: 200px;
  position: relative; z-index: 1; flex: none; margin: 0 var(--ms-gut); height: var(--room);
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-sec > [data-sv] { position: relative; height: 100%; min-width: 0; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-sec > [data-sv][hidden] { display: none !important; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-sec p { margin: 0; }
/* the red word on every slab: trimmed to cap height and baseline so it sits optically centred */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-play { display: grid; place-items: center; border-radius: var(--r); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-word { display: block; letter-spacing: .04em; margin-right: -.04em; text-box: trim-both cap alphabetic; }

/* Full button: the Result's slab, as tall as the room */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-full { display: grid; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-full .cta { min-height: 0; height: 100%; }

/* Button pair: two equal halves. Punch again is the red one; the other says where the hit went (a status: the glass
   takes no touch) */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pair {
  container-type: inline-size;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid);
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pair .ag-word,
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-code .ag-word { font-size: min(calc(64px / var(--cap)), calc((50cqi - var(--gap-grid) / 2 - 2 * var(--card-pad)) / 5.4)); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-save { min-width: 0; display: flex; align-items: center; gap: 24px; padding-inline: var(--card-pad); }
/* Lucide smartphone at 56 px: 1.5 on the 24 grid draws the 3 px line every glass icon uses */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-ico { flex: none; display: inline-flex; font-size: 56px; line-height: 0; color: var(--ink-1); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-save-t { min-width: 0; display: grid; gap: 10px; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-save-cap { font-size: 24px; color: var(--ink-3); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-say { min-width: 0; font-size: 34px; line-height: 1.15; color: var(--ink-1); text-wrap: balance; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-save .ag-ico { color: var(--up, #2BC46B); }

/* Countdown: the red slab and a shot clock side by side, the clock's caption over the end of the slab */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-clock {
  --ring: 200px;
  container-type: inline-size;
  display: grid; grid-template-columns: minmax(0, 1fr) var(--ring); grid-template-rows: minmax(0, 1fr) 144px; column-gap: var(--gap-grid);
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-next { grid-area: 1 / 1; align-self: start; justify-self: end; font-size: 32px; white-space: nowrap; text-box: trim-both cap alphabetic; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-clock .ag-play { grid-area: 2 / 1; place-items: center start; padding-inline: var(--card-pad); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-clock .ag-word { font-size: min(calc(64px / var(--cap)), calc((100cqi - var(--ring) - 120px) / 5.2)); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-dial { grid-area: 1 / 2 / 3 / 3; width: var(--ring); height: var(--ring); display: grid; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-dial > * { grid-area: 1 / 1; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-ring { display: block; width: 100%; height: 100%; transform: rotate(-90deg); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) :is(.ag-ring-track, .ag-ring-left) { fill: none; stroke-width: 22; stroke-dashoffset: -.55; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-ring-track { stroke: var(--track); stroke-dasharray: 3.9 1.1; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-ring-left { stroke: var(--ink-1); stroke-dasharray: 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 3.9 1.1 0 40; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-read { place-self: center; display: grid; justify-items: center; row-gap: 12px; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-num { font-size: calc(60px / var(--cap)); font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-unit { font-size: 32px; color: var(--ink-3); text-box: trim-both cap alphabetic; }

/* Code handoff: Punch again on the left, the run's code on the right with what it is for; the shared PunchQR tile at
   200 px, for a phone held at arm's length */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-code {
  container-type: inline-size;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--gap-grid);
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-hand { min-width: 0; display: grid; grid-template-columns: 200px minmax(0, 1fr); align-items: center; column-gap: 28px; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-qr { --pqr-size: 200px; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-copy { min-width: 0; display: grid; gap: 20px; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-keep { font-size: 34px; line-height: 1.2; color: var(--ink-1); text-wrap: balance; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-codeword { font-size: calc(32px / var(--cap)); letter-spacing: .14em; color: var(--ink-2); text-box: trim-both cap alphabetic; }

/* Big pad: the machine's strike pad, the rings it sends out across the glass fading as they travel */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-band {
  --d: 200px; --cx: calc(var(--ms-gut) + var(--d) / 2);
  position: relative; height: 100%; margin-inline: calc(-1 * var(--ms-gut)); overflow: hidden;
  display: flex; align-items: center; gap: 56px; padding-left: var(--ms-gut);
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-waves {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(circle at var(--cx) 50%,
    transparent 115px, var(--line) 116px 119px, transparent 120px 137px, var(--line) 138px 141px, transparent 142px 165px,
    var(--line) 166px 169px, transparent 170px 201px, var(--line) 202px 205px, transparent 206px 245px,
    var(--line) 246px 249px, transparent 250px 297px, var(--line) 298px 301px, transparent 302px 357px,
    var(--line) 358px 361px, transparent 362px 427px, var(--line) 428px 431px, transparent 432px 507px,
    var(--line) 508px 511px, transparent 512px 597px, var(--line) 598px 601px, transparent 602px 697px,
    var(--line) 698px 701px, transparent 702px 807px, var(--line) 808px 811px, transparent 812px);
  -webkit-mask-image: radial-gradient(circle at var(--cx) 50%, black 180px, transparent 860px), linear-gradient(to bottom, transparent, black 24%, black 76%, transparent);
  mask-image: radial-gradient(circle at var(--cx) 50%, black 180px, transparent 860px), linear-gradient(to bottom, transparent, black 24%, black 76%, transparent);
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
}
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-padbox { position: relative; flex: none; width: var(--d); height: var(--d); display: grid; place-items: center; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-rings { position: absolute; inset: 0; width: 100%; height: 100%; fill: none; stroke: var(--line); stroke-width: 2; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-core { position: relative; width: 156px; height: 156px; border-radius: 50%; display: grid; place-items: center; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-core > svg { grid-area: 1 / 1; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-stitch { width: 100%; height: 100%; fill: none; stroke: var(--cta-ink); stroke-opacity: .4; stroke-width: 2; stroke-dasharray: 5 6; }
/* Lucide rotate-ccw at 76 px: .95 on the 24 grid draws the 3 px line every glass icon uses */
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-again { width: 76px; height: 76px; color: var(--cta-ink); stroke-width: .95; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-hit { position: relative; font-size: 48px; color: var(--ink-1); white-space: nowrap; text-box: trim-both cap alphabetic; }

/* ---------------------------------------------------------------- motion: in last, after the number and the reel */
@keyframes ag-rise { from { opacity: 0; transform: translateY(48px); } }
@keyframes ag-in { from { opacity: 0; } }
@keyframes ag-pop { 0% { opacity: 0; transform: scale(.6); } 70% { opacity: 1; transform: scale(1.06); } 100% { transform: none; } }
@keyframes ag-wave { from { opacity: 0; transform: scale(.5); } }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag.is-play:not(.is-settled) { animation: ag-rise .7s cubic-bezier(.16, 1, .3, 1) both; animation-delay: var(--sd, 0ms); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pad.is-play:not(.is-settled) { animation: ag-in .4s ease-out both; animation-delay: var(--sd, 0ms); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pad.is-play:not(.is-settled) .ag-core { animation: ag-pop .6s cubic-bezier(.2, .9, .25, 1.2) both; animation-delay: calc(var(--sd, 0ms) + 120ms); }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pad.is-play:not(.is-settled) .ag-waves { animation: ag-wave 1.2s cubic-bezier(.16, 1, .3, 1) both; animation-delay: calc(var(--sd, 0ms) + 300ms); transform-origin: var(--cx) 50%; }
:is(.mscreen-score, .mscreen-record, .mscreen-stats) .ag-pad.is-play:not(.is-settled) .ag-hit { animation: ag-in .5s ease-out both; animation-delay: calc(var(--sd, 0ms) + 500ms); }

/* The global background, one look for the phone and the machine alike, chosen in Customise ("Background", app.js
   BACKDROPS) as html[data-mbackdrop]. Both surfaces carry the same host:
     <div class="ms-lights" aria-hidden="true"><i class="l1"></i> ... <i class="l6"></i></div>
   as the first child of every machine screen, and inside the phone's .m-bg (parts/phone.html). Each look restyles those
   six shapes. The host is a size container, so every length is written once in the glass's own pixels and scales:
     --u  one glass pixel across (1080 wide), --v  one glass pixel down (3840 tall),
     --k  a size pixel: 1px on the glass, a little over half of that on the phone (a phone is held closer).
   (cq units resolve against the host only in its children, so the host itself never uses them.)
   Colour comes from the surface: --bd-a (the key light) and --bd-b (the brand light) from the machine's --ms-light
   tokens or the phone's own, and --bd-red, the phone's red glow. So Arena, Reference, dark and light each tint every
   look. Everything sits behind the content, nothing is brighter than a light pool, nothing moves faster than a slow
   walk, and reduced motion holds each look on a composed still. */

.ms-lights {
  position: absolute; inset: 0; overflow: hidden; pointer-events: none;
  container-type: size;
  --u: calc(100cqw / 1080); --v: calc(100cqh / 3840);
}
.mscreen .ms-lights {
  z-index: -1;
  --k: calc(100cqw / 1080);
  --bd-a: var(--ms-light); --bd-b: var(--ms-light-2);
  --bd-red: rgba(235, 17, 16, .26); --bd-blur: 150px;
  --bd-base: var(--ms-ad-h);
}
:root[data-appearance="light"] .mscreen .ms-lights { --bd-red: rgba(235, 17, 16, .1); }
.m-bg .ms-lights {
  --k: calc(100cqw / 760);
  --bd-a: rgba(255, 226, 196, .075); --bd-b: rgb(from var(--m-blob) r g b / calc(alpha * .55));
  --bd-red: var(--m-blob); --bd-blur: 40px;
  --bd-base: 0px;
}
:root[data-appearance="light"] .m-bg .ms-lights { --bd-a: rgba(255, 170, 120, .16); }

.ms-lights i {
  --c: var(--bd-a); --cx: 540; --cy: 1920; --w: 950; --h: 950;
  position: absolute; display: block;
  left: calc(var(--cx) * var(--u) - var(--w) * var(--k) / 2);
  top: calc(var(--cy) * var(--v) - var(--h) * var(--k) / 2);
  width: calc(var(--w) * var(--k)); height: calc(var(--h) * var(--k));
}
.ms-lights :is(.l2, .l3, .l6) { --c: var(--bd-b); }

/* ---------------------------------------------------------------- red glow (the default): the phone's own ground
   three blurred red bodies where the phone app draws them (top right, left, the foot), so the phone looks exactly as it
   always has; the tall glass gets a fourth down its right side so the light runs the whole way down. Still: it moves
   only when the phone turns to another page, the way the room turns with you. */
:root[data-mbackdrop="glow"] .ms-lights i {
  background: var(--bd-red); border-radius: 999px; filter: blur(var(--bd-blur));
  transition: transform 1.2s cubic-bezier(.2, .7, .2, 1), opacity .8s ease;
}
:root[data-mbackdrop="glow"] .ms-lights .l1 { left: 64%; top: -12%; width: 106%; height: 47%; }
:root[data-mbackdrop="glow"] .ms-lights .l2 { left: -57%; top: 15%; width: 84%; height: 39%; border-radius: calc(24 * var(--k)); filter: blur(calc(var(--bd-blur) / 2)); opacity: .9; }
:root[data-mbackdrop="glow"] .ms-lights .l3 { left: 6%; top: 82%; width: 104%; height: 48%; filter: blur(calc(var(--bd-blur) * .75)); opacity: .7; }
:root[data-mbackdrop="glow"] .ms-lights .l4 { left: 62%; top: 46%; width: 90%; height: 24%; opacity: .5; }
:root[data-mbackdrop="glow"] .ms-lights :is(.l5, .l6) { display: none; }
:root[data-mbackdrop="glow"] .m-bg .ms-lights .l4 { display: none; }
/* the glass's left body is fifteen hundred pixels tall: at the phone's half blur its edges would read as a slab */
:root[data-mbackdrop="glow"] .mscreen .ms-lights .l2 { border-radius: 999px; filter: blur(var(--bd-blur)); opacity: .8; }

/* ---------------------------------------------------------------- soft lights: six pools, alternating sides
   warm key light up top beside the logo, the brand light in the middle and low; each drifts and breathes, very slowly */
:root[data-mbackdrop="lights"] .ms-lights i {
  --c2: rgb(from var(--c) r g b / min(1, calc(alpha * 1.35)));
  background: radial-gradient(closest-side, var(--c2), rgb(from var(--c2) r g b / calc(alpha * .5)) 55%, transparent);
  border-radius: 50%;
  animation: bd-drift var(--t, 19s) ease-in-out infinite alternate, bd-breathe calc(var(--t, 19s) * .7) ease-in-out infinite alternate;
  transition: transform 1.2s cubic-bezier(.2, .7, .2, 1);
}
:root[data-mbackdrop="lights"] .ms-lights .l1 { --cx: -128; --cy: 403; --dx: 70; --dy: 40; }
:root[data-mbackdrop="lights"] .ms-lights .l2 { --cx: 1162; --cy: 429; --w: 960; --h: 940; --dx: -60; --dy: 60; --t: 23s; animation-delay: -7s, -3s; }
:root[data-mbackdrop="lights"] .ms-lights .l3 { --cx: 1033; --cy: 1745; --dx: -80; --dy: -50; --t: 21s; animation-delay: -3s, -9s; }
:root[data-mbackdrop="lights"] .ms-lights .l4 { --cx: -86; --cy: 2002; --dx: 60; --dy: 70; animation-delay: -11s, -5s; }
:root[data-mbackdrop="lights"] .ms-lights .l5 { --cx: -111; --cy: 3113; --dx: 80; --dy: -40; --t: 25s; animation-delay: -5s, -12s; }
:root[data-mbackdrop="lights"] .ms-lights .l6 { --cx: 1105; --cy: 3269; --dx: -70; --dy: -60; --t: 22s; animation-delay: -14s, -2s; }
@keyframes bd-drift { from { translate: 0 0; scale: 1; } to { translate: calc(var(--dx) * var(--k)) calc(var(--dy) * var(--k)); scale: 1.07; } }
@keyframes bd-breathe { from { opacity: .72; } to { opacity: 1; } }

/* ---------------------------------------------------------------- stadium beams: lamps along the top edge
   six lamps, each a hot head and a soft cone that fades before the base, swinging a few degrees and back; they lean
   only a little inward, so they cross low and faint rather than knotting behind the score */
:root[data-mbackdrop="beams"] .ms-lights i {
  --cb: rgb(from var(--c) r g b / min(1, calc(alpha * 1.25)));
  --w: 2400; --cy: 1700; --h: 3700;
  top: -4%; height: 97%;
  background:
    radial-gradient(calc(46 * var(--k)) calc(30 * var(--k)) at 50% calc(150 * var(--k)), rgb(from var(--cb) r g b / min(1, calc(alpha * 2.4))), transparent),
    radial-gradient(calc(190 * var(--k)) calc(150 * var(--k)) at 50% calc(150 * var(--k)), var(--cb), transparent),
    conic-gradient(from 171deg at 50% calc(150 * var(--k)), transparent 0deg, var(--cb) 9deg, transparent 18deg);
  -webkit-mask-image: linear-gradient(to bottom, #000 0 26%, transparent 90%);
  mask-image: linear-gradient(to bottom, #000 0 26%, transparent 90%);
  transform-origin: 50% calc(150 * var(--k)); transform: rotate(var(--a));
  animation: bd-sweep var(--t, 17s) ease-in-out infinite alternate;
}
:root[data-mbackdrop="beams"] .ms-lights .l1 { --cx: 90; --a: -9deg; --t: 17s; animation-delay: -4s; }
:root[data-mbackdrop="beams"] .ms-lights .l2 { --cx: 990; --a: 9deg; --t: 19s; animation-delay: -12s; }
:root[data-mbackdrop="beams"] .ms-lights .l3 { --cx: 380; --a: 5deg; --t: 23s; animation-delay: -9s; }
:root[data-mbackdrop="beams"] .ms-lights .l4 { --cx: 700; --a: -5deg; --t: 21s; animation-delay: -2s; }
:root[data-mbackdrop="beams"] .ms-lights .l5 { --cx: -160; --a: -24deg; --t: 26s; animation-delay: -15s; }
:root[data-mbackdrop="beams"] .ms-lights .l6 { --cx: 1240; --a: 24deg; --t: 24s; animation-delay: -6s; }
@keyframes bd-sweep {
  from { transform: rotate(calc(var(--a) - 7deg)); }
  to { transform: rotate(calc(var(--a) + 7deg)); }
}

/* ---------------------------------------------------------------- spotlight: one lamp over the player
   a single cone from above the logo to a lit pool on the floor, breathing slowly; dust hangs in the beam and drifts */
:root[data-mbackdrop="spot"] .ms-lights i { --cs: rgb(from var(--bd-a) r g b / min(1, calc(alpha * 1.5))); }
:root[data-mbackdrop="spot"] .ms-lights .l1 {
  left: calc(540 * var(--u) - 1800 * var(--k)); width: calc(3600 * var(--k)); top: -3%; height: 103%;
  background: conic-gradient(from 164deg at 50% 0, transparent 0deg, var(--cs) 12deg, var(--cs) 20deg, transparent 32deg);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0, 0, 0, .9), #000 30%, rgba(0, 0, 0, .55) 86%, transparent);
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, .9), #000 30%, rgba(0, 0, 0, .55) 86%, transparent);
  animation: bd-breathe 7s ease-in-out infinite alternate;
}
:root[data-mbackdrop="spot"] .ms-lights .l2 {
  --w: 1500; --h: 420; --cx: 540;
  top: calc(100% - var(--bd-base) - 260 * var(--k));
  background: radial-gradient(closest-side, rgb(from var(--bd-b) r g b / min(1, calc(alpha * 1.6))), transparent);
  animation: bd-breathe 7s ease-in-out infinite alternate;
}
:root[data-mbackdrop="spot"] .ms-lights .l3 {
  --w: 700; --h: 360; --cx: 540; top: calc(-180 * var(--k));
  background: radial-gradient(closest-side, var(--cs), transparent);
}
:root[data-mbackdrop="spot"] .ms-lights :is(.l4, .l5, .l6) {
  --dust: rgb(from var(--bd-a) r g b / min(1, calc(alpha * 5)));
  left: 0; top: 0; width: 100%; height: calc(100% + var(--tile) * var(--k));
  background-image:
    radial-gradient(circle at 42% 12%, var(--dust) 0 calc(var(--s) * var(--k)), transparent calc(var(--s) * 2.4 * var(--k))),
    radial-gradient(circle at 57% 38%, var(--dust) 0 calc(var(--s) * var(--k)), transparent calc(var(--s) * 2.4 * var(--k))),
    radial-gradient(circle at 48% 64%, var(--dust) 0 calc(var(--s) * var(--k)), transparent calc(var(--s) * 2.4 * var(--k))),
    radial-gradient(circle at 63% 86%, var(--dust) 0 calc(var(--s) * var(--k)), transparent calc(var(--s) * 2.4 * var(--k))),
    radial-gradient(circle at 36% 78%, var(--dust) 0 calc(var(--s) * var(--k)), transparent calc(var(--s) * 2.4 * var(--k)));
  background-size: 100% calc(var(--tile) * var(--k));
  -webkit-mask-image: radial-gradient(60% 70% at 50% 45%, #000 30%, transparent 100%);
  mask-image: radial-gradient(60% 70% at 50% 45%, #000 30%, transparent 100%);
  animation: bd-sink var(--t) linear infinite, bd-sway var(--sw, 11s) ease-in-out infinite alternate;
}
:root[data-mbackdrop="spot"] .ms-lights .l4 { --tile: 1300; --s: 3; --t: 90s; }
:root[data-mbackdrop="spot"] .ms-lights .l5 { --tile: 1700; --s: 4; --t: 70s; --sw: 14s; background-position: 90px 400px; animation-delay: -30s, -4s; }
:root[data-mbackdrop="spot"] .ms-lights .l6 { --tile: 2100; --s: 2; --t: 110s; --sw: 9s; background-position: -120px 900px; animation-delay: -50s, -7s; }
@keyframes bd-sink { from { transform: translateY(calc(-1 * var(--tile) * var(--k))); } to { transform: translateY(0); } }
@keyframes bd-sway { from { translate: calc(-26 * var(--k)) 0; } to { translate: calc(26 * var(--k)) 0; } }

/* ---------------------------------------------------------------- heartbeat: a pulse rising from the base
   the six are rings of light that start at the foot in pairs, lub and dub, widen as they climb and fade before the
   logo; the first ring doubles as the glow on the floor, beating twice every two seconds */
:root[data-mbackdrop="pulse"] .ms-lights i {
  --cp: rgb(from var(--c) r g b / min(1, calc(alpha * 1.3)));
  --cx: 540; --w: 2000; --h: 800;
  top: calc(100% - var(--bd-base) - 460 * var(--k));
  border-radius: 50%;
  background: radial-gradient(closest-side, transparent 56%, var(--cp) 78%, transparent 97%);
  opacity: 0;
  animation: bd-rise 6s cubic-bezier(.25, .55, .35, 1) infinite;
}
:root[data-mbackdrop="pulse"] .ms-lights .l1 { animation-delay: -6s; }
:root[data-mbackdrop="pulse"] .ms-lights .l2 { animation-delay: -5.7s; }
:root[data-mbackdrop="pulse"] .ms-lights .l3 { animation-delay: -4s; }
:root[data-mbackdrop="pulse"] .ms-lights .l4 { animation-delay: -3.7s; }
:root[data-mbackdrop="pulse"] .ms-lights .l5 { animation-delay: -2s; }
:root[data-mbackdrop="pulse"] .ms-lights .l6 { animation-delay: -1.7s; }
/* the floor glow: a separate still pool under the rings, drawn on the host so it never shares a ring's timing */
:root[data-mbackdrop="pulse"] .ms-lights::before {
  content: ""; position: absolute; left: -15%; right: -15%; bottom: calc(var(--bd-base) - 9%); height: 18%;
  background: radial-gradient(closest-side, rgb(from var(--bd-b) r g b / min(1, calc(alpha * 2))), transparent);
  animation: bd-beat 2s linear infinite;
}
@keyframes bd-rise {
  0% { opacity: 0; transform: translateY(0) scale(.3); }
  6% { opacity: 1; }
  55% { opacity: .75; }
  100% { opacity: 0; transform: translateY(calc(-2900 * var(--v))) scale(1.6); }
}
@keyframes bd-beat {
  0% { opacity: 1; }
  10% { opacity: .45; }
  15% { opacity: .85; }
  45%, 100% { opacity: .3; }
}

/* ---------------------------------------------------------------- embers: sparks drifting up from below
   six layers of sparks, each a tall repeating tile carried upward and swaying; the nearer layers are larger and
   quicker, and they show most near the base, where a low fire glow sits */
:root[data-mbackdrop="embers"] .ms-lights {
  -webkit-mask-image: linear-gradient(to top, #000 8%, rgba(0, 0, 0, .45) 92%);
  mask-image: linear-gradient(to top, #000 8%, rgba(0, 0, 0, .45) 92%);
}
:root[data-mbackdrop="embers"] .ms-lights::before {
  content: ""; position: absolute; left: -10%; right: -10%; bottom: calc(var(--bd-base) - 11%); height: 22%;
  background: radial-gradient(closest-side, rgb(from var(--bd-b) r g b / min(1, calc(alpha * 1.8))), transparent);
}
:root[data-mbackdrop="embers"] .ms-lights i {
  --ce: rgb(from var(--c) r g b / min(1, calc(alpha * 6)));
  --ch: rgb(from var(--c) r g b / min(1, calc(alpha * 2)));
  --r: max(1.4px, calc(var(--s) * var(--k)));
  left: 0; top: 0; width: 100%; height: calc(100% + var(--tile) * var(--k));
  background-image:
    radial-gradient(circle at 8% 14%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 31% 62%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 52% 27%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 71% 83%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 89% 41%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 19% 91%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 44% 4%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2)),
    radial-gradient(circle at 96% 72%, var(--ce) 0 var(--r), var(--ch) calc(var(--r) + .6px), transparent calc(var(--r) * 3.2));
  background-size: 100% calc(var(--tile) * var(--k));
  background-position: calc(var(--bx, 0) * var(--u)) 0;
  animation: bd-float var(--t) linear infinite, bd-sway var(--sw, 9s) ease-in-out infinite alternate;
}
:root[data-mbackdrop="embers"] .ms-lights .l1 { --tile: 1400; --t: 70s; --s: 3; }
:root[data-mbackdrop="embers"] .ms-lights .l2 { --tile: 1180; --t: 58s; --s: 3; --bx: 410; --sw: 11s; animation-delay: -21s, -3s; }
:root[data-mbackdrop="embers"] .ms-lights .l3 { --tile: 1560; --t: 48s; --s: 4; --bx: 170; --sw: 13s; animation-delay: -9s, -6s; }
:root[data-mbackdrop="embers"] .ms-lights .l4 { --tile: 1320; --t: 42s; --s: 4; --bx: 690; --sw: 8s; animation-delay: -30s, -1s; }
:root[data-mbackdrop="embers"] .ms-lights .l5 { --tile: 1720; --t: 34s; --s: 6; --bx: 300; --sw: 10s; animation-delay: -12s, -4s; }
:root[data-mbackdrop="embers"] .ms-lights .l6 { --tile: 1900; --t: 30s; --s: 7; --bx: 820; --sw: 12s; animation-delay: -5s, -8s; }
@keyframes bd-float { from { transform: translateY(0); } to { transform: translateY(calc(-1 * var(--tile) * var(--k))); } }

/* ---------------------------------------------------------------- smoke: haze rolling through stage light
   four bands of haze, each a strip of long flat wisps twice the glass wide, rolling sideways at its own pace (two each
   way) so they thicken and thin where they cross; every wisp stays inside its own tile, so a seam never shows. The
   stage light below warms them from the floor and a soft wash sits above the logo */
:root[data-mbackdrop="smoke"] .ms-lights i:not(.l5, .l6) {
  --cm: rgb(from var(--c) r g b / min(1, calc(alpha * 1.1)));
  left: 0; width: 200%; height: calc(var(--h) * var(--k)); top: calc(var(--cy) * var(--v) - var(--h) * var(--k) / 2);
  background:
    radial-gradient(30% 20% at 24% 46%, var(--cm), transparent 70%),
    radial-gradient(24% 12% at 50% 66%, var(--cm), transparent 70%),
    radial-gradient(34% 16% at 70% 36%, var(--cm), transparent 70%),
    radial-gradient(20% 10% at 36% 24%, var(--cm), transparent 70%);
  background-size: 50% 100%; background-repeat: repeat-x;
  filter: blur(calc(22 * var(--k)));
  animation: bd-roll var(--t) linear infinite var(--dir, normal), bd-lift var(--lt, 17s) ease-in-out infinite alternate;
}
:root[data-mbackdrop="smoke"] .ms-lights .l1 { --cy: 560; --h: 1300; --t: 150s; }
:root[data-mbackdrop="smoke"] .ms-lights .l2 { --cy: 1450; --h: 1500; --t: 190s; --dir: reverse; --lt: 21s; animation-delay: -60s, -5s; }
:root[data-mbackdrop="smoke"] .ms-lights .l3 { --cy: 2400; --h: 1400; --t: 130s; --lt: 19s; animation-delay: -35s, -9s; }
:root[data-mbackdrop="smoke"] .ms-lights .l4 { --cy: 3200; --h: 1200; --t: 170s; --dir: reverse; animation-delay: -90s, -3s; }
:root[data-mbackdrop="smoke"] .ms-lights .l5 {
  --cx: 540; --w: 1900; --h: 900;
  top: calc(100% - var(--bd-base) - 520 * var(--k));
  background: radial-gradient(closest-side, rgb(from var(--bd-b) r g b / min(1, calc(alpha * 1.5))), transparent);
}
:root[data-mbackdrop="smoke"] .ms-lights .l6 {
  --cx: 540; --cy: 120; --w: 1700; --h: 800;
  background: radial-gradient(closest-side, rgb(from var(--bd-a) r g b / min(1, calc(alpha * 1.2))), transparent);
}
@keyframes bd-roll { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes bd-lift { from { translate: 0 calc(40 * var(--k)); opacity: .75; } to { translate: 0 calc(-40 * var(--k)); opacity: 1; } }

/* ---------------------------------------------------------------- arena grid: a lit floor in perspective
   a floor grid runs from a horizon six tenths down to the base, gliding toward the player; a band of light sits on the
   horizon and two pools stay up top, so the logo keeps its light */
:root[data-mbackdrop="grid"] .ms-lights .l1 {
  --cg: rgb(from var(--bd-b) r g b / min(1, calc(alpha * 2.6)));
  --line: max(1px, calc(4 * var(--k))); --cell: calc(120 * var(--k));
  left: calc(540 * var(--u) - 2540 * var(--k)); width: calc(5080 * var(--k));
  top: 58%; height: calc(900 * var(--k)); overflow: hidden;
  transform-origin: 50% 0; transform: perspective(calc(1000 * var(--k))) rotateX(70deg);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 36%);
  mask-image: linear-gradient(to bottom, transparent 0, #000 36%);
}
:root[data-mbackdrop="grid"] .ms-lights .l1::before {
  content: ""; position: absolute; left: 0; right: 0; top: calc(-1 * var(--cell)); bottom: 0;
  background:
    linear-gradient(to right, var(--cg) 0 var(--line), transparent var(--line)) calc(var(--cell) / 6) 0 / var(--cell) var(--cell),
    linear-gradient(to bottom, var(--cg) 0 var(--line), transparent var(--line)) 0 0 / var(--cell) var(--cell);
  animation: bd-glide 5s linear infinite;
}
@keyframes bd-glide { from { transform: translateY(0); } to { transform: translateY(var(--cell)); } }
:root[data-mbackdrop="grid"] .ms-lights .l2 {
  --cx: 540; --w: 1680; --h: 600; top: calc(58% - 300 * var(--k));
  border-radius: 50%;
  background: radial-gradient(closest-side, rgb(from var(--c) r g b / min(1, calc(alpha * 1.5))), transparent);
}
:root[data-mbackdrop="grid"] .ms-lights :is(.l3, .l4) {
  border-radius: 50%;
  background: radial-gradient(closest-side, var(--c), rgb(from var(--c) r g b / calc(alpha * .5)) 55%, transparent);
}
:root[data-mbackdrop="grid"] .ms-lights .l3 { --cx: -128; --cy: 403; --c: var(--bd-a); }
:root[data-mbackdrop="grid"] .ms-lights .l4 { --cx: 1162; --cy: 429; --c: var(--bd-b); }
:root[data-mbackdrop="grid"] .ms-lights :is(.l5, .l6) { display: none; }

/* ---------------------------------------------------------------- the phone turns in the same room
   under the two still looks, each page moves the light a little, so paging feels like turning where you stand */
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="connect"] .ms-lights .l1 { transform: translate(-30%, 8%); }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="connect"] .ms-lights .l2 { transform: translate(10%, -30%); }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="punch"] .ms-lights .l1 { transform: translate(-46%, 22%); opacity: .75; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="punch"] .ms-lights .l3 { transform: translate(-20%, -18%); }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="hit"] .ms-lights .l1 { transform: translate(-40%, -4%); }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="hit"] .ms-lights .l3 { opacity: .35; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="ranks"] .ms-lights .l2 { transform: translate(40%, 30%); opacity: .5; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="ranks"] .ms-lights .l3 { opacity: .4; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="feed"] .ms-lights .l1 { transform: translate(-10%, -20%); opacity: .6; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="feed"] .ms-lights .l3 { opacity: .3; }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="profile"] .ms-lights .l1 { transform: translate(-58%, 0); }
:root:is([data-mbackdrop="glow"], [data-mbackdrop="lights"]) .m-app[data-page="profile"] .ms-lights .l2 { opacity: .4; }

/* ---------------------------------------------------------------- reduced motion: every look as a still */
@media (prefers-reduced-motion: reduce) {
  .ms-lights i,
  .ms-lights::before,
  .ms-lights i::before { animation: none !important; transition: none !important; }
  :root[data-mbackdrop="beams"] .ms-lights i { transform: rotate(var(--a)); }
  /* the heartbeat held at three moments of one rise, so the still still reads as light climbing from the base */
  :root[data-mbackdrop="pulse"] .ms-lights :is(.l2, .l4, .l6) { display: none; }
  :root[data-mbackdrop="pulse"] .ms-lights .l1 { opacity: .9; transform: translateY(calc(-260 * var(--v))) scale(.55); }
  :root[data-mbackdrop="pulse"] .ms-lights .l3 { opacity: .6; transform: translateY(calc(-1000 * var(--v))) scale(.95); }
  :root[data-mbackdrop="pulse"] .ms-lights .l5 { opacity: .3; transform: translateY(calc(-1800 * var(--v))) scale(1.3); }
  :root[data-mbackdrop="pulse"] .ms-lights::before { opacity: .8; }
  :root[data-mbackdrop="embers"] .ms-lights i,
  :root[data-mbackdrop="spot"] .ms-lights i,
  :root[data-mbackdrop="smoke"] .ms-lights i { translate: none; transform: none; opacity: 1; }
}

/* The machine's shared header (parts/ms-brand.html): a global section whose wrapper takes no room, so each design is
   laid out by the screen exactly where the old header sat: the band from --ms-brand-top, --ms-brand-h tall (100 to
   224 px on the glass). Every design stays inside that band, in the screen's own tokens, so all four looks carry it:
     Lockup           the mark and the wordmark, centred (styles.css .ms-brand, the frames' own header)
     Venue and clock  the lockup at the left gutter; the time, large, and the venue at the right
     Slim bar         one glass bar across the glass: a small lockup, a live light and the machine's number
     Crest            the mark alone in a lit ring at the centre, the venue to its left and the time to its right
     Stacked          the mark over a smaller wordmark, centred, for screens that want a quieter top */
.mscreen .ms-head { display: contents; }
.mscreen .ms-head > [data-sv][hidden] { display: none !important; }
/* the wrapper has no box, so pointing at its Customise row marks the design on show instead */
.mscreen .ms-head.is-target > [data-sv]:not([hidden]) { outline: 10px dashed #EB1110; outline-offset: -10px; }

.mscreen .msh {
  position: absolute; z-index: 2; top: var(--ms-brand-top); left: 0; right: 0; height: var(--ms-brand-h); margin: 0;
  display: flex; align-items: center;
  pointer-events: none;
}
.mscreen .msh p { margin: 0; }
.mscreen .msh-lock { display: flex; align-items: center; flex: none; }
.mscreen .msh-mark { flex: none; display: block; object-fit: contain; }
.mscreen .msh-word { flex: none; }
/* the two wordmarks follow the appearance (styles.css .ms-on-dark, .ms-on-light); say so again at this specificity */
.mscreen .msh-word.ms-on-light { display: none; }
:root[data-appearance="light"] .mscreen .msh-word.ms-on-dark { display: none; }
:root[data-appearance="light"] .mscreen .msh-word.ms-on-light { display: block; }
.mscreen .msh [data-lucide] { flex: none; }

/* ---------------------------------------------------------------- Venue and clock */
.mscreen .msh-venue { justify-content: space-between; padding: 0 var(--ms-gut); }
.mscreen .msh-venue .msh-lock { gap: 20px; }
.mscreen .msh-venue .msh-mark { width: 96px; height: 101px; }
.mscreen .msh-venue .msh-word { width: 318px; height: 69.2px; }
.mscreen .msh-venue .msh-where { display: grid; justify-items: end; row-gap: 16px; }
.mscreen .msh-clock {
  font: 800 76px/1 var(--f-display); letter-spacing: .01em; color: var(--ink-1);
  font-variant-numeric: tabular-nums; text-box: trim-both cap alphabetic;
}
.mscreen .msh-place {
  display: flex; align-items: center; gap: 10px;
  font: 600 32px/1 var(--f-label); letter-spacing: .04em; color: var(--ink-2); white-space: nowrap;
  text-box: trim-both cap alphabetic;
}
.mscreen .msh-place [data-lucide] { font-size: 32px; color: var(--strike); }

/* ---------------------------------------------------------------- Slim bar: one glass bar, the lockup and the unit,
   on the glass's gutters like every section below it; the unit is plain text in the bar, not a second pill inside it */
.mscreen .msh-bar { padding: 0 var(--ms-gut); }
.mscreen .msh-bar-in {
  flex: 1; height: 104px; display: flex; align-items: center; gap: 28px;
  padding: 0 36px 0 32px; border-radius: 52px;
  background: color-mix(in oklab, var(--ink-1) 7%, transparent);
  box-shadow: inset 0 0 0 2px color-mix(in oklab, var(--ink-1) 12%, transparent), 0 24px 48px -30px rgba(0, 0, 0, .6);
  -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px);
}
.mscreen .msh-bar .msh-lock { gap: 16px; margin-right: auto; }
.mscreen .msh-bar .msh-mark { width: 68px; height: 72px; }
.mscreen .msh-bar .msh-word { width: 236px; height: 51.4px; }
.mscreen .msh-live, .mscreen .msh-unit {
  display: flex; align-items: center; gap: 12px; white-space: nowrap;
  font: 700 32px/1 var(--f-label); letter-spacing: .08em; text-transform: uppercase; color: var(--ink-1);
  text-box: trim-both cap alphabetic;
}
.mscreen .msh-unit { color: var(--ink-2); }
.mscreen .msh-unit [data-lucide] { font-size: 32px; color: var(--ink-1); }
.mscreen .msh-dot {
  position: relative; width: 18px; height: 18px; border-radius: 50%; background: var(--strike);
  box-shadow: 0 0 16px color-mix(in oklab, var(--strike) 80%, transparent);
}
.mscreen .msh-dot::after {
  content: ""; position: absolute; inset: -8px; border-radius: 50%; border: 3px solid var(--strike);
  opacity: 0; animation: msh-ping 2.4s cubic-bezier(.2, .6, .4, 1) infinite;
}
@keyframes msh-ping { 0% { opacity: .9; transform: scale(.5); } 70%, 100% { opacity: 0; transform: scale(1.5); } }

/* ---------------------------------------------------------------- Crest: the mark in a lit ring, flanked */
.mscreen .msh-crest { justify-content: center; gap: 48px; }
.mscreen .msh-ring {
  position: relative; flex: none; width: var(--ms-brand-h); height: var(--ms-brand-h); border-radius: 50%;
  display: grid; place-items: center;
  background: radial-gradient(closest-side, color-mix(in oklab, var(--strike) 22%, transparent), transparent);
  box-shadow: inset 0 0 0 4px var(--strike);
}
.mscreen .msh-crest .msh-mark { width: 80px; height: 84px; }
.mscreen .msh-side {
  flex: 1; display: flex; align-items: center; gap: 12px; white-space: nowrap;
  font: 700 38px/1 var(--f-label); letter-spacing: .1em; text-transform: uppercase; color: var(--ink-2);
  text-box: trim-both cap alphabetic;
}
.mscreen .msh-side-l { justify-content: flex-end; }
.mscreen .msh-side-r { font-variant-numeric: tabular-nums; }
.mscreen .msh-side [data-lucide] { font-size: 38px; color: var(--strike); }

/* ---------------------------------------------------------------- Stacked: the mark over a smaller wordmark */
.mscreen .msh-stack { flex-direction: column; justify-content: center; gap: 6px; }
.mscreen .msh-stack .msh-mark { width: 66px; height: 70px; }
.mscreen .msh-stack .msh-word { width: 220px; height: 47.9px; }
:root[data-appearance="light"] .mscreen .msh-bar-in {
  background: color-mix(in oklab, #FFFFFF 70%, transparent);
  box-shadow: inset 0 0 0 2px color-mix(in oklab, var(--ink-1) 10%, transparent), 0 24px 48px -30px rgba(70, 45, 30, .35);
}

@media (prefers-reduced-motion: reduce) {
  .mscreen .msh-dot::after { animation: none; opacity: .5; transform: scale(1.1); }
}

/* One spacing scale for every machine flow screen on the 1080 x 3840 glass (round six: "every page needs better
   spacing"). Read from 1 to 1.5 m, so the steps are big; screens use these instead of one-off numbers:
   --ms-gut        the glass's side margin
   --ms-sec-gap    between two sections of a screen
   --ms-group-gap  between groups inside a section (a heading and its content)
   --ms-item-gap   between items in a list
   --ms-pad        inside a card or a tile
   The sponsor strip at the foot (140 px) and the header at the top are shared chrome; a screen's sections sit between. */
.mscreen { --ms-gut: 88px; --ms-sec-gap: 120px; --ms-group-gap: 56px; --ms-item-gap: 28px; --ms-pad: 48px; }

/* Machine screen: attract, the leaderboard the glass shows between players (parts/mscreen-attract.html,
   mscreens/attract.js). One frame, four sections stacked between the shared header and the sponsor strip, each with
   five designs chosen in Customise ("This screen"):
     Title          Phone header, Scope name, Icon tabs, Photo banner, Timer ring, each with the one board switch
     Top three      Cards, Podium, Champion, Force meter, Tiles (the phone's five board styles at glass scale)
     Ranks 4 to 10  Glass rows, Table, Meter rows, Tiles, Ladder
     Call to play   Red card, Big code, Your bar, Phone photo, Open rank (the shared QR style, a line, a You row)
   Every section has a fixed room (the --msa-*-room heights), so the frame never moves when a design changes, and every
   design fits its room in all four looks. Spacing is the glass's own scale (mscreens/_space.css). Read from 1 to 1.5 m:
   body text 40 px and up, labels 32 px and up. Every rule is scoped under .mscreen-attract. */

/* ---------------------------------------------------------------- tokens per look. Arena dark is the default */
.mscreen-attract {
  --msa-top: calc(var(--ms-brand-top) + var(--ms-brand-h) + 72px);
  --msa-title-room: 390px;
  --msa-top-room: 1000px;
  --msa-ranks-room: 1140px;
  --msa-cta-room: 432px;
  --msa-cycle: 9s;
  --msa-lag: 0ms;
  --msa-k: 1;                         /* the display face's width: Reference's Archivo Black runs wider */
  --msa-red: var(--strike);
  --msa-on-red: #FFFFFF;
  --msa-badge: linear-gradient(180deg, color-mix(in oklab, var(--strike), #FFFFFF 10%), color-mix(in oklab, var(--strike), #000000 20%));
  --msa-badge-glow: 0 18px 36px -16px color-mix(in oklab, var(--strike) 80%, transparent);
  --msa-glass: var(--surface-bg);
  --msa-glass-line: var(--surface-border);
  --msa-lead: linear-gradient(135deg, color-mix(in oklab, var(--strike) 24%, transparent), color-mix(in oklab, var(--strike) 6%, transparent) 60%), var(--surface-bg);
  --msa-lead-line: 3px solid color-mix(in oklab, var(--strike) 62%, transparent);
  --msa-you: linear-gradient(135deg, #8E0D11, #2A0709 70%);
  --msa-you-line: 2px solid rgba(250, 84, 83, .45);
  --msa-champ: linear-gradient(135deg, #C8121A, #7A0A0E 62%, #3A0508);
  --msa-step: linear-gradient(180deg, rgba(255, 255, 255, .1), rgba(255, 255, 255, .02));
  --msa-step-first: linear-gradient(180deg, color-mix(in oklab, var(--strike) 62%, transparent), color-mix(in oklab, var(--strike) 6%, transparent));
  --msa-well: rgba(255, 255, 255, .05);
  --msa-solid: var(--ground);          /* a flat colour under the wells: Arena's --ms-ground is a gradient list, which cannot follow another layer */
  --msa-zebra: rgba(255, 255, 255, .045);
  --msa-ring: rgba(255, 255, 255, .22);
  --msa-crown: var(--strike);          /* the leader's crown in the brand red, as on every Results screen (round nine) */
  --msa-up: #43D787;
  --msa-down: #FF6B6B;
  --msa-track: rgba(255, 255, 255, .1);
  --msa-bar: linear-gradient(90deg, #A90E12, var(--strike) 70%, #FA5453);
  --msa-dash: color-mix(in oklab, var(--ink-1) 26%, transparent);
  --msa-scrim: linear-gradient(180deg, rgba(8, 8, 9, .05) 30%, rgba(8, 8, 9, .86) 100%);
  --msa-letter: .5;
}
:root[data-appearance="light"] .mscreen-attract {
  --msa-lead: linear-gradient(135deg, color-mix(in oklab, var(--strike) 12%, #FFFFFF), #FFFFFF 60%);
  --msa-lead-line: 3px solid color-mix(in oklab, var(--strike) 55%, transparent);
  --msa-you: linear-gradient(135deg, #D8141A, #8E0D11);
  --msa-you-line: 0 solid transparent;
  --msa-champ: linear-gradient(135deg, #E0161D, #A50D12 62%, #6E080B);
  --msa-step: linear-gradient(180deg, #FFFFFF, rgba(255, 255, 255, .45));
  --msa-step-first: linear-gradient(180deg, color-mix(in oklab, var(--strike) 96%, #FFFFFF), color-mix(in oklab, var(--strike) 58%, #FFFFFF));
  --msa-well: rgba(21, 20, 19, .05);
  --msa-zebra: rgba(21, 20, 19, .04);
  --msa-ring: rgba(21, 20, 19, .16);
  --msa-up: #0A6E3A;
  --msa-down: #B71C1C;
  --msa-track: rgba(21, 20, 19, .09);
  --msa-bar: linear-gradient(90deg, #B30D10, var(--strike) 70%, #F04544);
}

.mscreen-attract [hidden], .mscreen-attract [data-sv][hidden] { display: none !important; }

/* ---------------------------------------------------------------- the frame: sections stacked between header and strip */
.mscreen-attract .msa {
  position: absolute; inset: 0; overflow: hidden; isolation: isolate;
  display: flex; flex-direction: column; gap: var(--ms-sec-gap);
  padding: var(--msa-top) 0 calc(var(--ms-ad-h) + 80px);
  color: var(--ink-1); font-family: var(--f-text);
}
.mscreen-attract .msa > :not(.ms-lights, .ms-head, .ms-head > *, .ms-brand, .ms-ad, .sr-only) { position: relative; z-index: 1; flex: none; }
.mscreen-attract .msa-sec { margin: 0 var(--ms-gut); }
.mscreen-attract .msa-title { height: var(--msa-title-room); }
.mscreen-attract .msa-top { height: var(--msa-top-room); }
.mscreen-attract .msa-ranks { height: var(--msa-ranks-room); }
.mscreen-attract .msa-play { height: var(--msa-cta-room); }
.mscreen-attract .msa-sec > [data-sv], .mscreen-attract .msa-body { position: relative; height: 100%; }
.mscreen-attract ol, .mscreen-attract ul { list-style: none; margin: 0; padding: 0; }
.mscreen-attract p, .mscreen-attract h2 { margin: 0; }
.mscreen-attract img { display: block; }
.mscreen-attract [data-lucide] { display: inline-flex; flex: none; }

/* shared type */
.mscreen-attract .msa-t-kicker, .mscreen-attract .msa-c-kicker {
  display: flex; align-items: center; gap: 16px;
  font: var(--w-label) 36px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: var(--ink-2);
}
.mscreen-attract :is(.msa-t-kicker, .msa-c-kicker) > [data-lucide] { font-size: 44px; color: var(--msa-red); }
.mscreen-attract .msa-disp {
  font-family: var(--f-display); font-weight: var(--w-display); text-transform: var(--display-case); letter-spacing: var(--display-track); line-height: .9;
}

/* the pieces every board uses: rank, avatar, who, score, movement */
.mscreen-attract .msa-rk {
  display: grid; place-items: center; width: 96px; height: 96px; border-radius: 28px;
  background: var(--msa-well); border: 2px solid var(--line); color: var(--ink-1);
  font-family: var(--f-display); font-weight: var(--w-display); font-size: calc(46px / var(--cap)); line-height: 1; font-variant-numeric: tabular-nums;
}
.mscreen-attract .msa-rk.is-red { background: var(--msa-badge); color: var(--msa-on-red); border: 0; box-shadow: var(--msa-badge-glow); }
.mscreen-attract .msa-ava { display: block; flex: none; width: 104px; height: 104px; border-radius: 50%; object-fit: cover; background: var(--msa-well); }
.mscreen-attract .msa-ghost {
  display: grid; place-items: center; flex: none; width: 104px; height: 104px; border-radius: 50%;
  border: 3px dashed var(--msa-dash); color: var(--ink-3); font-size: 48px;
}
.mscreen-attract .msa-who { display: grid; gap: 6px; min-width: 0; }
.mscreen-attract .msa-name { display: flex; align-items: center; gap: 16px; min-width: 0; font: var(--w-strong) 44px/1.1 var(--f-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mscreen-attract .msa-name > span:last-child { overflow: hidden; text-overflow: ellipsis; }
.mscreen-attract .msa-name .ico { flex: none; color: var(--msa-crown); }
.mscreen-attract .msa-ghost .ico, .mscreen-attract .msa-crown .ico { display: block; }
/* an open place on a smaller board keeps the board's shape */
.mscreen-attract :is(.msa-card, .msa-lite, .msa-meter, .msa-champ-card).is-open { background: transparent; border: 3px dashed var(--msa-dash); box-shadow: none; color: var(--ink-1); }
.mscreen-attract .msa-city { font: var(--w-text) 32px/1.15 var(--f-text); color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mscreen-attract .msa-end { display: grid; justify-items: end; align-content: center; gap: 8px; }
.mscreen-attract .msa-pts {
  --budget: 290px; --top: 58px;
  font-family: var(--f-display); font-weight: var(--w-display); line-height: .9; letter-spacing: var(--display-track);
  white-space: nowrap; font-variant-numeric: tabular-nums; color: var(--ink-1);
  font-size: min(calc(var(--top) / var(--cap)), calc(var(--budget) / (var(--chars, 8.8) * var(--num-w))));
}
.mscreen-attract .msa-move { display: inline-flex; align-items: center; gap: 6px; font: var(--w-strong) 32px/1 var(--f-text); font-variant-numeric: tabular-nums; }
.mscreen-attract .msa-move svg { width: 32px; height: 32px; fill: none; stroke: currentColor; stroke-width: 2.8; stroke-linecap: round; stroke-linejoin: round; }
.mscreen-attract .msa-move.up { color: var(--msa-up); }
.mscreen-attract .msa-move.down { color: var(--msa-down); }
.mscreen-attract .msa-move.down svg { transform: rotate(180deg); }
.mscreen-attract .msa-move.same { min-height: 32px; }
.mscreen-attract .msa-open-name { color: var(--ink-2); }
.mscreen-attract .msa-open-city { color: var(--msa-red); }
/* a photo that fills its tile, the look's scrim under white type */
.mscreen-attract .msa-pic { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.mscreen-attract .msa-shade { position: absolute; inset: 0; background: var(--msa-scrim); pointer-events: none; }

/* ================================================================ TITLE */
/* The board switch (.msa-sw), one control in every Title design, the Global, National and Dubai boards as a segmented
   control. The well sits on the glass's 40 px radius; the segments inside it on the radius less the inset (10 px) and
   the line (2 px), so the two curves run parallel. The board on show is the red segment, white type; its bright red
   drains from right to left over the board's time and leaves the deep red behind, so the switch is also the clock.
   The other boards read in the second ink on the well. Labels 40 px and up, segments 100 px and up: read from 3 m.
   Under reduced motion the red stands full and the board still changes. */
.mscreen-attract {
  --msa-sw-r: 40px;
  --msa-sw-pad: 10px;
  --msa-sw-line: 2px;
  --msa-sw-seg: calc(var(--msa-sw-r) - var(--msa-sw-pad) - var(--msa-sw-line));
  --msa-sw-fs: 42px;
  --msa-sw-track: .06em;
  --msa-sw-spent: color-mix(in oklab, var(--strike), #000000 50%);
}
.mscreen-attract .msa-sw {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; height: 124px; padding: var(--msa-sw-pad);
  border-radius: var(--msa-sw-r); border: var(--msa-sw-line) solid var(--line);
  background: linear-gradient(var(--msa-well), var(--msa-well)) var(--msa-solid);
}
.mscreen-attract .msa-scope {
  position: relative; overflow: hidden; isolation: isolate; min-width: 0;
  display: flex; align-items: center; justify-content: center; gap: 16px; padding: 0 20px;
  border-radius: var(--msa-sw-seg); color: var(--ink-2);
  font: var(--w-label) var(--msa-sw-fs)/1 var(--f-label); letter-spacing: var(--msa-sw-track); text-transform: uppercase; white-space: nowrap;
  transition: background-color .4s ease, color .4s ease;
}
.mscreen-attract .msa-sw-l { position: relative; margin-right: calc(-1 * var(--msa-sw-track)); }
.mscreen-attract .msa-sw-i { position: relative; font-size: 44px; }
.mscreen-attract .msa-scope.is-on { background: var(--msa-sw-spent); color: var(--msa-on-red); box-shadow: var(--msa-badge-glow); }
.mscreen-attract .msa-fill {
  position: absolute; inset: 0; z-index: -1; background: var(--msa-badge);
  transform-origin: 0 50%; transform: scaleX(0);
}
.mscreen-attract .msa-scope.is-on .msa-fill { transform: scaleX(1); }
.mscreen-attract .is-live .msa-scope.is-on .msa-fill { animation: msa-drain var(--msa-cycle) linear both; animation-delay: var(--msa-lag); }

/* Phone header: the phone's own header, its title and trophy, and its segmented control */
.mscreen-attract .msa-t-phone { display: grid; align-content: start; gap: 28px; }
.mscreen-attract .msa-t-live { display: flex; align-items: center; gap: 16px; font: var(--w-strong) 38px/1 var(--f-text); color: var(--ink-2); }
.mscreen-attract .msa-t-live [data-lucide] { font-size: 44px; color: var(--msa-red); }
.mscreen-attract .msa-t-row { display: flex; align-items: center; justify-content: space-between; gap: 32px; }
.mscreen-attract .msa-t-title {
  font-family: var(--f-display); font-weight: var(--w-display); text-transform: var(--display-case); letter-spacing: var(--display-track);
  font-size: min(calc(120px / var(--cap)), calc(700px / (11 * var(--msa-letter)))); line-height: .9;
}
.mscreen-attract .msa-t-trophy {
  flex: none; display: grid; place-items: center; width: 136px; height: 136px; border-radius: 40px; font-size: 68px;
  background: var(--surface-hi-bg); border: var(--surface-hi-border); box-shadow: var(--surface-shadow); color: var(--ink-1);
}
.mscreen-attract .msa-t-phone .msa-sw { margin-top: 6px; }

/* Scope name: the board's name as big as the glass allows, the switch standing beside it, one board to a row */
.mscreen-attract .msa-t-name { display: grid; grid-template-columns: minmax(0, 1fr) 340px; align-items: center; column-gap: 48px; }
.mscreen-attract .msa-t-names { display: grid; gap: 28px; min-width: 0; container-type: inline-size; }
.mscreen-attract .msa-t-big {
  font-family: var(--f-display); font-weight: var(--w-display); text-transform: var(--display-case); letter-spacing: var(--display-track);
  font-size: min(calc(210px / var(--cap)), calc(100cqi / (8.4 * var(--msa-letter)))); line-height: .84; white-space: nowrap;
}
.mscreen-attract .msa-sw-col { grid-template-columns: none; grid-template-rows: repeat(3, minmax(0, 1fr)); height: 350px; }
.mscreen-attract .msa-sw-col .msa-scope { justify-content: flex-start; padding: 0 24px; }

/* Icon tabs: the Force meter's heading over a tall switch, each board's mark over its name */
.mscreen-attract .msa-t-tabs { display: grid; align-content: center; gap: 24px; }
.mscreen-attract .msa-t-hard {
  max-width: 880px; text-wrap: balance; font-family: var(--f-display); font-weight: var(--w-display); text-transform: var(--display-case);
  letter-spacing: var(--display-track); font-size: min(calc(94px / var(--cap)), calc(880px / (15 * var(--msa-letter) * 1.1))); line-height: .9; white-space: nowrap;
}
.mscreen-attract .msa-sw-tall { height: 164px; margin-top: 8px; }
.mscreen-attract .msa-sw-tall .msa-scope { flex-direction: column; gap: 16px; }
.mscreen-attract .msa-sw-tall .msa-sw-i { font-size: 48px; }

/* Photo banner: a real photo for each board, the switch in smoked glass along its top, the board's name at its foot */
.mscreen-attract .msa-t-photo { overflow: hidden; border-radius: var(--msa-sw-r); color: #FFFFFF; background: #0B0B0C; box-shadow: var(--surface-shadow); }
.mscreen-attract .msa-t-pics img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity .6s ease; }
.mscreen-attract .msa-t-pics img.is-on { opacity: 1; }
.mscreen-attract .msa-t-pics::after {
  content: ""; position: absolute; inset: 0;
  /* the switch and the title sit on the photo: a scrim under all of it, deepest where the type is */
  background: linear-gradient(180deg, rgba(8, 8, 9, .8), rgba(8, 8, 9, .5) 34%, rgba(8, 8, 9, .46) 52%, rgba(8, 8, 9, .9));
}
/* the switch in smoked glass, white type in every look (it sits on a photo), inset by the gutter it keeps below */
.mscreen-attract .msa-sw-glass {
  position: absolute; left: 32px; right: 32px; top: 32px; height: 112px;
  background: rgba(8, 8, 9, .56); border-color: rgba(255, 255, 255, .24); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
}
.mscreen-attract .msa-sw-glass .msa-scope { color: rgba(255, 255, 255, .86); }
.mscreen-attract .msa-sw-glass .msa-scope.is-on { color: #FFFFFF; }
.mscreen-attract .msa-t-foot { position: absolute; left: 44px; right: 44px; bottom: 40px; display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; container-type: inline-size; }
.mscreen-attract .msa-t-over {
  display: flex; align-items: center; gap: 24px; min-width: 0;
  font-family: var(--f-display); font-weight: var(--w-display); text-transform: var(--display-case); letter-spacing: var(--display-track);
  font-size: min(calc(96px / var(--cap)), calc((100cqi - 340px) / (8.4 * var(--msa-letter)))); line-height: .9; white-space: nowrap; text-shadow: 0 4px 30px rgba(0, 0, 0, .5);
}
.mscreen-attract .msa-t-ic {
  flex: none; display: grid; place-items: center; width: 112px; height: 112px; border-radius: 32px; font-size: 60px;
  background: var(--msa-badge); color: var(--msa-on-red); box-shadow: var(--msa-badge-glow);
}
.mscreen-attract .msa-t-overtext { display: grid; gap: 16px; min-width: 0; }
.mscreen-attract .msa-t-small { font: var(--w-label) 32px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase; color: rgba(255, 255, 255, .84); text-shadow: none; }
.mscreen-attract .msa-t-chip {
  flex: none; display: inline-flex; align-items: center; gap: 16px; height: 72px; padding: 0 28px; border-radius: 36px;
  background: rgba(8, 8, 9, .5); border: 2px solid rgba(255, 255, 255, .24); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
  font: var(--w-label) 34px/1 var(--f-label); letter-spacing: var(--label-track); text-transform: uppercase;
}
