.lb-y-photo-img { align-self: stretch; width: 88px; height: 100%; min-height: 88px; object-fit: cover; object-position: 40% 40%; -webkit-mask-image: linear-gradient(90deg, #000 60%, transparent); mask-image: linear-gradient(90deg, #000 60%, transparent); }
.lb-y-photo-rk b { font: var(--m-w-num-hi) calc(46px * var(--m-num-scale))/.9 var(--m-num); color: var(--m-red-soft); }
.lb-y-photo .m-who { gap: 6px; }
.lb-y-photo .m-cap { font-size: 11px; }

/* Percentile: the share of the board you are ahead of, on a scale */
.lb-y-pct {
  display: grid; grid-template-columns: 64px minmax(0, 1fr); align-items: center; column-gap: 16px; row-gap: 12px;
  padding: 12px 16px 16px 12px;
  background: var(--m-sheet); -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px);
  box-shadow: 0 18px 34px -16px var(--m-shadow);
}
.lb-y-top { display: grid; justify-items: center; align-content: center; gap: 2px; width: 64px; height: 64px; border-radius: 16px; background: var(--m-cta); color: var(--m-on-red); }
.lb-y-top small { font: var(--m-w-label) 11px/1 var(--m-f-label); letter-spacing: .14em; text-transform: uppercase; }
.lb-y-top b { font: var(--m-w-num-hi) calc(26px * var(--m-num-scale))/1 var(--m-num); }
.lb-y-scale { grid-column: 1 / -1; position: relative; height: 6px; margin: 0 6px; border-radius: 3px; background: var(--m-track); }
.lb-y-scale i { position: absolute; left: 0; top: 0; bottom: 0; width: calc(var(--p) * 100%); border-radius: inherit; background: linear-gradient(90deg, var(--m-red-deep), var(--m-red-soft)); }
.lb-y-scale i::after { content: ""; position: absolute; right: -7px; top: 50%; width: 14px; height: 14px; border-radius: 50%; background: var(--m-red); transform: translateY(-50%); box-shadow: 0 0 0 3px var(--m-sheet); }

/* ---------------------------------------------------------------- motion: the page rises in, a new design eases in */
.lb-page.is-entering .lb-head, .lb-page.is-entering .m-board { animation: lb-rise .6s cubic-bezier(.2, .7, .2, 1) both; }
.lb-page.is-entering .m-board { animation-delay: .1s; }
.lb-page.is-entering .lb-you > * { animation: lb-pin .5s cubic-bezier(.2, .7, .2, 1) .25s both; }
.lb-page .is-swap { animation: lb-rise .5s cubic-bezier(.2, .7, .2, 1) both; }
