  cursor: pointer; border-radius: 6px;
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev-btn:focus-visible { outline: 2px solid var(--_ink); outline-offset: 4px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev-btn:hover .cd-ev-t { text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-dot {
  flex: none; width: 12px; height: 12px; margin-top: 4px; border-radius: 50%;
  background: var(--_bg); box-shadow: inset 0 0 0 2px var(--_ink);
  transition: background-color .3s ease, box-shadow .3s ease, transform .4s var(--_ease);
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev.is-past .cd-dot { background: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev.is-key .cd-dot { box-shadow: inset 0 0 0 2px var(--_accent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev.is-key.is-past .cd-dot { background: var(--_accent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev.is-active .cd-dot { background: var(--_accent); box-shadow: inset 0 0 0 2px var(--_accent), 0 0 0 5px color-mix(in srgb, var(--_accent) 24%, transparent); transform: scale(1.12); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev-d { margin-top: 6px; font-size: 13px; line-height: 1.45; color: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ev .cd-cell-time { padding-bottom: 28px; }

/* miniatures and captions */
:is(.cd-state, .cd-run, .cd-geometry) .cd-mini { position: relative; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-mini svg { display: block; width: 100%; height: auto; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-mini-glass { width: var(--gl); aspect-ratio: 180 / 640; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-mini-phone { width: var(--ph); aspect-ratio: 236 / 511; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ghost { width: 100%; height: 100%; border-radius: 7px; outline: 1.5px dashed color-mix(in srgb, var(--_ink) 30%, var(--_bg)); outline-offset: -1.5px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ghost-phone { border-radius: 14px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-cap-t { margin-top: 16px; font-size: 14px; font-weight: 600; line-height: 1.3; color: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-cap-d { margin-top: 4px; font-size: 13px; line-height: 1.45; color: var(--_muted); }

/* the glass, in the machine's own language */
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-bezel { fill: none; stroke: color-mix(in srgb, var(--_ink) 16%, transparent); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-base { fill: #5C0A0A; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-crown { font-family: "Big Shoulders Display", "Arial Narrow", sans-serif; font-weight: 900; font-size: 50px; fill: #F5F3EF; letter-spacing: .01em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-ghost { fill: rgba(245, 243, 239, .1); font-size: 41px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-plate-fill { fill: #1B1B1E; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-plate-red { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-plate-edge { fill: rgba(255, 255, 255, .14); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-bell { fill: rgba(245, 243, 239, .55); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-plate-label { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-weight: 700; font-size: 11px; letter-spacing: .12em; fill: #F5F3EF; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-plate-dec { font-family: "Big Shoulders Display", "Arial Narrow", sans-serif; font-weight: 900; font-size: 18px; fill: rgba(245, 243, 239, .72); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-rail { fill: #1E1E21; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-rail-charge, :is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-notch { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-tick, :is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-today { fill: rgba(245, 243, 239, .75); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-replay-shade { fill: rgba(11, 11, 12, .18); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-replay image { filter: saturate(.4) contrast(1.08); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-prog { fill: rgba(245, 243, 239, .18); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-prog-on { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-scrim { fill: rgba(11, 11, 12, .62); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-hitit, :is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-call-t { font-family: "Big Shoulders Display", "Arial Narrow", sans-serif; font-weight: 900; fill: #F5F3EF; letter-spacing: .02em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-hitit { font-size: 28px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-call-t { font-size: 21px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-rec { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-head { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-weight: 700; font-size: 12px; letter-spacing: .08em; fill: #F5F3EF; }
/* the run code in the one QR style (qr.css): the phone app's glass tile, white rim, white code, the red glow behind */
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-qr-tile {
  fill: rgba(38, 38, 38, .2); stroke: #FFFFFF; stroke-width: .6; rx: 6.9px;
  filter: drop-shadow(0 0 7px rgba(206, 19, 22, .55));
}
/* the modules live in a <use> clone, out of reach of a descendant selector: they inherit their fill from the group */
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-qr { fill: #FAF9F9; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-still image { filter: saturate(.5); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-still-edge { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-kept { fill: #363637; } /* white at 16% over the glass: the kept hit's still, faded */
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-copy { fill: rgba(245, 243, 239, .38); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-copy-kept { fill: #F5F3EF; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-code { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-weight: 600; font-size: 10px; letter-spacing: .12em; fill: rgba(245, 243, 239, .8); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-pay { fill: #F5F3EF; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-red-line { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-charge { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-charge-edge { fill: #FF6A5F; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-today-line { fill: rgba(255, 255, 255, .5); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-runline { fill: none; stroke: #F5F3EF; stroke-width: 3; stroke-linecap: round; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-clear { opacity: 0; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-was, :is(.cd-state, .cd-run, .cd-geometry) .cd-glass .g-fall { opacity: 0; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass.is-same { opacity: .5; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-glass :is(.g-charge, .g-charge-edge, .g-rail-charge, .g-land, .g-arrive, .g-still-new, .g-prompt, .g-kept, .g-copy-kept, .g-qr-row) { transform-box: fill-box; }

/* the phone */
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-bezel { fill: none; stroke: color-mix(in srgb, var(--_ink) 16%, transparent); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-bar, :is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-home { fill: rgba(245, 243, 239, .6); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-t { font-family: "Inter", ui-sans-serif, system-ui, sans-serif; fill: #F5F3EF; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-place { font-size: 9.5px; font-weight: 600; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-nav { font-size: 9px; font-weight: 600; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-small { font-size: 8px; fill: rgba(245, 243, 239, .62); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-tiny { font-size: 6.6px; fill: rgba(245, 243, 239, .55); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-title { font-size: 16px; font-weight: 700; letter-spacing: -.01em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-body { font-size: 7.4px; fill: rgba(245, 243, 239, .62); }
