:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-int { font-family: "Big Shoulders Display", "Arial Narrow", sans-serif; font-weight: 900; font-size: 66px; fill: #F5F3EF; letter-spacing: .005em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-plate { fill: #151517; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-plate-empty { fill: #111113; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-plate-edge { fill: rgba(255, 255, 255, .22); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-label { font-family: "Barlow Condensed", "Arial Narrow", sans-serif; font-weight: 700; font-size: 9.5px; letter-spacing: .12em; fill: #F5F3EF; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-dec { font-family: "Big Shoulders Display", "Arial Narrow", sans-serif; font-weight: 900; font-size: 21px; fill: rgba(245, 243, 239, .7); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-btn-red { fill: #EB1110; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-btn-line { fill: none; stroke: rgba(245, 243, 239, .45); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-btn-t { font-size: 8.6px; font-weight: 600; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-kept-t { font-size: 20px; font-weight: 700; letter-spacing: -.02em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-dead-t { font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-empty { fill: #1A1A1C; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone .p-unblur { opacity: 0; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-phone :is(.p-int, .p-cta, .p-cell, .p-kept, .p-dead) { transform-box: fill-box; }

/* live miniatures: each plays its moment when the playhead reaches it, and rests on its final frame */
.cd-run.cd-motion .cd-ev.is-active .g-prompt { animation: cd-rise .6s var(--_ease) .25s both; }
.cd-run.cd-motion .cd-ev.is-active .g-rec { animation: cd-blink 1.1s steps(2, jump-none) .2s 2 both; }
.cd-run.cd-motion .cd-ev.is-active .g-land { animation: cd-land .55s cubic-bezier(.3, 1.3, .5, 1) .15s both; }
.cd-run.cd-motion .cd-ev.is-active .g-arrive { animation: cd-rise .7s var(--_ease) .55s both; }
.cd-run.cd-motion .cd-ev.is-active :is(.g-charge, .g-rail-charge) { transform-origin: 50% 100%; animation: cd-charge 1.1s cubic-bezier(.2, .8, .2, 1) .1s both; }
.cd-run.cd-motion .cd-ev.is-active .g-charge-edge { animation: cd-edge-up 1.1s cubic-bezier(.2, .8, .2, 1) .1s both; }
.cd-run.cd-motion .cd-ev.is-active .g-clear { animation: cd-out .5s ease .1s both; }
.cd-run.cd-motion .cd-ev.is-active .g-still-new { animation: cd-in .5s ease .6s both; }
.cd-run.cd-motion .cd-ev.is-active .g-kept { animation: cd-kept .3s ease .7s both; }
.cd-run.cd-motion .cd-ev.is-active .g-copy-kept { transform-origin: 0 50%; animation: cd-grow-x .5s var(--_ease) .8s both; }
.cd-run.cd-motion .cd-ev.is-active .g-fall { animation: cd-fall-block 1.35s linear both; }
.cd-run.cd-motion .cd-ev.is-active .g-qr-row { animation: cd-drop .7s cubic-bezier(.5, 0, .9, .6) calc(.25s + (20 - var(--r)) * .02s) both; }
.cd-run.cd-motion .cd-ev.is-active .g-was { animation: cd-out-late 1.6s ease both; }
.cd-run.cd-motion .cd-ev.is-active .g-now { animation: cd-in .45s ease 1.2s both; }
.cd-run.cd-motion .cd-ev.is-active .g-after { animation: cd-in .5s ease 1.35s both; }
.cd-run.cd-motion .cd-ev.is-active .p-cell { animation: cd-rise .6s var(--_ease) calc(.2s + var(--i) * .12s) both; }
.cd-run.cd-motion .cd-ev.is-active .p-int { animation: cd-land .6s cubic-bezier(.3, 1.3, .5, 1) .25s both; }
.cd-run.cd-motion .cd-ev.is-active .p-cta { transform-origin: 50% 50%; animation: cd-tap .5s ease .95s both; }
.cd-run.cd-motion .cd-ev.is-active .p-unblur { animation: cd-out-from-full .7s ease .35s both; }
.cd-run.cd-motion .cd-ev.is-active .p-kept { animation: cd-rise .6s var(--_ease) .75s both; }
.cd-run.cd-motion .cd-ev.is-active .p-dead { animation: cd-rise .6s var(--_ease) .3s both; }

@keyframes cd-rise { from { opacity: 0; transform: translateY(14px); } }
@keyframes cd-land { from { opacity: 0; transform: translateY(-26px); } }
@keyframes cd-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes cd-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes cd-out-late { 0%, 72% { opacity: 1; } 100% { opacity: 0; } }
@keyframes cd-out-from-full { from { opacity: 1; } to { opacity: 0; } }
@keyframes cd-blink { 50% { opacity: .15; } }
@keyframes cd-charge { from { transform: scaleY(0); } }
@keyframes cd-edge-up { from { transform: translateY(349px); } }
@keyframes cd-kept { from { opacity: 0; } to { opacity: 1; } }
@keyframes cd-grow-x { from { transform: scaleX(.8); } }
@keyframes cd-fall-block { 0%, 70% { opacity: 1; } 100% { opacity: 0; } }
@keyframes cd-drop { from { transform: none; opacity: 1; } to { transform: translateY(60px); opacity: 0; } }
@keyframes cd-tap { 40% { transform: scale(.94); } }

@media (max-width: 720px) {
  .cd-run { --col: 190px; --lane: 96px; --gl: 70px; --ph: 94px; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-lane-t { font-size: 15px; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-lane-d { font-size: 12px; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-ev-btn { font-size: 14.5px; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-now { flex-basis: 100%; margin-left: 0; }
}

/* ======================================================================== 3. viewing geometry */
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px 32px; margin-bottom: 20px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-head .cd-small { margin-top: 6px; max-width: 34em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-ctl { display: flex; flex-wrap: wrap; gap: 8px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-canvas { position: relative; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-svg { display: block; width: 100%; min-width: 1060px; max-width: 1560px; height: auto; margin-inline: auto; overflow: visible; }

:is(.cd-state, .cd-run, .cd-geometry) .cd-g-t { font-size: 11.5px; fill: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-strong { font-size: 12.5px; font-weight: 600; fill: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-soft { fill: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-note { font-size: 12px; fill: var(--_label); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-zone { font-size: 12.5px; font-weight: 600; fill: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-h { fill: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-glass { font-size: 12px; font-weight: 600; fill: var(--_accent-text); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-leader { fill: none; stroke: color-mix(in srgb, var(--_ink) 34%, var(--_bg)); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-leader.is-glass { stroke: var(--_accent); }

:is(.cd-state, .cd-run, .cd-geometry) .cd-g-head { fill: color-mix(in srgb, var(--_ink) 6%, transparent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-eyeband { fill: color-mix(in srgb, var(--_accent) 13%, transparent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-floorline { fill: none; stroke: var(--_ink); stroke-width: 2; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-hatch, :is(.cd-state, .cd-run, .cd-geometry) .cd-g-tick { fill: none; stroke: color-mix(in srgb, var(--_ink) 40%, var(--_bg)); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-decal { fill: color-mix(in srgb, var(--_accent) 42%, transparent); transition: fill .5s ease; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-cab { fill: color-mix(in srgb, var(--_ink) 4%, transparent); stroke: var(--_ink); stroke-width: 1.5; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-div { fill: rgba(255, 255, 255, .16); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-bell { fill: rgba(245, 243, 239, .7); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-pad { fill: var(--_accent-soft); stroke: var(--_ink); stroke-width: 1; stroke-dasharray: 4 3; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-reader { fill: var(--_accent); }

:is(.cd-state, .cd-run, .cd-geometry) .cd-g-fig {
  fill: color-mix(in srgb, var(--_ink) 17%, var(--_bg));
  opacity: 0;
  transition: opacity .6s ease, fill .5s ease;
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-fig.is-behind { fill: color-mix(in srgb, var(--_ink) 11%, var(--_bg)); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-fig.is-on { opacity: 1; }
.cd-geometry:not([data-step="all"]) .cd-g-fig.is-on:not(.is-act) { opacity: .5; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-fig.is-act { fill: color-mix(in srgb, var(--_ink) 36%, var(--_bg)); opacity: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-eye { fill: var(--_ink); opacity: 0; transition: opacity .5s ease; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-eye.is-hollow { fill: var(--_bg); stroke: var(--_ink); stroke-width: 1.5; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-eye.is-on { opacity: 1; }

:is(.cd-state, .cd-run, .cd-geometry) .cd-ga { opacity: 0; transition: opacity .45s ease; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ga.is-on { opacity: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-draw { stroke-dasharray: 1 1; stroke-dashoffset: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-ga.is-on .cd-draw, :is(.cd-state, .cd-run, .cd-geometry) .cd-draw.is-on { stroke-dashoffset: 0; transition: stroke-dashoffset 1.1s cubic-bezier(.45, 0, .2, 1) .12s; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-red { fill: none; stroke: var(--_accent); stroke-width: 2; stroke-linecap: round; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-grey { fill: none; stroke: color-mix(in srgb, var(--_ink) 50%, var(--_bg)); stroke-width: 1.25; stroke-linecap: round; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-dash { fill: none; stroke: var(--_ink); stroke-width: 1.5; stroke-dasharray: 6 5; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-mask-line { fill: none; stroke: #FFFFFF; stroke-width: 10; stroke-linecap: round; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-hit { fill: none; stroke: var(--_accent); stroke-width: 2.5; }

/* plan view */
:is(.cd-state, .cd-run, .cd-geometry) .cd-plan-svg { display: block; width: 100%; max-width: 480px; height: auto; margin-top: 20px; overflow: visible; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-plan-svg .cd-p-t { font-size: 15px; fill: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-plan-svg .cd-p-strong { font-size: 16px; font-weight: 600; fill: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-axis { fill: none; stroke: color-mix(in srgb, var(--_ink) 44%, var(--_bg)); stroke-width: 1; stroke-dasharray: 4 4; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-ray { fill: none; stroke: color-mix(in srgb, var(--_ink) 44%, var(--_bg)); stroke-width: 1; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-decalplan { fill: color-mix(in srgb, var(--_accent) 18%, transparent); stroke: var(--_accent); stroke-width: 1.25; transition: fill .5s ease; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-cabplan { fill: var(--_ink); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-glassplan { fill: var(--_accent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-padplan { fill: var(--_accent-soft); stroke: var(--_accent); stroke-width: 1.25; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-player { fill: color-mix(in srgb, var(--_ink) 20%, var(--_bg)); transition: fill .5s ease; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-g-leaderplan { fill: none; stroke: color-mix(in srgb, var(--_ink) 44%, var(--_bg)); stroke-width: 1; }
.cd-geometry[data-step="decal"] [data-hi="decal"] { fill: color-mix(in srgb, var(--_accent) 40%, transparent); }
.cd-geometry[data-step="decal"] .cd-g-decal { fill: var(--_accent); }
.cd-geometry[data-step="pad"] [data-hi="pad"] { fill: color-mix(in srgb, var(--_ink) 45%, var(--_bg)); }

/* notes: the viewing positions are the controls */
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-foot {
  display: grid; gap: 32px 40px; margin-top: 36px;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.9fr);
  grid-template-areas: "plan viewers" "spec spec";
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-plan { grid-area: plan; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-viewers { grid-area: viewers; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-specs { grid-area: spec; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-plan .cd-small { margin-top: 6px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-list { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 6px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note {
  position: relative; display: grid; align-content: start; gap: 6px; width: 100%; height: 100%;
  padding: 16px 16px 16px 20px; border: 0; border-radius: 16px;
  background: transparent; color: var(--_ink);
  font: inherit; text-align: left; cursor: pointer;
  transition: background-color .3s ease;
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note::before {
  content: ""; position: absolute; left: 6px; top: 16px; bottom: 16px; width: 3px; border-radius: 2px;
  background: var(--_accent); transform: scaleY(0); transform-origin: top; transition: transform .45s var(--_ease);
}
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note:hover { background: color-mix(in srgb, var(--_card) 70%, transparent); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note.is-current { background: var(--_card); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note.is-current::before { transform: none; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note:focus-visible { outline: 2px solid var(--_ink); outline-offset: 2px; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note-t { font-size: 14.5px; font-weight: 600; line-height: 1.3; letter-spacing: -.01em; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note-d { font-size: 13px; line-height: 1.45; color: var(--_muted); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-spec { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px 32px; padding-top: 28px; border-top: 1px solid var(--_line); }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-spec-t { font-size: 14.5px; font-weight: 600; line-height: 1.3; }
:is(.cd-state, .cd-run, .cd-geometry) .cd-geo-spec-d { margin-top: 6px; font-size: 13px; line-height: 1.45; color: var(--_muted); }

@media (max-width: 1100px) {
  :is(.cd-state, .cd-run, .cd-geometry) .cd-geo-foot { grid-template-columns: minmax(0, 1fr); grid-template-areas: "viewers" "plan" "spec"; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-geo-spec { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  :is(.cd-state, .cd-run, .cd-geometry) .cd-geo-list, :is(.cd-state, .cd-run, .cd-geometry) .cd-geo-spec { grid-template-columns: minmax(0, 1fr); }
}

/* reduced motion: nothing travels, nothing draws in; states still change, instantly and calmly */
@media (prefers-reduced-motion: reduce) {
  :is(.cd-state, .cd-run, .cd-geometry) *, :is(.cd-state, .cd-run, .cd-geometry) *::before, :is(.cd-state, .cd-run, .cd-geometry) *::after { animation: none !important; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-trail.is-drawn, :is(.cd-state, .cd-run, .cd-geometry) .cd-ga.is-on .cd-draw, :is(.cd-state, .cd-run, .cd-geometry) .cd-draw.is-on { transition: none; }
  :is(.cd-state, .cd-run, .cd-geometry) .cd-spot, :is(.cd-state, .cd-run, .cd-geometry) .cd-axis i, :is(.cd-state, .cd-run, .cd-geometry) .cd-dot, :is(.cd-state, .cd-run, .cd-geometry) .cd-n-ring, :is(.cd-state, .cd-run, .cd-geometry) .cd-bar-fill, :is(.cd-state, .cd-run, .cd-geometry) .cd-geo-note::before { transition-duration: .01s !important; }
}
